    # Short-retention command audit -------------------------------------

    # mac-6m14: scrub common secret-bearing argv shapes before writing.
    _SECRET_KEY_HINTS = (
        "password",
        "passwd",
        "secret",
        "token",
        "apikey",
        "api_key",
        "api-key",
        "credential",
        "auth",
    )
    # High-entropy bare values: anything resembling a base64/hex blob of
    # ≥ 32 chars and not a path, URL, or numeric.
    _ARGV_BARE_HIGH_ENTROPY_RE = re.compile(r"^[A-Za-z0-9+/=_-]{32,}$")

    @classmethod
    def _scrub_argv(cls, argv: Iterable[str]) -> List[str]:
        """Replace secret-bearing argv elements with redaction markers.

        Common patterns:
          ``--token=abc123`` -> ``--token=<redacted>``
          ``--password sekret`` -> ``--password <redacted>`` (best-effort
            via key-then-value matching)
          ``ghp_abcdef...`` (bare 32+ char alphanum) -> ``<redacted>``
        """
        out: List[str] = []
        skip_next = False
        for raw in argv:
            item = str(raw)
            if skip_next:
                out.append("<redacted>")
                skip_next = False
                continue
            # --foo=bar where the key contains a secret hint
            if item.startswith("-") and "=" in item:
                key_part, _sep, value = item.partition("=")
                if any(hint in key_part.lower() for hint in cls._SECRET_KEY_HINTS) and value:
                    out.append("%s=<redacted>" % key_part)
                    continue
            # --foo  <value>: key flag followed by a separate value
            if item.startswith("-") and any(
                hint in item.lower() for hint in cls._SECRET_KEY_HINTS
            ):
                out.append(item)
                skip_next = True
                continue
            # Bare high-entropy values; skip URLs and absolute paths.
            if (
                cls._ARGV_BARE_HIGH_ENTROPY_RE.match(item)
                and "/" not in item
                and ":" not in item
                and not item.isdigit()
            ):
                out.append("<redacted>")
                continue
            out.append(item)
        return out

    def record_command_audit(
        self,
        agent_id: str,
        phase: str,
        argv: Iterable[str],
        cwd: str,
        command_id: Optional[str] = None,
        task_id: Optional[str] = None,
        lease_id: Optional[str] = None,
        started_at: Optional[str] = None,
        completed_at: Optional[str] = None,
        duration_ms: Optional[float] = None,
        returncode: Optional[int] = None,
        stdout_sha256: Optional[str] = None,
        stderr_sha256: Optional[str] = None,
        stdout_bytes: Optional[int] = None,
        stderr_bytes: Optional[int] = None,
        metadata: Optional[Dict[str, Any]] = None,
        retention_seconds: Optional[int] = None,
    ) -> CommandAuditRecord:
        self.get_agent(agent_id)
        phase_value = str(phase or "").strip().lower()
        if phase_value not in COMMAND_AUDIT_PHASES:
            raise ValidationError("unsupported command audit phase: %s" % phase)
        argv_raw = [str(item) for item in argv]
        if not argv_raw:
            raise ValidationError("command audit requires argv")
        # mac-6m14: scrub before persisting so secrets on argv never
        # land in command_audit or observability detail.
        argv_list = self._scrub_argv(argv_raw)
        cwd_value = str(cwd or "").strip()
        if not cwd_value:
            raise ValidationError("command audit requires cwd")
        if task_id:
            self.get_task(task_id)
        audit_id = new_id("cmda")
        cid = command_id or new_id("cmd")
        now = utcnow()
        detail = ensure_json_object(metadata or {})
        retention = self._command_audit_retention_seconds(retention_seconds)
        cutoff = (
            parse_time(now) - timedelta(seconds=retention)
        ).isoformat(timespec="microseconds")
        with self.store.transaction() as conn:
            conn.execute(
                """
                INSERT INTO command_audit (
                    id, command_id, agent_id, phase, argv, cwd, task_id, lease_id,
                    started_at, completed_at, duration_ms, returncode,
                    stdout_sha256, stderr_sha256, stdout_bytes, stderr_bytes,
                    metadata, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    audit_id,
                    cid,
                    agent_id,
                    phase_value,
                    json_dumps(argv_list),
                    cwd_value,
                    task_id,
                    lease_id,
                    started_at,
                    completed_at,
                    duration_ms,
                    returncode,
                    stdout_sha256,
                    stderr_sha256,
                    stdout_bytes,
                    stderr_bytes,
                    json_dumps(detail),
                    now,
                ),
            )
            self.action_events.project_command_audit(
                conn,
                audit_id=audit_id,
                command_id=cid,
                agent_id=agent_id,
                phase=phase_value,
                argv=argv_list,
                cwd=cwd_value,
                task_id=task_id,
                lease_id=lease_id,
                started_at=started_at,
                completed_at=completed_at,
                duration_ms=duration_ms,
                returncode=returncode,
                stdout_sha256=stdout_sha256,
                stderr_sha256=stderr_sha256,
                stdout_bytes=stdout_bytes,
                stderr_bytes=stderr_bytes,
                metadata=detail,
                timestamp=now,
            )
            conn.execute("DELETE FROM command_audit WHERE created_at < ?", (cutoff,))
            self.observability.insert_observation(
                conn,
                "log",
                "command.%s" % phase_value,
                "worker",
                agent_id,
                "error" if phase_value in {"failed", "timeout", "error"} else "info",
                None,
                "",
                "task" if task_id else "agent",
                task_id or agent_id,
                {
                    "command_id": cid,
                    "argv": argv_list,
                    "cwd": cwd_value,
                    "task_id": task_id,
                    "lease_id": lease_id,
                    "duration_ms": duration_ms,
                    "returncode": returncode,
                    **detail,
                },
                now,
            )
        return self.get_command_audit(audit_id)

    def get_command_audit(self, audit_id: str) -> CommandAuditRecord:
        row = self.store.query_one("SELECT * FROM command_audit WHERE id = ?", (audit_id,))
        if row is None:
            raise NotFoundError("command audit record not found: %s" % audit_id)
        return self._command_audit_from_row(row)

    def list_command_audit(
        self,
        agent_id: Optional[str] = None,
        task_id: Optional[str] = None,
        command_id: Optional[str] = None,
        phase: Optional[str] = None,
        since: Optional[str] = None,
        until: Optional[str] = None,
        limit: int = 200,
    ) -> List[CommandAuditRecord]:
        self.prune_command_audit()
        clauses: List[str] = []
        params: List[Any] = []
        if agent_id is not None:
            clauses.append("agent_id = ?")
            params.append(agent_id)
        if task_id is not None:
            clauses.append("task_id = ?")
            params.append(task_id)
        if command_id is not None:
            clauses.append("command_id = ?")
            params.append(command_id)
        if phase is not None:
            phase_value = str(phase).strip().lower()
            if phase_value not in COMMAND_AUDIT_PHASES:
                raise ValidationError("unsupported command audit phase: %s" % phase)
            clauses.append("phase = ?")
            params.append(phase_value)
        if since is not None:
            clauses.append("created_at >= ?")
            params.append(since)
        if until is not None:
            clauses.append("created_at <= ?")
            params.append(until)
        sql = "SELECT * FROM command_audit"
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY created_at DESC, id DESC LIMIT ?"
        params.append(min(max(1, int(limit)), 1000))
        return [
            self._command_audit_from_row(row)
            for row in self.store.query_all(sql, tuple(params))
        ]

    def prune_command_audit(self, older_than: Optional[str] = None) -> int:
        cutoff = older_than
        if cutoff is None:
            now = utcnow()
            retention = self._command_audit_retention_seconds(None)
            cutoff = (
                parse_time(now) - timedelta(seconds=retention)
            ).isoformat(timespec="microseconds")
        cursor = self.store.execute(
            "DELETE FROM command_audit WHERE created_at < ?", (cutoff,)
        )
        return int(cursor.rowcount or 0)

    def _command_audit_retention_seconds(self, override: Optional[int]) -> int:
        if override is not None:
            return max(60, int(override))
        raw = os.environ.get("MAC_COMMAND_AUDIT_RETENTION_SECONDS")
        if raw:
            return max(60, int(raw))
        return 24 * 60 * 60

    # ------------------------------------------------------------------
    # Evidence-reuse decision records
    #
    # Durable audit trail of prior-executor-evidence reuse decisions made
    # by recovery logic when review infrastructure fails. See
    # ``mac.evidence_reuse_verifier`` for the fail-closed verifier whose
    # structured result is persisted here.
    # ------------------------------------------------------------------
    def record_evidence_reuse(
        self,
        task_id: str,
        source_evidence_id: str,
        reused: bool,
        *,
        verification: Optional[Mapping[str, Any]] = None,
        problems: Optional[Iterable[str]] = None,
        remote_url: Optional[str] = None,
        expected_head_sha: Optional[str] = None,
        decided_by: str = "control-plane",
        reused_by_agent_id: Optional[str] = None,
        reuse_context: str = "",
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> EvidenceReuseRecord:
        """Persist one evidence-reuse decision and return the stored record.

        ``task_id`` must reference an existing task. ``verification`` is the
        serialised structured result (e.g. ``ReuseVerificationResult.to_dict``)
        that backed the decision; ``problems`` is the convenience list of
        human-readable failure descriptions when reuse was refused.
        """
        self.get_task(task_id)
        source_id = str(source_evidence_id or "").strip()
        if not source_id:
            raise ValidationError("evidence reuse requires source_evidence_id")
        verification_payload = ensure_json_object(verification or {})
        if problems is None:
            raw_problems = verification_payload.get("problems")
            problem_list = [str(p) for p in raw_problems] if isinstance(raw_problems, list) else []
        else:
            problem_list = [str(p) for p in problems]
        decided = str(decided_by or "").strip() or "control-plane"
        # Reuse provenance: default the acting agent to the deciding identity
        # when the caller does not name one explicitly.
        reused_by = str(reused_by_agent_id or "").strip() or decided
        context = str(reuse_context or "").strip()
        metadata_payload = ensure_json_object(metadata or {})
        record_id = new_id("evreuse")
        now = utcnow()
        self.store.execute(
            """
            INSERT INTO evidence_reuse_records (
                id, task_id, source_evidence_id, remote_url, expected_head_sha,
                reused, verification, problems, decided_by, created_at,
                reused_by_agent_id, reuse_context, metadata
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                record_id,
                task_id,
                source_id,
                remote_url,
                expected_head_sha,
                1 if reused else 0,
                json_dumps(verification_payload),
                json_dumps(problem_list),
                decided,
                now,
                reused_by,
                context,
                json_dumps(metadata_payload),
            ),
        )
        self._record_history(
            task_id,
            "evidence.reuse_recorded",
            reused_by,
            None,
            None,
            {
                "record_id": record_id,
                "source_evidence_id": source_id,
                "prior_evidence_id": source_id,
                "reused": bool(reused),
                "reuse_context": context,
                "decided_by": decided,
            },
        )
        return self.get_evidence_reuse(record_id)

    def get_evidence_reuse(self, record_id: str) -> EvidenceReuseRecord:
        row = self.store.query_one(
            "SELECT * FROM evidence_reuse_records WHERE id = ?", (record_id,)
        )
        if row is None:
            raise NotFoundError("evidence reuse record not found: %s" % record_id)
        return self._evidence_reuse_from_row(row)

    def list_evidence_reuse(
        self,
        task_id: Optional[str] = None,
        source_evidence_id: Optional[str] = None,
        reused: Optional[bool] = None,
        limit: int = 200,
    ) -> List[EvidenceReuseRecord]:
        clauses: List[str] = []
        params: List[Any] = []
        if task_id is not None:
            clauses.append("task_id = ?")
            params.append(task_id)
        if source_evidence_id is not None:
            clauses.append("source_evidence_id = ?")
            params.append(source_evidence_id)
        if reused is not None:
            clauses.append("reused = ?")
            params.append(1 if reused else 0)
        sql = "SELECT * FROM evidence_reuse_records"
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY created_at DESC, id DESC LIMIT ?"
        params.append(min(max(1, int(limit)), 1000))
        return [
            self._evidence_reuse_from_row(row)
            for row in self.store.query_all(sql, tuple(params))
        ]

    def _evidence_reuse_from_row(self, row: Any) -> EvidenceReuseRecord:
        keys = row.keys() if hasattr(row, "keys") else ()
        return EvidenceReuseRecord(
            row["id"],
            row["task_id"],
            row["source_evidence_id"],
            row["remote_url"],
            row["expected_head_sha"],
            bool(row["reused"]),
            json_loads(row["verification"], {}),
            json_loads(row["problems"], []),
            row["decided_by"],
            row["created_at"],
            row["reused_by_agent_id"] if "reused_by_agent_id" in keys else "",
            row["reuse_context"] if "reuse_context" in keys else "",
            json_loads(row["metadata"], {}) if "metadata" in keys else {},
        )

    def get_evidence_reuse_records(self, task_id: str) -> List[EvidenceReuseRecord]:
        """Return every evidence-reuse record for ``task_id`` (oldest first)."""
        self.get_task(task_id)
        return [
            self._evidence_reuse_from_row(row)
            for row in self.store.query_all(
                "SELECT * FROM evidence_reuse_records WHERE task_id = ?"
                " ORDER BY created_at, id",
                (task_id,),
            )
        ]

    def list_dead_letters(
        self,
        tenant_id: Optional[str] = None,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> List[Task]:
        return self.list_dead_letters_page(
            tenant_id=tenant_id,
            limit=limit,
            cursor=cursor,
        )["tasks"]

    def list_dead_letters_page(
        self,
        tenant_id: Optional[str] = None,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> JsonDict:
        limit_value = max(1, min(int(limit), 1000))
        clauses = ["state = ?", "attempt_count >= max_attempts"]
        params: List[Any] = [TaskState.FAILED.value]
        if tenant_id is not None:
            clauses.append(
                "COALESCE("
                "NULLIF(json_extract(metadata, '$.origin.tenant_id'), ''), "
                "NULLIF(json_extract(metadata, '$.tenant_id'), '')"
                ") = ?"
            )
            params.append(tenant_id)
        decoded = self._decode_scan_cursor(cursor, "dead-letters")
        if decoded is not None:
            updated_at, task_id = decoded
            clauses.append("(updated_at > ? OR (updated_at = ? AND id > ?))")
            params.extend([updated_at, updated_at, task_id])
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s "
            "ORDER BY updated_at, id LIMIT ?" % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        tasks = [self._task_from_row(row) for row in rows[:limit_value]]
        next_cursor = (
            self._encode_scan_cursor(
                "dead-letters",
                tasks[-1].updated_at,
                tasks[-1].id,
            )
            if has_more and tasks
            else None
        )
        return {
            "tasks": tasks,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _encode_scan_cursor(self, kind: str, position: str, item_id: str) -> str:
        payload = json_dumps(
            {"kind": kind, "position": position, "item_id": item_id}
        ).encode("utf-8")
        encoded = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")
        return "v1:%s" % encoded

    def _decode_scan_cursor(
        self,
        cursor: Optional[str],
        kind: str,
    ) -> Optional[Tuple[str, str]]:
        if cursor is None:
            return None
        raw = str(cursor).strip()
        if not raw.startswith("v1:"):
            raise ValidationError("invalid %s cursor" % kind)
        encoded = raw[3:]
        try:
            padding = "=" * (-len(encoded) % 4)
            payload = json_loads(
                base64.urlsafe_b64decode((encoded + padding).encode("ascii")).decode(
                    "utf-8"
                ),
                {},
            )
            payload_kind = str(payload["kind"])
            position = str(payload["position"])
            item_id = str(payload["item_id"])
        except (binascii.Error, KeyError, TypeError, ValueError, UnicodeError):
            raise ValidationError("invalid %s cursor" % kind) from None
        if payload_kind != kind or not position or not item_id:
            raise ValidationError("invalid %s cursor" % kind)
        return position, item_id

    def close_task(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        drain_outbox: bool = True,
    ) -> Task:
        """Operator boundary for an ordinary task's terminal close.

        Worker-authored transitions belong to :meth:`transition_task` and are
        fenced to an exact active lease.  This separate public operation is
        for an authenticated operator that has already been authorized by the
        transport (or for an explicitly selected local authority).  It is
        deliberately limited to the two ``task close`` outcomes; package-
        linked tasks remain protected by the generic lifecycle guard in
        :meth:`_transition_task_impl` and must advance through their package
        controller instead.
        """

        target = _state_value(target_state)
        if target not in {
            TaskState.COMPLETED.value,
            TaskState.CANCELLED.value,
        }:
            raise ValidationError(
                "operator close only supports completed or cancelled"
            )
        return self._transition_task_impl(
            task_id,
            target,
            actor,
            detail,
            lease_id=None,
            trusted_internal=True,
            drain_outbox=drain_outbox,
            conn=None,
        )

    def transition_task(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        lease_id: Optional[str] = None,
        drain_outbox: bool = True,
    ) -> Task:
        return self._transition_task_impl(
            task_id,
            target_state,
            actor,
            detail,
            lease_id=lease_id,
            trusted_internal=False,
            drain_outbox=drain_outbox,
            conn=None,
        )

    def _transition_task_internal(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        drain_outbox: bool = True,
    ) -> Task:
        """Trusted service-only transition path.

        Public callers must use :meth:`transition_task`, whose active-task
        writes require an exact lease fence.  Internal services may use this
        private entry point only after performing their own authority check
        (for example ``start_task`` validates owner/delegate plus lease first).
        """
        return self._transition_task_impl(
            task_id,
            target_state,
            actor,
            detail,
            lease_id=None,
            trusted_internal=True,
            drain_outbox=drain_outbox,
            conn=None,
        )

    def _transition_task_in_transaction(
        self,
        conn: Any,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
    ) -> Task:
        return self._transition_task_impl(
            task_id,
            target_state,
            actor,
            detail,
            lease_id=None,
            trusted_internal=True,
            drain_outbox=False,
            conn=conn,
        )

    def _transition_task_impl(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        lease_id: Optional[str],
        trusted_internal: bool,
        drain_outbox: bool,
        conn: Optional[Any],
    ) -> Task:
        target = _state_value(target_state)
        if conn is None:
            task = self.get_task(task_id)
        else:
            task_row = conn.execute(
                "SELECT * FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if task_row is None:
                raise NotFoundError("task not found: %s" % task_id)
            task = self._task_from_row(task_row)
        # ``get_task`` accepts unambiguous display prefixes.  Every write and
        # related-record lookup below must use the canonical id it resolved;
        # otherwise the initial read succeeds but the UPDATE/history/outbox
        # writes target the non-existent prefix.
        task_id = task.id
        package_link = (
            conn.execute(
                "SELECT package_id FROM work_package_task_links WHERE task_id = ?",
                (task_id,),
            ).fetchone()
            if conn is not None
            else self.store.query_one(
                "SELECT package_id FROM work_package_task_links WHERE task_id = ?",
                (task_id,),
            )
        )
        if package_link is not None and target not in {
            TaskState.RUNNING.value,
            TaskState.NEEDS_REVIEW.value,
        }:
            self._require_non_package_task_mutation(
                task_id,
                operation="generic transition to %s" % target,
                conn=conn,
            )
        # Worker-authored lifecycle writes are fenced to the exact active lease
        # attempt. Without this check, an old process for lease A can mutate a
        # task after the same agent has reacquired it as lease B (the classic
        # ABA failure). It also prevents any bound agent from using the generic
        # endpoint to mutate an unowned OPEN/review/terminal task. Operators,
        # dispatchers, and reviewers use explicit trusted service paths.
        fenced_lease_id: Optional[str] = None
        if not trusted_internal:
            if task.state not in {
                TaskState.CLAIMED.value,
                TaskState.RUNNING.value,
            }:
                raise AuthorizationError(
                    "worker task transitions require ownership of an active lease"
                )
            self._require_exact_lease_actor(task, actor, lease_id)
            fenced_lease_id = str(lease_id or "").strip()
        transition_detail = dict(detail or {})
        if target == TaskState.BLOCKED.value:
            transition_detail = _normalize_blocked_detail(transition_detail)
        diagnosis_record = _structured_failure_diagnosis(
            target,
            transition_detail,
            actor=actor,
            attempt_count=task.attempt_count,
        )
        if diagnosis_record is not None:
            existing_diagnosis = transition_detail.get("diagnosis")
            if existing_diagnosis not in (None, "", {}, diagnosis_record):
                diagnosis_record["reported_diagnosis"] = str(existing_diagnosis)[:1000]
            transition_detail["diagnosis"] = diagnosis_record
        if target == TaskState.CANCELLED.value:
            # Resolve replacement_task_id prefix before normalization so that
            # normalize_cancellation_detail receives a canonical full ID.
            # AmbiguousIdError and NotFoundError propagate without state change.
            _raw_replacement = str(
                (dict(transition_detail) if transition_detail else {}).get(
                    "replacement_task_id"
                ) or ""
            ).strip()
            if _raw_replacement:
                _resolved_replacement = self._resolve_task_id(_raw_replacement)
                if _resolved_replacement != _raw_replacement:
                    transition_detail = dict(transition_detail)
                    transition_detail["replacement_task_id"] = _resolved_replacement
            transition_detail = normalize_cancellation_detail(transition_detail)
            # Write guard: reject cancellations that point at a terminal or held
            # replacement task unless the caller has explicitly set archival_override.
            disposition = str(transition_detail.get("disposition") or "").strip().lower()
            if disposition in {"superseded", "duplicate"}:
                replacement_id = str(
                    transition_detail.get("replacement_task_id") or ""
                ).strip()
                archival_override = bool(transition_detail.get("archival_override", False))
                validate_replacement_target(
                    replacement_id,
                    self.get_task,
                    archival_override=archival_override,
                )
                if archival_override:
                    # Record archival_override in lifecycle metadata for audit.
                    transition_detail["archival_override_recorded"] = True
        detail = transition_detail
        if task.state == target:
            # A terminal cancellation may be re-submitted solely to backfill or
            # correct its repository-ref disposition. Keep the original
            # terminal timestamp so this cannot reset the grace period.
            if target != TaskState.CANCELLED.value:
                return task
            lifecycle = repository_ref_lifecycle_for_transition(
                target,
                detail,
                now=task.completed_at or utcnow(),
            )
            metadata = ensure_json_object(task.metadata)
            if metadata.get("repository_ref_lifecycle") == lifecycle:
                if drain_outbox and conn is None:
                    self.drain_task_transition_outbox(task_id=task_id, limit=20)
                return task
            metadata["repository_ref_lifecycle"] = lifecycle
            now = utcnow()

            def apply_lifecycle(transaction: Any) -> None:
                transaction.execute(
                    "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                    (json_dumps(metadata), now, task_id),
                )
                self._record_history(
                    task_id,
                    "repository_ref.lifecycle_updated",
                    actor,
                    target,
                    target,
                    detail,
                    conn=transaction,
                )
                self.task_ledger.enqueue_outbox(
                    transaction,
                    task_id=task_id,
                    event_type="task.lifecycle",
                    actor=actor,
                    from_state=target,
                    to_state=target,
                    detail=detail,
                    created_at=now,
                )
            if conn is None:
                with self.store.transaction() as transaction:
                    apply_lifecycle(transaction)
                if drain_outbox:
                    self.drain_task_transition_outbox(task_id=task_id, limit=20)
                return self.get_task(task_id)
            apply_lifecycle(conn)
            transitioned_row = conn.execute(
                "SELECT * FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if transitioned_row is None:
                raise NotFoundError("task not found: %s" % task_id)
            return self._task_from_row(transitioned_row)
        validate_transition(task.state, target)
        review_ready_evidence: Optional[Evidence] = None
        if target == TaskState.NEEDS_REVIEW.value:
            review_ready_evidence = self._require_review_ready(task)
        if target == TaskState.COMPLETED.value and not self.reviews.completion_authorized(task_id):
            raise ValidationError("task completion requires approved review and evidence")
        if target == TaskState.COMPLETED.value:
            self._require_canonical_integration_proof(task)
        now = utcnow()
        updated_metadata: Optional[JsonDict] = None
        candidate_metadata = ensure_json_object(task.metadata)
        metadata_changed = False
        if diagnosis_record is not None:
            diagnosis_summary = _failure_diagnosis(target, detail) or diagnosis_record["problem"]
            activity = candidate_metadata.get("activity")
            if not isinstance(activity, list):
                activity = []
            activity.append(
                {
                    "phase": "diagnosis",
                    "actor": str(actor or "")[:120],
                    "summary": str(diagnosis_summary)[:1200],
                    "detail": diagnosis_record,
                    "at": utcnow(),
                }
            )
            candidate_metadata["activity"] = activity[-24:]
            metadata_changed = True
        if review_ready_evidence is not None:
            candidate_metadata["review_target"] = {
                "executor_evidence_id": review_ready_evidence.id,
                "attempt_count": task.attempt_count,
                "recorded_at": now,
            }
            metadata_changed = True
        elif target in {
            TaskState.OPEN.value,
            TaskState.WAITING.value,
            TaskState.BLOCKED.value,
            TaskState.RUNNING.value,
            TaskState.FAILED.value,
            TaskState.CANCELLED.value,
        }:
            if candidate_metadata.pop("review_target", None) is not None:
                metadata_changed = True
        repository_ref_lifecycle = repository_ref_lifecycle_for_transition(
            target,
            detail,
            now=now,
        )
        if repository_ref_lifecycle is not None:
            if candidate_metadata.get("repository_ref_lifecycle") != repository_ref_lifecycle:
                candidate_metadata["repository_ref_lifecycle"] = repository_ref_lifecycle
                metadata_changed = True
        if metadata_changed:
            updated_metadata = candidate_metadata
        owner_agent_id = task.owner_agent_id
        lease_id = task.lease_id
        leased_until = task.leased_until
        release_lease_id = None
        if target in {
            TaskState.WAITING.value,
            TaskState.BLOCKED.value,
            TaskState.OPEN.value,
            TaskState.NEEDS_REVIEW.value,
            TaskState.FAILED.value,
            TaskState.CANCELLED.value,
        }:
            release_lease_id = lease_id
            owner_agent_id = None
            lease_id = None
            leased_until = None
        # mac-d2xh: a dead-letter requeue (FAILED→OPEN or CANCELLED→OPEN)
        # must reset attempt_count and clear completed_at; otherwise the
        # next claim immediately fails the cap check (attempt_count >=
        # max_attempts) and the requeue is a no-op.
        is_requeue_from_terminal = (
            task.state in {TaskState.FAILED.value, TaskState.CANCELLED.value}
            and target == TaskState.OPEN.value
        )

        def apply_transition(conn: Any) -> None:
            if fenced_lease_id:
                self._require_exact_lease_actor_in_transaction(
                    conn,
                    task_id=task_id,
                    agent_id=actor,
                    lease_id=fenced_lease_id,
                    allowed_states=(task.state,),
                )
            if release_lease_id:
                conn.execute(
                    "UPDATE leases SET status = ?, updated_at = ? WHERE id = ? AND status = ?",
                    (LeaseStatus.RELEASED.value, now, release_lease_id, LeaseStatus.ACTIVE.value),
                )
                self._consume_break_glass_authorizations(
                    conn,
                    task_id=task_id,
                    lease_id=release_lease_id,
                    now=now,
                )
            if is_requeue_from_terminal:
                transition_where = "WHERE id = ? AND state = ?"
                transition_guards: List[Any] = [task_id, task.state]
                if fenced_lease_id:
                    transition_where += " AND lease_id = ?"
                    transition_guards.append(fenced_lease_id)
                changed = conn.execute(
                    """
                    UPDATE tasks
                    SET state = ?, owner_agent_id = ?, lease_id = ?, leased_until = ?,
                        started_at = NULL, completed_at = NULL,
                        attempt_count = 0, updated_at = ?
                    """ + transition_where,
                    tuple(
                        [
                        target,
                        owner_agent_id,
                        lease_id,
                        leased_until,
                        now,
                        ]
                        + transition_guards
                    ),
                )
            else:
                transition_where = "WHERE id = ? AND state = ?"
                transition_guards = [task_id, task.state]
                if fenced_lease_id:
                    transition_where += " AND lease_id = ?"
                    transition_guards.append(fenced_lease_id)
                changed = conn.execute(
                    """
                    UPDATE tasks
                    SET state = ?, owner_agent_id = ?, lease_id = ?, leased_until = ?,
                        started_at = ?, completed_at = ?, updated_at = ?
                    """ + transition_where,
                    tuple(
                        [
                        target,
                        owner_agent_id,
                        lease_id,
                        leased_until,
                        now if target == TaskState.RUNNING.value and not task.started_at else task.started_at,
                        now if target in TERMINAL_TASK_STATES and not task.completed_at else task.completed_at,
                        now,
                        ]
                        + transition_guards
                    ),
                )
            if changed.rowcount != 1:
                raise TransitionError("task state changed during transition; retry")
            if updated_metadata is not None:
                conn.execute(
                    "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                    (json_dumps(updated_metadata), now, task_id),
                )
            if task.owner_agent_id and target in TERMINAL_TASK_STATES.union(
                {
                    TaskState.WAITING.value,
                    TaskState.BLOCKED.value,
                    TaskState.OPEN.value,
                    TaskState.NEEDS_REVIEW.value,
                }
            ):
                self._set_agent_idle(task.owner_agent_id, conn=conn)
            self._record_history(
                task_id, "task.transitioned", actor, task.state, target, detail or {}, conn=conn
            )
            self.task_ledger.enqueue_outbox(
                conn,
                task_id=task_id,
                event_type="task.lifecycle",
                actor=actor,
                from_state=task.state,
                to_state=target,
                detail=detail or {},
                created_at=now,
            )
            if target in TERMINAL_TASK_STATES.union({TaskState.BLOCKED.value}):
                row = conn.execute(
                    "SELECT workflow_run_id FROM tasks WHERE id = ?", (task_id,)
                ).fetchone()
                if row is not None and row["workflow_run_id"]:
                    self.task_ledger.enqueue_outbox(
                        conn,
                        task_id=task_id,
                        event_type="workflow.advance",
                        actor=actor,
                        from_state=task.state,
                        to_state=target,
                        detail=detail or {},
                        created_at=now,
                    )
        if conn is None:
            with self.store.transaction() as transaction:
                apply_transition(transaction)
        else:
            apply_transition(conn)
            transitioned_row = conn.execute(
                "SELECT * FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if transitioned_row is None:
                raise NotFoundError("task not found: %s" % task_id)
            return self._task_from_row(transitioned_row)
        if drain_outbox:
            self.drain_task_transition_outbox(task_id=task_id, limit=20)
        transitioned = self.get_task(task_id)
        if target in {TaskState.FAILED.value, TaskState.CANCELLED.value}:
            self._resolve_waiting_dependents_of(task_id, target, actor)
        return transitioned

    def _terminal_dependency_replacement(self, dep_id: str) -> Optional[str]:
        """Return a live replacement recorded on a terminal prerequisite.

        Cancellation normalisation already validates a superseding replacement
        at write time. Re-check its current liveness here because a replacement
        may have become terminal between the prerequisite transition and this
        dependent reconciliation.
        """
        try:
            dependency = self.get_task(dep_id)
        except NotFoundError:
            return None
        lifecycle = ensure_json_object(dependency.metadata).get(
            "repository_ref_lifecycle"
        )
        replacement_id = str(
            ensure_json_object(lifecycle).get("replacement_task_id") or ""
        ).strip()
        if not replacement_id:
            return None
        try:
            replacement = self.get_task(replacement_id)
        except NotFoundError:
            return None
        if replacement.state in {TaskState.FAILED.value, TaskState.CANCELLED.value}:
            return None
        if bool(ensure_json_object(replacement.metadata).get("no_dispatch")):
            return None
        return replacement.id

    def _resolve_waiting_dependents_of(self, dep_id: str, dep_state: str, actor: str) -> None:
        """Reconcile waiting dependents of a terminal prerequisite.

        A terminal prerequisite cannot satisfy a waiting dependency edge.  The
        old behaviour recursively marked every dependent as ``failed``; that
        converted one root failure into a large, misleading execution-failure
        count.  A durable replacement is instead substituted into each edge.
        When none exists, the dependent is explicitly cancelled with its
        terminal-dependency provenance, preserving an auditable decision without
        claiming the dependent itself executed and failed.

        This remains best-effort: a reconciliation error must never invalidate
        the triggering terminal transition.
        """
        replacement_id = self._terminal_dependency_replacement(dep_id)
        try:
            rows = self.store.query_all(
                "SELECT id FROM tasks WHERE state = ? AND dependencies LIKE ?",
                (TaskState.WAITING.value, "%" + dep_id + "%"),
            )
        except Exception:  # noqa: BLE001 - propagation must not break the transition
            return
        for row in rows or []:
            dependent_id = row["id"]
            try:
                dependent = self.get_task(dependent_id)
            except NotFoundError:
                continue
            # LIKE is a substring match — confirm a real dependency edge, and
            # that the dependent is still WAITING (a concurrent transition may
            # have moved it).
            if dep_id not in dependent.dependencies:
                continue
            if dependent.state != TaskState.WAITING.value:
                continue
            if self.store.query_one(
                "SELECT package_id FROM work_package_task_links WHERE task_id = ?",
                (dependent_id,),
            ) is not None:
                # A package node's dependency and cancellation decisions are
                # part of the immutable graph/epoch transaction.  The legacy
                # best-effort reconciler must not rewrite just the task row.
                try:
                    self.record_log(
                        "work_package.dependency_reconciliation_deferred",
                        level="warning",
                        detail={
                            "dependent": dependent_id,
                            "dependency": dep_id,
                            "dependency_state": dep_state,
                        },
                    )
                except Exception:  # noqa: BLE001 - diagnostic only
                    pass
                continue
            try:
                if replacement_id:
                    self.update_task(
                        dependent_id,
                        dependencies=[
                            replacement_id if item == dep_id else item
                            for item in dependent.dependencies
                        ],
                        actor="dependency-reconciliation",
                    )
                else:
                    self._transition_task_internal(
                        dependent_id,
                        TaskState.CANCELLED.value,
                        "dependency-reconciliation",
                        {
                            "reason": "dependency_terminated",
                            "disposition": "preserve",
                            "failed_dependency": dep_id,
                            "dependency_state": dep_state,
                            "manual_repair_required": True,
                        },
                    )
            except Exception as exc:  # noqa: BLE001 - one dependent must not stop the rest
                try:
                    self.record_log(
                        "task.dependency_propagation_failed",
                        level="warning",
                        detail={"dependent": dependent_id, "dependency": dep_id, "error": str(exc)},
                    )
                except Exception:  # noqa: BLE001
                    pass

    def reopen_task(
        self,
        task_id: str,
        actor: str,
        reason: Optional[str] = None,
    ) -> Task:
        """Recovery action: return a stuck/terminal task to OPEN so it can be
        retried or reconciled.

        Valid from ``failed``/``cancelled`` (resets ``attempt_count`` and clears
        ``completed_at`` so the requeue isn't immediately re-exhausted) and from
        ``blocked``; the state machine rejects reopening an already-``completed``
        task. Records who reopened it and why. Counterpart to
        :meth:`force_complete_task`.
        """
        task = self.get_task(task_id)
        self._require_non_package_task_mutation(
            task.id,
            operation="operator reopen",
        )
        detail: Dict[str, Any] = {"via": "operator_reopen"}
        if reason:
            detail["reason"] = reason
        return self._transition_task_internal(
            task.id, TaskState.OPEN.value, actor, detail
        )

    def force_complete_task(
        self,
        task_id: str,
        actor: str,
        reason: Optional[str] = None,
    ) -> Task:
        """Operator override: mark a task COMPLETED regardless of its current
        state or review status.

        For reconciling work done out-of-band (e.g. a task whose change merged
        via a PR) or recovering a task stranded in a terminal state where the
        normal review→publish path can no longer run. This deliberately bypasses
        the review/evidence completion gate, so it records who forced it, the
        prior state, and why. Recovery counterpart to :meth:`reopen_task`.
        """
        task = self.get_task(task_id)
        # get_task accepts unambiguous display prefixes, but every mutation and
        # foreign-keyed audit row must use the canonical full identifier.
        task_id = task.id
        self._require_non_package_task_mutation(
            task_id,
            operation="operator force-complete",
        )
        if task.state == TaskState.COMPLETED.value:
            return task
        self._require_canonical_integration_proof(task)
        now = utcnow()
        detail: Dict[str, Any] = {"via": "operator_force_complete", "from_state": task.state}
        if reason:
            detail["reason"] = reason
        metadata = ensure_json_object(task.metadata)
        metadata["repository_ref_lifecycle"] = repository_ref_lifecycle_for_transition(
            TaskState.COMPLETED.value,
            detail,
            now=now,
        )
        with self.store.transaction() as conn:
            if task.lease_id:
                conn.execute(
                    "UPDATE leases SET status = ?, updated_at = ? WHERE id = ? AND status = ?",
                    (LeaseStatus.RELEASED.value, now, task.lease_id, LeaseStatus.ACTIVE.value),
                )
                self._consume_break_glass_authorizations(
                    conn,
                    task_id=task.id,
                    lease_id=task.lease_id,
                    now=now,
                )
            if task.owner_agent_id:
                self._set_agent_idle(task.owner_agent_id, conn=conn)
            conn.execute(
                """
                UPDATE tasks
                SET state = ?, owner_agent_id = NULL, lease_id = NULL, leased_until = NULL,
                    completed_at = COALESCE(completed_at, ?), metadata = ?, updated_at = ?
                WHERE id = ?
                """,
                (TaskState.COMPLETED.value, now, json_dumps(metadata), now, task_id),
            )
            self._record_history(
                task_id,
                "task.force_completed",
                actor,
                task.state,
                TaskState.COMPLETED.value,
                detail,
                conn=conn,
            )
            self.task_ledger.enqueue_outbox(
                conn,
                task_id=task_id,
                event_type="task.lifecycle",
                actor=actor,
                from_state=task.state,
                to_state=TaskState.COMPLETED.value,
                detail=detail,
                created_at=now,
            )
        self.drain_task_transition_outbox(task_id=task_id, limit=20)
        return self.get_task(task_id)

    @staticmethod
    def _repository_contract_for_task(task: Task) -> JsonDict:
        """Return the repository contract carried by a repository task."""
        metadata = ensure_json_object(task.metadata)
        if metadata_declares_report_deliverable(metadata):
            # Reports may inspect an exact repository base, but no code is
            # integrated. Their reviewed operator_result is the completion
            # proof; canonical Git integration is categorically inapplicable.
            return {}
        execution = ensure_json_object(metadata.get("execution_contract"))
        origin = ensure_json_object(metadata.get("origin"))
        contract = ensure_json_object(execution.get("repository_contract"))
        if not contract:
            contract = ensure_json_object(origin.get("repository_contract"))
        if str(execution.get("type") or "").strip().lower() != "repository":
            return {}
        return contract

    def _require_canonical_integration_proof(self, task: Task) -> None:
        """Refuse repository completion until a guarded canonical push is durable.

        An approved review proves that an executor attempt was acceptable; it
        does not prove that the reviewed ref survived parallel integration.
        The deterministic finalizer records ``canonical_integration`` only
        after its guarded push has verified the canonical branch remotely.
        Require that record on both ordinary and operator completion paths.
        """
        contract = self._repository_contract_for_task(task)
        if not contract:
            return
        canonical_branch = str(contract.get("canonical_branch") or "main").strip()
        canonical_ref = "refs/heads/%s" % canonical_branch
        for evidence in reversed(self.list_evidence(task.id)):
            metadata = ensure_json_object(evidence.metadata)
            manifest = ensure_json_object(metadata.get("verification")) or metadata
            repo = ensure_json_object(manifest.get("repo"))
            integration = ensure_json_object(manifest.get("canonical_integration"))
            head_sha = str(repo.get("head_sha") or "").strip()
            proof_sha = str(
                integration.get("canonical_tip_sha") or integration.get("head_sha") or ""
            ).strip()
            reviewed_sha = str(integration.get("reviewed_head_sha") or "").strip()
            proof_carries_reviewed_head = (
                _GIT_SHA_RE.match(reviewed_sha)
                and reviewed_sha == head_sha
                and integration.get("contains_reviewed_head") is True
            )
            if (
                str(integration.get("status") or "").strip().lower() in {"pass", "passed"}
                and integration.get("remote_verified") is True
                and str(integration.get("canonical_ref") or "").strip() == canonical_ref
                and _GIT_SHA_RE.match(head_sha)
                and _GIT_SHA_RE.match(proof_sha)
                and (head_sha == proof_sha or proof_carries_reviewed_head)
            ):
                return
        raise ValidationError(
            "repository task completion requires durable canonical integration proof "
            "(canonical_integration.status=pass, remote_verified=true, and a "
            "matching canonical branch SHA)"
        )

    def claim_task(
        self,
        task_id: str,
        agent_id: str,
        lease_seconds: int = 900,
        *,
        sync_beads: bool = True,
        allow_cooperative_reuse: bool = False,
        assignment_allocator: str = "control-plane",
        assignment_allocator_version: Optional[str] = None,
        assignment_score: Optional[float] = None,
        assignment_rationale: Optional[str] = None,
        assignment_decision: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[Task, Lease]:
        lease_seconds = self._validated_task_lease_seconds(lease_seconds)
        task = self.get_task(task_id)
        task_id = task.id
        agent = self._require_live_agent(agent_id)
        if (
            task.state in {TaskState.WAITING.value, TaskState.BLOCKED.value}
            and task.dependencies
            and self._dependencies_satisfied(task)
            and not self._blocked_task_requires_manual_repair(task)
        ):
            task = self._prepare_cooperative_integration_task(task)
            task = self._transition_task_internal(
                task_id,
                TaskState.OPEN.value,
                "dispatcher",
                {"reason": "dependencies satisfied"},
            )
        if task.state != TaskState.OPEN.value:
            raise TransitionError("only open tasks can be claimed")
        self._assert_work_package_claim_downstream_ready(task.id)
        # mac-1g3u: the tenant gate also runs as an explicit chokepoint
        # in claim_task itself, not only through _agent_available_for.
        # A future dispatch path that forgets the broader eligibility
        # check still hits this assertion because every claim must go
        # through claim_task. The richer Python policy lives in
        # _machine_allows_tenant; this is the redundant safety belt.
        machine = self.get_machine(agent.machine_id)
        task_tenant = self._task_tenant_id(task)
        if not self._machine_allows_tenant(machine, task_tenant):
            raise AuthorizationError(
                "machine %s tenant policy refuses tenant %s for task %s"
                % (machine.id, task_tenant, task_id)
            )
        # Candidate availability is an advisory fast path only. Always call it
        # so dispatch telemetry and test barriers observe the preflight, but do
        # not let a replica-local clock or stale mutable snapshot make the
        # authorization decision. The locked snapshot below is authoritative.
        self._agent_available_for(
            agent, task, allow_cooperative_reuse=allow_cooperative_reuse
        )
        if task.attempt_count >= task.max_attempts:
            target_state, detail = self._exhausted_attempt_terminal_transition(
                task,
                {"reason": "max attempts"},
            )
            self._transition_task_internal(
                task_id, target_state, "dispatcher", detail
            )
            raise TransitionError("task %s exhausted max_attempts" % task_id)
        lease_id = new_id("lease")
        coordination_related_ids = self._coordination_related_task_ids(task)
        coordination_lock_task_id: Optional[str] = None
        if coordination_related_ids:
            relationships = ensure_json_object(
                ensure_json_object(task.metadata).get("relationships")
            )
            coordination_lock_task_id = str(
                relationships.get("parent_task_id")
                or ensure_json_object(task.metadata).get("parent_task_id")
                or task.id
            ).strip()
        with self.store.transaction() as conn:
            # Claims for the same agent must serialize before capacity is
            # counted.  The earlier availability check is useful for a cheap
            # rejection, but it cannot be the authority: two dispatchers can
            # both observe one free slot.  Locking the agent row and repeating
            # the count closes that race on both SQLite and PostgreSQL.
            agent_lock = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if agent_lock.rowcount != 1:
                raise ValidationError("agent %s is unavailable" % agent_id)
            agent_row = conn.execute(
                "SELECT * FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            if agent_row is None:
                raise ValidationError("agent %s is unavailable" % agent_id)
            current_agent = self._agent_from_row(agent_row)
            active_count_row = conn.execute(
                """
                SELECT COUNT(*) AS count FROM leases l
                JOIN tasks t ON t.lease_id = l.id
                WHERE l.agent_id = ?
                  AND l.status = ?
                  AND t.owner_agent_id = ?
                """,
                (agent_id, LeaseStatus.ACTIVE.value, agent_id),
            ).fetchone()
            active_count = int(
                active_count_row["count"] if active_count_row is not None else 0
            )
            if coordination_lock_task_id:
                # Serialize family participation across dispatchers.  The
                # eligibility check above is intentionally repeated while a
                # shared parent-row lock is held, closing the race where two
                # child claims could otherwise assign the same agent before
                # either lease became visible.
                family_lock = conn.execute(
                    "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                    (coordination_lock_task_id,),
                )
                if family_lock.rowcount != 1:
                    raise ValidationError(
                        "cooperative task family lock %s is unavailable"
                        % coordination_lock_task_id
                    )
                placeholders = ",".join("?" for _ in coordination_related_ids)
                # Expired leases (crashed attempts) do not count as participation
                # — see _coordination_excluded_agent_ids.  allow_cooperative_reuse
                # relaxes the distinct-executor rule entirely when the dispatcher
                # has determined the whole pool is otherwise exhausted.
                prior_participation = (
                    None
                    if allow_cooperative_reuse
                    else conn.execute(
                        "SELECT 1 FROM leases WHERE agent_id = ? "
                        "AND task_id IN (%s) AND status != ? LIMIT 1" % placeholders,
                        (
                            agent_id,
                            *sorted(coordination_related_ids),
                            LeaseStatus.EXPIRED.value,
                        ),
                    ).fetchone()
                )
                if prior_participation is not None:
                    raise ValidationError(
                        "agent %s already participated in cooperative task family for %s"
                        % (agent_id, task_id)
                    )
            # Lock and re-read the task after the agent capacity lock.  The
            # task's dependency list and every dependency state below are now
            # checked in the same transaction as the claim write, so an OPEN
            # task with incomplete prerequisites cannot slip through a stale
            # dispatcher candidate snapshot.
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task_id,),
            )
            if task_lock.rowcount != 1:
                raise NotFoundError("task not found: %s" % task_id)
            task_row = conn.execute(
                "SELECT * FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if task_row is None:
                raise NotFoundError("task not found: %s" % task_id)
            current_task = self._task_from_row(task_row)
            if (
                current_task.state != TaskState.OPEN.value
                or current_task.lease_id is not None
            ):
                raise TransitionError("task %s was claimed by another agent" % task_id)
            self._assert_current_read_only_report_task_contract(
                current_task,
                conn=conn,
            )
            for dependency_id in current_task.dependencies:
                dependency_row = conn.execute(
                    "SELECT state FROM tasks WHERE id = ?", (dependency_id,)
                ).fetchone()
                if (
                    dependency_row is None
                    or dependency_row["state"] != TaskState.COMPLETED.value
                ):
                    raise TransitionError(
                        "task %s dependencies are not complete" % task_id
                    )
            if current_task.attempt_count >= current_task.max_attempts:
                raise TransitionError("task %s exhausted max_attempts" % task_id)
            self._assert_work_package_claim_downstream_ready_in_transaction(
                conn, current_task.id
            )
            project_paused = False
            if current_task.project:
                # A project pause is part of claim authority, so serialize
                # against activation/pause writes and inspect the same row in
                # this transaction. Implicit projects have no row and remain
                # active by design.
                conn.execute(
                    "UPDATE projects SET updated_at = updated_at "
                    "WHERE name = ? OR id = ?",
                    (current_task.project, current_task.project),
                )
                project_row = conn.execute(
                    "SELECT status, metadata FROM projects WHERE name = ? OR id = ?",
                    (current_task.project, current_task.project),
                ).fetchone()
                if project_row is not None:
                    project_metadata = json_loads(project_row["metadata"], {})
                    project_paused = (
                        str(project_row["status"] or "active") != "active"
                        or bool(project_metadata.get("dispatch_paused"))
                    )
            machine_lock = conn.execute(
                "UPDATE machines SET updated_at = updated_at WHERE id = ?",
                (current_agent.machine_id,),
            )
            if machine_lock.rowcount != 1:
                raise ValidationError("agent machine is unavailable")
            machine_row = conn.execute(
                "SELECT * FROM machines WHERE id = ?",
                (current_agent.machine_id,),
            ).fetchone()
            if machine_row is None:
                raise ValidationError("agent machine is unavailable")
            current_machine = self._machine_from_row(machine_row)
            required_runtime_digest = self._task_required_runtime_digest_in_transaction(
                conn, current_task
            )
            role_reason = self._claim_role_ineligibility_reason_in_transaction(
                conn,
                agent=current_agent,
                task=current_task,
                machine=current_machine,
            )
            # The task row lock serializes this read with authorization
            # creation. Lock the one ACTIVE record as well so its revoke/claim
            # CAS cannot wait until after we sample time. An authorization for
            # another agent reserves the task; it must never be silently left
            # active after a different worker claims the task.
            break_glass_row = conn.execute(
                """
                SELECT * FROM task_break_glass_authorizations
                WHERE task_id = ? AND status = 'active'
                ORDER BY created_at DESC LIMIT 1
                """,
                (current_task.id,),
            ).fetchone()
            if break_glass_row is not None:
                conn.execute(
                    "UPDATE task_break_glass_authorizations SET status = status "
                    "WHERE id = ?",
                    (break_glass_row["id"],),
                )
                break_glass_row = conn.execute(
                    "SELECT * FROM task_break_glass_authorizations WHERE id = ?",
                    (break_glass_row["id"],),
                ).fetchone()

            # This is deliberately after every potentially blocking claim lock.
            # A lease therefore receives its full TTL even if the transaction
            # waited behind another hub replica.
            now = self._lease_authority_now_in_transaction(conn)
            break_glass: Optional[BreakGlassAuthorization] = None
            if (
                break_glass_row is not None
                and break_glass_row["status"] == "active"
            ):
                if self._timestamp_is_after(break_glass_row["expires_at"], now):
                    break_glass = self._break_glass_authorization_from_row(
                        break_glass_row
                    )
                else:
                    conn.execute(
                        "UPDATE task_break_glass_authorizations "
                        "SET status = 'expired' WHERE id = ? AND status = 'active'",
                        (break_glass_row["id"],),
                    )
            if break_glass is not None:
                if break_glass.agent_id != current_agent.id:
                    raise AuthorizationError(
                        "task %s is reserved by break-glass authorization for agent %s"
                        % (current_task.id, break_glass.agent_id)
                    )
                if break_glass.execution_boundary != BREAK_GLASS_EXECUTION_BOUNDARY:
                    raise AuthorizationError(
                        "task break-glass execution boundary is invalid"
                    )
                role_reason = None
            ineligible_reason = self._claim_snapshot_ineligibility_reason(
                agent=current_agent,
                task=current_task,
                machine=current_machine,
                active_count=active_count,
                project_paused=project_paused,
                break_glass=break_glass,
                required_runtime_digest=required_runtime_digest,
                role_reason=role_reason,
            )
            if ineligible_reason is not None:
                raise ValidationError(
                    "agent %s cannot claim task %s: %s"
                    % (agent_id, task_id, ineligible_reason)
                )
            expires_at = (
                parse_time(now) + timedelta(seconds=lease_seconds)
            ).isoformat(timespec="microseconds")
            # Prepare the lease and, for a linked work-package task, its exact
            # immutable assignment/WIP authority before changing the ordinary
            # task row.  The database claim guard can therefore fail closed for
            # mixed-version hubs that know only the legacy task state machine.
            conn.execute(
                """
                INSERT INTO leases (id, task_id, agent_id, expires_at, status, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (lease_id, task_id, agent_id, expires_at, LeaseStatus.ACTIVE.value, now, now),
            )
            package_assignment = WorkPackageClaimGate().admit_claim(
                conn,
                task_id=task_id,
                agent_id=agent_id,
                lease_id=lease_id,
                attempt_number=current_task.attempt_count + 1,
                now=now,
                allocator=assignment_allocator,
                allocator_version=(
                    assignment_allocator_version
                    or WORK_PACKAGE_ALLOCATOR_VERSION
                ),
                score=assignment_score,
                rationale=(assignment_rationale or "authoritative package claim"),
                decision=assignment_decision,
                prepared_task=True,
            )
            # Atomic claim: the UPDATE only succeeds if the task is still OPEN and
            # unleased. rowcount==0 means another dispatcher already took it.
            cursor = conn.execute(
                """
                UPDATE tasks
                SET state = ?, owner_agent_id = ?, lease_id = ?, leased_until = ?,
                    attempt_count = attempt_count + 1, updated_at = ?
                WHERE id = ? AND state = ? AND lease_id IS NULL
                """,
                (
                    TaskState.CLAIMED.value,
                    agent_id,
                    lease_id,
                    expires_at,
                    now,
                    task_id,
                    TaskState.OPEN.value,
                ),
            )
            if cursor.rowcount != 1:
                raise TransitionError("task %s was claimed by another agent" % task_id)
            if package_assignment is not None:
                # Worker-visible projection only; the immutable assignment
                # audit remains authority.  This gives executors the exact
                # attempt ref they must push without letting them derive or
                # select a mutable task branch.
                projected_metadata = ensure_json_object(current_task.metadata)
                projected_metadata["work_package_assignment"] = {
                    "schema": "mac.work_package.assignment_projection.v1",
                    **package_assignment.to_dict(),
                }
                projected = conn.execute(
                    "UPDATE tasks SET metadata = ?, updated_at = ? "
                    "WHERE id = ? AND lease_id = ? AND state = ?",
                    (
                        json_dumps(projected_metadata),
                        now,
                        task_id,
                        lease_id,
                        TaskState.CLAIMED.value,
                    ),
                )
                if projected.rowcount != 1:
                    raise TransitionError(
                        "work-package assignment projection lost its lease fence"
                    )
            if break_glass is not None:
                authorization_update = conn.execute(
                    """
                    UPDATE task_break_glass_authorizations
                    SET status = 'claimed', claimed_at = ?, lease_id = ?
                    WHERE id = ? AND task_id = ? AND agent_id = ?
                      AND status = 'active'
                    """,
                    (
                        now,
                        lease_id,
                        break_glass.id,
                        task.id,
                        agent.id,
                    ),
                )
                if authorization_update.rowcount != 1:
                    raise ValidationError(
                        "break-glass authorization expired or changed during claim"
                    )
            conn.execute(
                """
                UPDATE agents
                SET status = ?, current_task_id = ?, updated_at = ?, last_seen_at = ?
                WHERE id = ?
                """,
                (AgentStatus.BUSY.value, task_id, now, now, agent_id),
            )
            detail = {"lease_id": lease_id, "expires_at": expires_at}
            if break_glass is not None:
                detail["break_glass_authorization_id"] = break_glass.id
                detail["execution_boundary"] = break_glass.execution_boundary
            self._record_history(
                task_id,
                "task.claimed",
                agent_id,
                task.state,
                TaskState.CLAIMED.value,
                detail,
                conn=conn,
            )
        claimed_task = self.get_task(task_id)
        if sync_beads:
            self.drain_task_transition_outbox(task_id=task_id, limit=20)
        return claimed_task, self.get_lease(lease_id)


    def list_task_transition_outbox(
        self,
        *,
        status: str = "pending",
        task_id: Optional[str] = None,
        limit: int = 100,
    ) -> List[TaskTransitionOutbox]:
        return self.task_ledger.list_outbox(status=status, task_id=task_id, limit=limit)

    def drain_task_transition_outbox(
        self,
        *,
        task_id: Optional[str] = None,
        limit: int = 100,
    ) -> JsonDict:
        processed = []
        for item in self.task_ledger.list_outbox(task_id=task_id, limit=limit):
            try:
                self._process_task_transition_outbox_item(item)
            except Exception as exc:  # noqa: BLE001 - one failed side effect must not block later rows.
                self.task_ledger.mark_outbox_failed(item.id, str(exc))
                self.record_log(
                    "task.transition_outbox.failed",
                    layer="control_plane",
                    source="task-ledger",
                    level="warning",
                    subject_type="task",
                    subject_id=item.task_id,
                    detail={"outbox_id": item.id, "event_type": item.event_type, "error": str(exc)},
                )
                processed.append({"id": item.id, "event_type": item.event_type, "status": "failed"})
                continue
            self.task_ledger.mark_outbox_processed(item.id)
            processed.append({"id": item.id, "event_type": item.event_type, "status": "delivered"})
        return {"processed": processed, "count": len(processed)}

    def drain_task_transition_outbox_best_effort(
        self,
        *,
        task_id: Optional[str] = None,
        limit: int = 100,
    ) -> JsonDict:
        if not self._task_outbox_drain_lock.acquire(blocking=False):
            return {"processed": [], "count": 0, "status": "busy"}
        try:
            result = self.drain_task_transition_outbox(task_id=task_id, limit=limit)
            # Success resets the failure streak so the health signal reflects
            # only *ongoing* trouble.
            self._task_outbox_drain_failures = 0
            return result
        except Exception as exc:  # noqa: BLE001 - side effects must not break API responses.
            # Track failures in an in-memory counter that CANNOT itself fail:
            # the previous code logged-and-swallowed, then wrapped the log in a
            # bare `except: pass`, so a persistently failing outbox (stranded
            # task transitions) could be entirely invisible if logging also
            # failed and the caller ignored the return. The counter guarantees
            # the failure is observable via status(), and severity escalates
            # once failures persist.
            self._task_outbox_drain_failures = (
                getattr(self, "_task_outbox_drain_failures", 0) + 1
            )
            failures = self._task_outbox_drain_failures
            try:
                self.record_log(
                    "task.transition_outbox.drain_failed",
                    layer="control_plane",
                    source="task-ledger",
                    # A one-off drain miss is a warning; a sustained failure
                    # streak means transitions are stranding — escalate.
                    level="error" if failures >= 3 else "warning",
                    subject_type="task" if task_id else None,
                    subject_id=task_id,
                    detail={
                        "error": str(exc),
                        "limit": limit,
                        "consecutive_failures": failures,
                    },
                )
            except Exception:  # noqa: BLE001 - telemetry may be down; counter still holds it.
                pass
            return {
                "processed": [],
                "count": 0,
                "status": "failed",
                "error": str(exc),
                "consecutive_failures": failures,
            }
        finally:
            self._task_outbox_drain_lock.release()

    def _process_task_transition_outbox_item(self, item: TaskTransitionOutbox) -> None:
        if item.event_type == "task.lifecycle":
            task = self.get_task(item.task_id)
            metadata = ensure_json_object(task.metadata)
            lifecycle = ensure_json_object(metadata.get("repository_ref_lifecycle"))
            if lifecycle:
                self.record_log(
                    "repository.ref.lifecycle",
                    layer="control_plane",
                    source="task-ledger",
                    level="info",
                    subject_type="task",
                    subject_id=item.task_id,
                    detail={
                        "task_state": task.state,
                        "disposition": lifecycle.get("disposition"),
                        "status": lifecycle.get("status"),
                        "eligible_after": lifecycle.get("eligible_after"),
                        "replacement_task_id": lifecycle.get("replacement_task_id"),
                    },
                )
            return
        task = self.get_task(item.task_id)
        if item.event_type == "workflow.advance":
            # Workflow-runtime hook. The link is the `tasks.workflow_run_id`
            # column (never caller metadata), so forged task metadata cannot
            # push a free-floating task into the workflow state machine.
            if item.to_state in TERMINAL_TASK_STATES.union({TaskState.BLOCKED.value}):
                self.workflow_runtime.on_task_completed(item.task_id, item.to_state or "")
            return
        raise ValidationError("unsupported task transition outbox event: %s" % item.event_type)

    def start_task(
        self,
        task_id: str,
        agent_id: str,
        *,
        lease_id: Optional[str] = None,
        drain_outbox: bool = True,
    ) -> Task:
        task = self.get_task(task_id)
        # PR2c (spec §6.3): accept either the lease owner OR a delegated
        # actor (recorded via delegate_lease). Renewal / release stay
        # strictly owner-only and are unchanged.
        self._require_lease_actor(task, agent_id, lease_id)
        current_lease_id = str(task.lease_id or "")
        # A loop worker may restart after it moved an assignment to RUNNING but
        # before it recorded evidence.  Starting the same, still-active lease
        # is idempotent so the worker can resume execution instead of stranding
        # the dispatcher-owned assignment on an invalid RUNNING -> RUNNING
        # transition.
        if task.state == TaskState.RUNNING.value:
            with self.store.transaction() as conn:
                self._require_exact_lease_actor_in_transaction(
                    conn,
                    task_id=task.id,
                    agent_id=agent_id,
                    lease_id=current_lease_id,
                    allowed_states=(TaskState.RUNNING.value,),
                )
            return self.get_task(task.id)
        return self.transition_task(
            task_id,
            TaskState.RUNNING.value,
            agent_id,
            {},
            lease_id=current_lease_id,
            drain_outbox=drain_outbox,
        )

    def submit_for_review(
        self,
        task_id: str,
        agent_id: str,
        *,
        lease_id: Optional[str] = None,
        drain_outbox: bool = True,
    ) -> Task:
        task = self.get_task(task_id)
        # PR2c (spec §6.3): accept either the lease owner OR a delegated
        # actor (recorded via delegate_lease).
        self._require_lease_actor(task, agent_id, lease_id)
        package_link = self.store.query_one(
            "SELECT package_id FROM work_package_task_links WHERE task_id = ?",
            (task.id,),
        )
        if package_link is not None:
            # Package work leaves the mutation station as an immutable
            # candidate before its execution lease is released.  The
            # controller derives the exact evidence target using the same
            # review-readiness gate as the normal transition; worker metadata
            # never chooses the candidate identity.  Submission is idempotent,
            # so a worker retry after a response loss cannot duplicate WIP.
            candidate_evidence = self._require_review_ready(task)
            candidate_submission = self.work_package_candidates.submit(
                candidate_evidence.id,
                actor="work-package-candidate-controller",
            )
        reviewed = self.transition_task(
            task_id,
            TaskState.NEEDS_REVIEW.value,
            agent_id,
            {},
            lease_id=str(task.lease_id or ""),
            drain_outbox=drain_outbox,
        )
        if package_link is not None:
            # Repository observation is controller-owned and therefore cannot
            # happen inside the worker's evidence transaction.  Start it as
            # soon as the immutable candidate reaches the review buffer, but
            # never trust worker evidence or undo submission if Git/network
            # observation is temporarily unavailable.  The approved review
            # station retries the same idempotent receipt before acceptance.
            try:
                verification = self.verify_work_package_output(candidate_evidence.id)
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.package_output_verified",
                    "info",
                    {
                        "candidate_id": verification.candidate_id,
                        "evidence_id": candidate_evidence.id,
                        "verification_receipt_id": verification.verification.id,
                        "created": verification.created,
                        "trigger": "candidate_submission",
                    },
                    "work-package-output-controller",
                )
            except Exception as exc:  # noqa: BLE001 - observation is retried at approval.
                try:
                    self._record_default_review_observation(
                        task_id,
                        "workflow.default_review.package_output_verification_failed",
                        "warning",
                        {
                            "candidate_id": candidate_submission.candidate.id,
                            "evidence_id": candidate_evidence.id,
                            "error": (
                                str(exc)[:500]
                                if isinstance(exc, MACError)
                                else "unexpected controller output verification failure"
                            ),
                            "error_class": exc.__class__.__name__,
                            "trigger": "candidate_submission",
                        },
                        "work-package-output-controller",
                    )
                except Exception:  # noqa: BLE001 - telemetry must not break submission.
                    pass
        # Event, not sweep: start the review workflow the moment work is
        # submitted instead of waiting up to a full tick interval.
        self._nudge_review_workflow(task_id)
        return reviewed

    def verify_work_package_output(
        self,
        evidence_id: str,
    ) -> AttemptVerificationResult:
        """Independently observe and receipt one exact package attempt output.

        This is intentionally separate from the worker-authored evidence call:
        repository inspection may involve remote I/O, and only the controller
        may append the immutable verification receipt consumed by acceptance
        and assembly.
        """

        return self.work_package_outputs.verify(evidence_id)

    def accept_work_package_candidate(
        self,
        candidate_id: str,
        *,
        actor: str = "work-package-acceptance-controller",
    ) -> Any:
        """Accept one reviewed, controller-verified package candidate."""

        return self.work_package_acceptance.accept(candidate_id, actor=actor)

    def reject_work_package_candidate(
        self,
        candidate_id: str,
        *,
        actor: str = "work-package-acceptance-controller",
        reason: str,
    ) -> Any:
        """Reject one exact package candidate under its immutable rework budget."""

        return self.work_package_acceptance.reject(
            candidate_id,
            actor=actor,
            reason=reason,
        )

    def create_work_package_integration_batch(
        self,
        package_id: str,
        integration_node_key: str,
        *,
        actor: str = "work-package-integration-controller",
    ) -> Any:
        """Freeze the exact accepted inputs for one integration node."""

        return self.work_package_integrations.create_batch(
            package_id,
            integration_node_key,
            actor=actor,
        )

    def work_package_integration_status(self, batch_id: str) -> JsonDict:
        """Return the integrity-checked state of one assembly batch."""

        return self.work_package_integrations.status(batch_id)

    def claim_work_package_integration_batch(self, batch_id: str) -> Any:
        """Claim one integration batch under this controller's monotonic fence."""

        return self.work_package_integrations.claim(batch_id)

    def assemble_work_package_integration_batch(self, batch_id: str) -> Any:
        """Assemble one already-created batch from its exact protected inputs."""

        return self.work_package_integrations.assemble(batch_id)

    def assemble_work_package(
        self,
        package_id: str,
        integration_node_key: str,
        *,
        actor: str = "work-package-integration-controller",
    ) -> JsonDict:
        """Create and assemble an integration batch as one controller operation."""

        batch = self.create_work_package_integration_batch(
            package_id,
            integration_node_key,
            actor=actor,
        )
        assembly = self.assemble_work_package_integration_batch(batch.batch_id)
        return {
            "batch": batch.to_dict(),
            "assembly": assembly.to_dict(),
        }

