    def _record_history_notification(
        self,
        writer: Any,
        task_id: str,
        event_type: str,
        actor: str,
        from_state: Optional[str],
        to_state: Optional[str],
        detail: Dict[str, Any],
        when: str,
    ) -> None:
        payload = self._notification_payload_for_history(
            task_id,
            event_type,
            actor,
            from_state,
            to_state,
            detail,
            writer=writer,
        )
        if payload is None:
            return
        self.record_notification(
            payload["event_type"],
            payload["title"],
            payload["body"],
            subject_type="task",
            subject_id=task_id,
            channels=payload.get("channels"),
            metadata=payload.get("metadata"),
            conn=writer,
            created_at=when,
        )

    def _notification_payload_for_history(
        self,
        task_id: str,
        event_type: str,
        actor: str,
        from_state: Optional[str],
        to_state: Optional[str],
        detail: Dict[str, Any],
        *,
        writer: Any = None,
    ) -> Optional[JsonDict]:
        task_title = task_id
        try:
            # Reuse the caller's transaction connection when history and its
            # notification are emitted atomically.  Opening a second pooled
            # connection here can deadlock a small PostgreSQL pool: one claim
            # holds this transaction, a peer claim holds the other connection
            # while waiting on the same agent row, and both wait forever for a
            # third connection.  The direct lookup also sees the transaction's
            # own task writes.
            source = writer if writer is not None else self.store
            row = source.execute(
                "SELECT title FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if row is not None and row["title"]:
                task_title = str(row["title"])
        except Exception:
            pass
        metadata = {
            "actor": actor,
            "from_state": from_state,
            "to_state": to_state,
            **ensure_json_object(detail),
        }
        if event_type == "task.claimed":
            return {
                "event_type": event_type,
                "title": "Task claimed",
                "body": "%s claimed %s" % (actor, task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.evidence_added":
            return {
                "event_type": event_type,
                "title": "Evidence recorded",
                "body": "%s added %s evidence for %s"
                % (actor, detail.get("kind", "task"), task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.review_requested":
            return {
                "event_type": event_type,
                "title": "Review requested",
                "body": "Review requested for %s" % task_title,
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.review_claimed":
            return {
                "event_type": event_type,
                "title": "Review claimed",
                "body": "%s claimed review for %s" % (actor, task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.review_completed":
            return {
                "event_type": event_type,
                "title": "Review completed",
                "body": "Review %s for %s"
                % (str(detail.get("status") or "completed"), task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.published":
            return {
                "event_type": event_type,
                "title": "Task published",
                "body": "%s published %s" % (actor, task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.lease_expired":
            return {
                "event_type": event_type,
                "title": "Task lease expired",
                "body": "%s was requeued after lease expiry" % task_title,
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.transitioned" and to_state in {
            TaskState.RUNNING.value,
            TaskState.WAITING.value,
            TaskState.BLOCKED.value,
            TaskState.NEEDS_REVIEW.value,
            TaskState.REVIEWING.value,
            TaskState.COMPLETED.value,
            TaskState.FAILED.value,
            TaskState.CANCELLED.value,
        }:
            return {
                "event_type": "task.%s" % to_state,
                "title": "Task %s" % to_state.replace("_", " "),
                "body": "%s moved to %s" % (task_title, to_state),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        return None

    def _dependencies_satisfied(self, task: Task) -> bool:
        for dep_id in task.dependencies:
            dep = self.get_task(dep_id)
            if dep.state != TaskState.COMPLETED.value:
                return False
        return True

    def _blocked_task_requires_manual_repair(self, task: Task) -> bool:
        if task.state != TaskState.BLOCKED.value:
            return False
        for event in reversed(self.task_history(task.id, limit=20)):
            if event.to_state != TaskState.BLOCKED.value:
                continue
            detail = ensure_json_object(event.detail)
            reason = str(detail.get("reason") or "").strip()
            # In the current state model every non-legacy BLOCKED reason is an
            # actionable execution/operator condition. Only the two historic
            # dependency-wait encodings may be auto-migrated/opened here.
            return detail.get("manual_repair_required") is True or reason not in {
                "",
                "waiting_on_dependencies",
                "dependencies_incomplete",
            }
        return False

    def _merge_attempt_failure_salvage_metadata(
        self,
        existing: Any,
        derived: Mapping[str, Any],
    ) -> JsonDict:
        merged = dict(existing) if isinstance(existing, Mapping) else {}
        for key, value in derived.items():
            if value in (None, "", [], {}):
                continue
            if key in {"recorded_lessons", "published_children"}:
                current = _metadata_string_list(merged.get(key))
                for item in _metadata_string_list(value):
                    if item not in current:
                        current.append(item)
                if current:
                    merged[key] = current
                continue
            merged.setdefault(key, value)
        return merged

    def _record_attempt_failure_classification(self, task: Task) -> Tuple[str, JsonDict]:
        history = [event.to_dict() for event in self.task_history(task.id, limit=100)]
        classification = classify_attempt_failure(history)
        metadata = ensure_json_object(task.metadata)
        metadata["failure_class"] = classification.failure_class
        if classification.salvage:
            metadata["salvage"] = self._merge_attempt_failure_salvage_metadata(
                metadata.get("salvage"),
                classification.salvage,
            )
        self.store.execute(
            "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
            (json_dumps(metadata), utcnow(), task.id),
        )
        return classification.failure_class, dict(classification.salvage)

    def _attempt_failure_output(self, task: Task) -> Tuple[str, str]:
        """Return the newest durable output tail from the exhausted attempts."""
        for event in reversed(self.task_history(task.id, limit=100)):
            detail = ensure_json_object(event.detail)
            output_tail, unavailable = _diagnostic_output_tail(detail)
            if output_tail:
                return output_tail, ""
            diagnosis = ensure_json_object(detail.get("diagnosis"))
            output_tail, unavailable = _diagnostic_output_tail(diagnosis)
            if output_tail:
                return output_tail, ""
        return "", "no captured stdout, stderr, output, log, or tail exists in attempt history"

    def _exhausted_attempt_terminal_transition(
        self,
        task: Task,
        detail: Mapping[str, Any],
    ) -> Tuple[str, JsonDict]:
        failure_class, salvage = self._record_attempt_failure_classification(task)
        transition_detail = dict(detail)
        defer_attempt_reset = bool(
            transition_detail.pop("_defer_attempt_reset", False)
        )
        transition_detail["failure_class"] = failure_class
        output_tail, unavailable = self._attempt_failure_output(task)
        if output_tail:
            transition_detail.setdefault("output_tail", output_tail)
        else:
            transition_detail.setdefault("output_tail_unavailable_reason", unavailable)
        if salvage:
            transition_detail["salvage"] = salvage
        # Contract failures are recoverable prerequisites, not dead-letter
        # task failures.  Create a durable repair task and suspend the parent
        # until that task supplies valid pushed/evidence state.  This prevents
        # the dispatcher from orphaning otherwise-complete work after retries.
        recent_history = self.task_history(task.id, limit=100)
        contract_failure = any(
            "verification_contract_failed" in json_dumps(ensure_json_object(event.detail)).lower()
            for event in recent_history
        )
        repairable_prerequisite = contract_failure or failure_class == "environment"
        # Recursion base case (2026-07-14 churn root cause): a repair task that
        # itself exhausts its attempts must NOT spawn a repair-of-repair. Without
        # this guard every deterministic infra failure (e.g. a stale attestation
        # key) grew an unbounded chain — "Repair prerequisites: Repair
        # prerequisites: ..." — with each level burning a full attempt budget on
        # the identical failure (observed: 175 of 267 new tasks in 12h were
        # repair tasks; 5 completions). A failed repair task dead-letters so its
        # parent's failure surfaces for real diagnosis instead of multiplying.
        origin = ensure_json_object(ensure_json_object(task.metadata).get("origin"))
        if str(origin.get("type") or "").endswith("_prerequisite"):
            transition_detail["reason"] = "repair_task_exhausted_no_recursion"
            transition_detail["manual_repair_required"] = True
            return TaskState.FAILED.value, transition_detail
        if repairable_prerequisite:
            # Classification is persisted immediately above. Reload before
            # adding dependency metadata so update_task cannot overwrite the
            # freshly recorded failure class and salvage with the stale task
            # object passed into this method.
            metadata = ensure_json_object(self.get_task(task.id).metadata)
            repair_metadata_key = "contract_repair_task_id" if contract_failure else "environment_repair_task_id"
            origin_type = (
                "contract_prerequisite"
                if contract_failure
                else "environment_prerequisite"
            )
            repair_id = str(metadata.get(repair_metadata_key) or "").strip()
            if not repair_id:
                if contract_failure:
                    repair_title = "Repair contract prerequisites: %s" % task.title
                    repair_description = (
                        "Repair the repository contract for parent task %s: commit all "
                        "changes, pass the required verification gate, and push a remote "
                        "ref/PR. The parent task will retry automatically after completion."
                    ) % task.id
                else:
                    repair_title = "Repair environment prerequisites: %s" % task.title
                    repair_description = (
                        "Repair the execution environment prerequisite for parent task %s. "
                        "Use the parent failure evidence and salvage metadata to restore the "
                        "required agent, service, credential source, or toolchain. The parent "
                        "task will retry automatically after this prerequisite completes."
                    ) % task.id
                # The repair identity is an idempotency key, not a random
                # allocation. If a sweeper crashes after creating the repair
                # but before detaching the expired lease, a recovery sweep (or
                # an exceptionally stale finalizer takeover) reuses this exact
                # task instead of manufacturing duplicate prerequisites.
                repair_id = "task_repair_%s" % hashlib.sha256(
                    (task.id + ":" + repair_metadata_key).encode("utf-8")
                ).hexdigest()[:24]
                repair = self.create_task(
                    repair_title,
                    description=repair_description,
                    project=task.project,
                    priority=task.priority,
                    required_capabilities=task.required_capabilities,
                    metadata={"origin": {"type": origin_type, "parent_task_id": task.id}},
                    actor="dispatcher.tick",
                    _task_id=repair_id,
                )
                repair_id = repair.id
                repair_origin = ensure_json_object(
                    ensure_json_object(repair.metadata).get("origin")
                )
                if (
                    repair_origin.get("type") != origin_type
                    or repair_origin.get("parent_task_id") != task.id
                ):
                    raise ValidationError(
                        "deterministic repair id collides with unrelated task"
                    )
                metadata[repair_metadata_key] = repair_id
                if contract_failure:
                    metadata["contract_repair_status"] = "waiting"
                self.update_task(
                    task.id,
                    dependencies=[*task.dependencies, repair_id],
                    metadata=metadata,
                    actor="dispatcher.tick",
                )
                transition_detail["repair_task_id"] = repair_id
            repair_task = self.get_task(repair_id)
            repair_origin = ensure_json_object(
                ensure_json_object(repair_task.metadata).get("origin")
            )
            if (
                repair_origin.get("type") != origin_type
                or repair_origin.get("parent_task_id") != task.id
            ):
                raise ValidationError(
                    "repair prerequisite does not match its parent and origin"
                )
            if not defer_attempt_reset:
                self.store.execute(
                    "UPDATE tasks SET attempt_count = 0, updated_at = ? WHERE id = ?",
                    (utcnow(), task.id),
                )
            else:
                transition_detail["reset_attempt_count"] = True
            transition_detail["reason"] = (
                "waiting_on_contract_prerequisite"
                if contract_failure
                else "waiting_on_environment_prerequisite"
            )
            transition_detail["manual_repair_required"] = False
            return TaskState.WAITING.value, transition_detail
        if failure_class == "superseded":
            transition_detail["reason"] = "superseded"
            return TaskState.CANCELLED.value, transition_detail
        return TaskState.FAILED.value, transition_detail

    def _blocked_attempt_retry_backoff_seconds(self, task: Task) -> int:
        per_attempt = _int_env(
            "MAC_BLOCKED_ATTEMPT_RETRY_BACKOFF_SECONDS",
            DEFAULT_BLOCKED_ATTEMPT_RETRY_BACKOFF_SECONDS,
        )
        return per_attempt * max(1, int(task.attempt_count or 0))

    def _blocked_attempt_retry_ready_at(
        self,
        task: Task,
        *,
        backoff_seconds: Optional[int] = None,
    ) -> str:
        backoff = (
            int(backoff_seconds)
            if backoff_seconds is not None
            else self._blocked_attempt_retry_backoff_seconds(task)
        )
        return (
            parse_time(task.updated_at) + timedelta(seconds=backoff)
        ).isoformat(timespec="microseconds")

    def _blocked_attempt_non_retryable_marker(self, task: Task) -> Optional[str]:
        if task.state != TaskState.BLOCKED.value:
            return None
        for event in reversed(self.task_history(task.id, limit=20)):
            if event.to_state != TaskState.BLOCKED.value:
                continue
            marker = _non_retryable_blocked_attempt_marker(event.detail)
            if marker:
                return marker
            break
        metadata = ensure_json_object(task.metadata)
        activity = metadata.get("activity")
        if isinstance(activity, list):
            for entry in reversed(activity):
                entry_dict = ensure_json_object(entry) if isinstance(entry, dict) else {}
                phase = str(entry_dict.get("phase") or "").strip().lower()
                if phase != "diagnosis":
                    continue
                return _non_retryable_blocked_attempt_marker(entry_dict)
        for key in ("diagnosis", "failure_diagnosis", "diagnosis_code"):
            marker = _non_retryable_blocked_attempt_marker(metadata.get(key))
            if marker:
                return marker
        return None

    def _is_timeout_blocked_attempt(self, task: Task) -> bool:
        """Return True when the most recent block on *task* looks like an agent-run timeout.

        Checks (in order, stopping at the first conclusive signal):
        1. The last BLOCKED history event's detail (reason/error/problems fields).
        2. The most recent ``diagnosis`` entry in ``metadata.activity``.

        Mirrors the ``_blocked_attempt_non_retryable_marker`` inspection pattern so
        both helpers stay consistent about how they read block evidence.
        """
        if task.state != TaskState.BLOCKED.value:
            return False
        for event in reversed(self.task_history(task.id, limit=20)):
            if event.to_state != TaskState.BLOCKED.value:
                continue
            detail = ensure_json_object(event.detail)
            blob = " ".join(
                str(detail.get(k) or "") for k in ("reason", "error", "problems")
            )
            if blob.strip():
                return _is_timeout_blob(blob)
            break
        metadata = ensure_json_object(task.metadata)
        activity = metadata.get("activity")
        if isinstance(activity, list):
            for entry in reversed(activity):
                entry_dict = ensure_json_object(entry) if isinstance(entry, dict) else {}
                phase = str(entry_dict.get("phase") or "").strip().lower()
                if phase != "diagnosis":
                    continue
                summary = str(entry_dict.get("summary") or "")
                return _is_timeout_blob(summary)
        return False

    def _auto_retry_blocked_attempt_task(
        self,
        task: Task,
        *,
        now: str,
    ) -> Tuple[Optional[Task], Optional[Task]]:
        if task.state != TaskState.BLOCKED.value:
            return None, None
        if int(task.attempt_count or 0) <= 0:
            return None, None
        if task.dependencies and not self._dependencies_satisfied(task):
            return None, None
        non_retryable = self._blocked_attempt_non_retryable_marker(task)
        if non_retryable:
            return None, None
        backoff_seconds = self._blocked_attempt_retry_backoff_seconds(task)
        ready_at = self._blocked_attempt_retry_ready_at(
            task,
            backoff_seconds=backoff_seconds,
        )
        if parse_time(now) < parse_time(ready_at):
            return None, None
        base_detail: JsonDict = {
            "via": "auto_retry",
            "attempt_count": task.attempt_count,
            "max_attempts": task.max_attempts,
            "backoff_seconds": backoff_seconds,
            "blocked_since": task.updated_at,
            "ready_at": ready_at,
        }
        if task.attempt_count >= task.max_attempts:
            target_state, exhausted_detail = self._exhausted_attempt_terminal_transition(
                task,
                {
                    **base_detail,
                    "via": "auto_retry_exhausted",
                    "reason": "max attempts",
                },
            )
            exhausted = self._transition_task_internal(
                task.id,
                target_state,
                "dispatcher.tick",
                exhausted_detail,
            )
            return None, exhausted
        detail = {
            **base_detail,
            "reason": "blocked attempt retry backoff elapsed",
        }
        is_timeout = self._is_timeout_blocked_attempt(task)
        if is_timeout and not ensure_json_object(task.metadata).get("plan_first"):
            # mac-timeout-plan: a timed-out task is likely too large for a
            # monolithic run. Instead of retrying blindly, inject plan_first=True
            # so the next executor run decomposes the work instead of repeating it.
            patched_meta = ensure_json_object(task.metadata)
            patched_meta["plan_first"] = True
            self.store.execute(
                "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                (json_dumps(patched_meta), now, task.id),
            )
            self._record_history(
                task.id,
                "task.timeout_requeued_as_plan",
                "dispatcher.tick",
                TaskState.BLOCKED.value,
                TaskState.BLOCKED.value,
                {**detail, "injected": "plan_first"},
            )
        reopened = self._transition_task_internal(
            task.id,
            TaskState.OPEN.value,
            "dispatcher.tick",
            detail,
        )
        self._record_history(
            task.id,
            "task.auto_reopened",
            "dispatcher.tick",
            TaskState.BLOCKED.value,
            TaskState.OPEN.value,
            detail,
        )
        return reopened, None

    def _prepare_cooperative_integration_task(self, task: Task) -> Task:
        """Attach immutable child outputs before reopening an integration task."""
        metadata = ensure_json_object(task.metadata)
        coordination = ensure_json_object(metadata.get("coordination"))
        if coordination.get("mode") != "cooperative_integration":
            return task
        child_ids = _metadata_string_list(coordination.get("child_task_ids"))
        if not child_ids:
            return task
        outputs: List[JsonDict] = []
        for child_id in child_ids:
            try:
                child = self.get_task(child_id)
            except NotFoundError:
                outputs.append(
                    {"task_id": child_id, "status": "missing_task"}
                )
                continue
            child_target = ensure_json_object(
                ensure_json_object(child.metadata).get("review_target")
            )
            evidence_id = str(
                child_target.get("executor_evidence_id") or ""
            ).strip()
            output: JsonDict = {
                "task_id": child.id,
                "title": child.title,
                "state": child.state,
                "executor_evidence_id": evidence_id,
            }
            if evidence_id:
                try:
                    evidence = self.get_evidence(evidence_id)
                except NotFoundError:
                    output["status"] = "missing_evidence"
                else:
                    manifest = ensure_json_object(
                        ensure_json_object(evidence.metadata).get("verification")
                    )
                    repo = ensure_json_object(manifest.get("repo"))
                    output.update(
                        {
                            "status": "ready",
                            "summary": evidence.summary,
                            "created_by": evidence.created_by,
                            "evidence_type": manifest.get("evidence_type"),
                            "repo": {
                                key: repo.get(key)
                                for key in (
                                    "head_sha",
                                    "base_sha",
                                    "remote_ref",
                                    "remote_url",
                                    "pr_url",
                                    "files_changed",
                                )
                                if repo.get(key) not in (None, "", [])
                            },
                        }
                    )
            else:
                output["status"] = "missing_evidence"
            outputs.append(output)
        coordination["phase"] = "integration"
        coordination["child_outputs"] = outputs
        coordination["integration_contract"] = {
            "required": True,
            "strategy": "merge_each_exact_child_commit",
            "verify_combined_result": True,
            "verify_child_commit_ancestry": True,
        }
        metadata["coordination"] = coordination
        self.store.execute(
            "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
            (json_dumps(metadata), utcnow(), task.id),
        )
        return self.get_task(task.id)

    def _unblock_ready_tasks(
        self,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> JsonDict:
        limit_value = max(1, min(int(limit), 1000))
        clauses = ["state IN (?, ?)"]
        params: List[Any] = [TaskState.WAITING.value, TaskState.BLOCKED.value]
        decoded = self._decode_scan_cursor(cursor, "blocked-tasks")
        if decoded is not None:
            updated_at, task_id = decoded
            clauses.append("(updated_at > ? OR (updated_at = ? AND id > ?))")
            params.extend([updated_at, updated_at, task_id])
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s "
            "ORDER BY updated_at, id LIMIT ?" % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        rows = rows[:limit_value]
        unblocked: List[Task] = []
        for row in rows:
            task = self._task_from_row(row)
            try:
                manual_repair = self._blocked_task_requires_manual_repair(task)
                if task.dependencies and self._dependencies_satisfied(task) and not manual_repair:
                    task = self._prepare_cooperative_integration_task(task)
                    unblocked.append(
                        self._transition_task_internal(
                            task.id,
                            TaskState.OPEN.value,
                            "dispatcher",
                            {"reason": "dependencies satisfied"},
                        )
                    )
                elif (
                    task.state == TaskState.BLOCKED.value
                    and task.dependencies
                    and not manual_repair
                ):
                    # One-way compatibility migration for ledgers created
                    # before dependency waits had their own state.
                    self._transition_task_internal(
                        task.id,
                        TaskState.WAITING.value,
                        "dispatcher",
                        {
                            "reason": "waiting_on_dependencies",
                            "blocked_by_task_ids": list(task.dependencies),
                            "legacy_state_migration": True,
                        },
                    )
            except Exception as exc:  # noqa: BLE001 - isolate corrupt blocked rows.
                try:
                    self.record_log(
                        "task.unblock.failed",
                        layer="control_plane",
                        source="dispatcher",
                        level="error",
                        subject_type="task",
                        subject_id=task.id,
                        detail={"task_id": task.id, "error": str(exc)},
                    )
                except Exception:
                    pass
        next_cursor = (
            self._encode_scan_cursor(
                "blocked-tasks",
                str(rows[-1]["updated_at"]),
                str(rows[-1]["id"]),
            )
            if has_more and rows
            else None
        )
        return {
            "tasks": unblocked,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _unblock_ready_sweep_page(self, *, limit: int) -> JsonDict:
        claim = self.reconciliation.claim("blocked-task-sweep")
        if claim is None:
            return {
                "tasks": [],
                "next_cursor": None,
                "has_more": False,
                "skipped": "lease_held",
            }
        try:
            result = self._unblock_ready_tasks(
                limit=limit,
                cursor=claim.cursor,
            )
        except Exception:
            self.reconciliation.abandon(claim)
            raise
        self.reconciliation.complete(claim, cursor=result.get("next_cursor"))
        return result

    def _auto_retry_blocked_attempts(
        self,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> JsonDict:
        limit_value = max(1, min(int(limit), 1000))
        clauses = ["state = ?", "attempt_count > 0"]
        params: List[Any] = [TaskState.BLOCKED.value]
        decoded = self._decode_scan_cursor(cursor, "blocked-attempt-retries")
        if decoded is not None:
            updated_at, task_id = decoded
            clauses.append("(updated_at > ? OR (updated_at = ? AND id > ?))")
            params.extend([updated_at, updated_at, task_id])
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s "
            "ORDER BY updated_at, id LIMIT ?" % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        rows = rows[:limit_value]
        now = utcnow()
        reopened: List[Task] = []
        exhausted: List[Task] = []
        for row in rows:
            task = self._task_from_row(row)
            try:
                reopened_task, exhausted_task = self._auto_retry_blocked_attempt_task(
                    task,
                    now=now,
                )
            except Exception as exc:  # noqa: BLE001 - isolate corrupt blocked rows.
                try:
                    self.record_log(
                        "task.auto_retry.failed",
                        layer="control_plane",
                        source="dispatcher.tick",
                        level="error",
                        subject_type="task",
                        subject_id=task.id,
                        detail={"task_id": task.id, "error": str(exc)},
                    )
                except Exception:
                    pass
                continue
            if reopened_task is not None:
                reopened.append(reopened_task)
            if exhausted_task is not None:
                exhausted.append(exhausted_task)
        next_cursor = (
            self._encode_scan_cursor(
                "blocked-attempt-retries",
                str(rows[-1]["updated_at"]),
                str(rows[-1]["id"]),
            )
            if has_more and rows
            else None
        )
        return {
            "tasks": reopened,
            "exhausted": exhausted,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _auto_retry_blocked_attempts_sweep_page(self, *, limit: int) -> JsonDict:
        claim = self.reconciliation.claim("blocked-attempt-retry-sweep")
        if claim is None:
            return {
                "tasks": [],
                "exhausted": [],
                "next_cursor": None,
                "has_more": False,
                "skipped": "lease_held",
            }
        try:
            result = self._auto_retry_blocked_attempts(
                limit=limit,
                cursor=claim.cursor,
            )
        except Exception:
            self.reconciliation.abandon(claim)
            raise
        self.reconciliation.complete(claim, cursor=result.get("next_cursor"))
        return result

    # mac-5ayd: cap the working set per dispatch batch. Loading 100k OPEN
    # tasks into Python to sort+round-robin is wasteful and grows linearly
    # with backlog. 500 is above the largest supported tick batch while
    # remaining below the point where the Python sort cost is noticeable.
    _DISPATCH_TASK_WINDOW = 500
    _DISPATCH_PRIORITY_AGING_SECONDS = 24 * 60 * 60
    _DISPATCH_SKIP_LOG_LIMIT = 25


    def _dispatch_ordered_tasks(self, *, project: Optional[str] = None) -> List[Task]:
        groups: Dict[str, List[Task]] = {}
        now = utcnow()
        candidates = self._dispatch_candidate_tasks(project=project)
        task_ranks = WorkPackageDispatchAdvisor(self.store).task_rank_snapshot(
            candidates
        )
        for task in candidates:
            tenant_key = self._task_tenant_id(task) or ""
            groups.setdefault(tenant_key, []).append(task)
        for tenant_id, tenant_tasks in groups.items():
            groups[tenant_id] = self._interleave_tasks_by_project(
                tenant_tasks,
                now,
                task_ranks=task_ranks,
            )
        tenant_order = sorted(
            groups,
            key=lambda tenant_id: (
                *self._dispatch_task_sort_key(
                    groups[tenant_id][0], now, task_ranks=task_ranks
                ),
                tenant_id,
            ),
        )
        ordered: List[Task] = []
        while any(groups.values()):
            for tenant_id in tenant_order:
                if groups[tenant_id]:
                    ordered.append(groups[tenant_id].pop(0))
        return ordered

    def _interleave_tasks_by_project(
        self,
        tasks: List[Task],
        now: str,
        *,
        task_ranks: Optional[Mapping[str, WorkPackageTaskRank]] = None,
    ) -> List[Task]:
        """Round-robin a tenant's candidates across projects.

        Projects sharing a tenant otherwise contend on a single
        (priority, age) order, so one project flooding high-priority tasks
        starves its siblings for up to the aging period. Interleaving gives
        every project with ready work a claim slot each cycle; within a
        project the (priority, age) order is preserved.
        """
        projects: Dict[str, List[Task]] = {}
        for task in tasks:
            projects.setdefault(task.project or "", []).append(task)
        for project_tasks in projects.values():
            project_tasks.sort(
                key=lambda item: self._dispatch_task_sort_key(
                    item, now, task_ranks=task_ranks
                )
            )
        project_order = sorted(
            projects,
            key=lambda name: (
                *self._dispatch_task_sort_key(
                    projects[name][0], now, task_ranks=task_ranks
                ),
                name,
            ),
        )
        ordered: List[Task] = []
        while any(projects.values()):
            for name in project_order:
                if projects[name]:
                    ordered.append(projects[name].pop(0))
        return ordered

    def _dispatch_candidate_tasks(self, *, project: Optional[str] = None) -> List[Task]:
        """Bound dispatch's SQL read while keeping starvation protection visible.

        The priority window preserves the hot path: newly-high-priority tasks
        are seen first. The oldest window is de-duplicated into the same Python
        scoring pass so an ancient low-priority task can age into dispatch even
        when the priority window is saturated.
        """
        where = ["state = ?", "owner_agent_id IS NULL", "lease_id IS NULL"]
        params: List[Any] = [TaskState.OPEN.value]
        if project is not None:
            where.append("project = ?")
            params.append(project)
        where_sql = " AND ".join(where)
        limit_params = tuple(params + [self._DISPATCH_TASK_WINDOW])
        priority_rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s "
            "ORDER BY priority DESC, created_at, id LIMIT ?" % where_sql,
            limit_params,
        )
        oldest_rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s "
            "ORDER BY created_at, id LIMIT ?" % where_sql,
            limit_params,
        )
        tasks_by_id: Dict[str, Task] = {}
        for row in list(priority_rows) + list(oldest_rows):
            task = self._task_from_row(row)
            tasks_by_id.setdefault(task.id, task)
        return list(tasks_by_id.values())

    def _dispatch_task_sort_key(
        self,
        task: Task,
        now: Optional[str] = None,
        *,
        task_ranks: Optional[Mapping[str, WorkPackageTaskRank]] = None,
    ) -> Tuple[int, float, str, str]:
        age_bonus = self._dispatch_priority_age_bonus(task, now or utcnow())
        effective_priority = int(task.priority or 0) + age_bonus
        package_rank = (task_ranks or {}).get(task.id)
        order_signal = package_rank.order_signal if package_rank is not None else 0.0
        return (-effective_priority, -order_signal, task.created_at, task.id)

    def _dispatch_priority_age_bonus(self, task: Task, now: str) -> int:
        step_seconds = _int_env(
            "MAC_DISPATCH_PRIORITY_AGING_SECONDS",
            self._DISPATCH_PRIORITY_AGING_SECONDS,
            minimum=60,
        )
        try:
            age_seconds = (parse_time(now) - parse_time(task.created_at)).total_seconds()
        except Exception:  # noqa: BLE001 - corrupt timestamps should not block dispatch.
            return 0
        return max(0, int(age_seconds // step_seconds))

    def _worker_claim_policy(
        self,
        allowed_projects: Optional[Iterable[str]],
        required_metadata: Optional[Dict[str, Any]],
        require_canary: bool,
        dry_run: bool,
        capabilities: Optional[Iterable[str]] = None,
    ) -> JsonDict:
        return {
            "allowed_projects": sorted(
                {
                    str(project).strip()
                    for project in (allowed_projects or [])
                    if str(project).strip()
                }
            ),
            "required_metadata": ensure_json_object(required_metadata or {}),
            "require_canary": bool(require_canary),
            "dry_run": bool(dry_run),
            "capabilities": sorted(
                {
                    str(cap).strip()
                    for cap in (capabilities or [])
                    if str(cap).strip()
                }
            ),
        }

    def _active_break_glass_authorization(
        self,
        task_id: str,
        agent_id: Optional[str] = None,
        *,
        now: Optional[str] = None,
    ) -> Optional[BreakGlassAuthorization]:
        current = now or utcnow()
        clauses = ["task_id = ?", "status = 'active'", "expires_at > ?"]
        params: List[Any] = [task_id, current]
        if agent_id is not None:
            clauses.append("agent_id = ?")
            params.append(agent_id)
        row = self.store.query_one(
            "SELECT * FROM task_break_glass_authorizations WHERE %s "
            "ORDER BY created_at DESC LIMIT 1" % " AND ".join(clauses),
            tuple(params),
        )
        return self._break_glass_authorization_from_row(row) if row is not None else None

    def _claimed_break_glass_authorization(
        self, task_id: str, agent_id: str, lease_id: str
    ) -> Optional[BreakGlassAuthorization]:
        row = self.store.query_one(
            """
            SELECT * FROM task_break_glass_authorizations
            WHERE task_id = ? AND agent_id = ? AND lease_id = ? AND status = 'claimed'
            ORDER BY claimed_at DESC LIMIT 1
            """,
            (task_id, agent_id, lease_id),
        )
        return self._break_glass_authorization_from_row(row) if row is not None else None

    def _assignment_task_payload(self, task: Task, lease: Lease) -> JsonDict:
        """Attach a lease-bound host authorization to an in-memory assignment.

        This transient projection is the only task document the executor trusts
        for host execution.  The durable task metadata remains unchanged.
        """

        payload = task.to_dict()
        metadata = ensure_json_object(payload.get("metadata"))
        runtime = ensure_json_object(metadata.get("runtime"))
        # Strip caller-controlled lookalikes even when no authorization exists.
        runtime.pop("break_glass_authorization", None)
        if runtime:
            metadata["runtime"] = runtime
        else:
            metadata.pop("runtime", None)
        payload["metadata"] = metadata
        authorization = self._claimed_break_glass_authorization(
            task.id, lease.agent_id, lease.id
        )
        if authorization is None:
            return payload
        runtime = ensure_json_object(metadata.get("runtime"))
        runtime["break_glass_authorization"] = authorization.to_dict()
        metadata["runtime"] = runtime
        payload["metadata"] = metadata
        return payload

    def _consume_break_glass_authorizations(
        self,
        conn: Any,
        *,
        task_id: str,
        lease_id: Optional[str],
        now: str,
    ) -> None:
        if not lease_id:
            return
        conn.execute(
            """
            UPDATE task_break_glass_authorizations
            SET status = 'consumed', consumed_at = ?
            WHERE task_id = ? AND lease_id = ? AND status = 'claimed'
            """,
            (now, task_id, lease_id),
        )

    def _task_dispatch_held(self, task: Task) -> bool:
        """True when a task is explicitly held from autonomous dispatch (staged).

        Set via metadata ``no_dispatch: true`` (e.g. ``mac task create
        --no-dispatch``) so a backlog — a freshly-onboarded project's tickets,
        or operator handoff notes — can be filed WITHOUT the loop-mode fleet
        auto-claiming it. The hold only blocks autonomous claim and hides the
        task from the ready queue; an operator can still start it explicitly
        (``mac task claim`` / ``mac task start``). This is the first-class
        replacement for abusing a sentinel ``required_capabilities`` value.
        """
        return bool(ensure_json_object(task.metadata).get("no_dispatch"))

    def _project_dispatch_paused(self, project: Optional[str]) -> bool:
        """True when the task's project is explicitly dispatch-PAUSED.

        Per-project onboarding gate: a newly-created project can be staged
        (``mac project create`` defaults to paused; ``mac project activate``
        releases it) so its tickets don't auto-dispatch until the operator
        turns the project on. IMPLICIT projects (no ``projects`` row — the case
        for the live fleet's default project) are never paused, so existing
        autonomous behavior is unchanged. Only projects with a record carrying
        ``metadata.dispatch_paused`` are held.
        """
        if not project:
            return False
        try:
            rec = self.get_project_record(project)
        except NotFoundError:
            return False
        except Exception:  # noqa: BLE001 — never let a lookup error block dispatch
            return False
        return bool(ensure_json_object(rec.metadata).get("dispatch_paused"))

    def _task_matches_worker_claim_policy(
        self, task: Task, policy: JsonDict, *, agent_id: Optional[str] = None
    ) -> Tuple[bool, str]:
        break_glass = (
            self._active_break_glass_authorization(task.id, agent_id)
            if agent_id
            else None
        )
        if self._task_dispatch_held(task) and break_glass is None:
            return False, "dispatch_held"
        if self._project_dispatch_paused(task.project) and break_glass is None:
            return False, "project_dispatch_paused"
        if break_glass is not None:
            # Admin authorization binds this exact task to this exact worker and
            # intentionally overrides worker-side project/canary/metadata lanes.
            # The hard host trust, health, capacity, and tenant checks still run
            # in _agent_availability_for_task.
            return True, "break_glass_authorized"
        allowed_projects = set(policy.get("allowed_projects") or [])
        if allowed_projects and (task.project or "") not in allowed_projects:
            return False, "project_not_allowed"
        capabilities = set(policy.get("capabilities") or [])
        if capabilities:
            required = set(getattr(task, "required_capabilities", None) or [])
            if required and not required.issubset(capabilities):
                return False, "capability_not_allowed"
        metadata = ensure_json_object(task.metadata)
        if policy.get("require_canary") and not (
            metadata.get("canary") is True
            or metadata.get("mac_canary") is True
            or metadata.get("worker_canary") is True
        ):
            return False, "not_canary"
        for key, expected in (policy.get("required_metadata") or {}).items():
            if metadata.get(key) != expected:
                return False, "metadata_mismatch"
        return True, "matched"

    def _available_agents(self) -> List[Agent]:
        rows = self.store.query_all(
            """
            SELECT a.* FROM agents a
            JOIN machines m ON m.id = a.machine_id
            WHERE a.status IN (?, ?) AND a.health_status = ? AND m.trusted = 1
            ORDER BY a.last_seen_at DESC, a.id
            """,
            (AgentStatus.IDLE.value, AgentStatus.BUSY.value, HealthStatus.HEALTHY.value),
        )
        return [self._agent_from_row(row) for row in rows]

    def _coordination_related_task_ids(self, task: Task) -> set[str]:
        """Return the durable task family used for cooperative separation."""
        metadata = ensure_json_object(task.metadata)
        coordination = ensure_json_object(metadata.get("coordination"))
        if coordination.get("require_distinct_agent") is not True:
            return set()
        relationships = ensure_json_object(metadata.get("relationships"))
        parent_id = str(
            relationships.get("parent_task_id")
            or metadata.get("parent_task_id")
            or task.id
        ).strip()
        related_ids = {parent_id}
        if parent_id == task.id:
            related_ids.update(
                _metadata_string_list(coordination.get("child_task_ids"))
            )
            related_ids.update(
                _metadata_string_list(relationships.get("child_task_ids"))
            )
        else:
            try:
                parent = self.get_task(parent_id)
            except NotFoundError:
                parent = None
            if parent is not None:
                parent_metadata = ensure_json_object(parent.metadata)
                parent_relationships = ensure_json_object(
                    parent_metadata.get("relationships")
                )
                parent_coordination = ensure_json_object(
                    parent_metadata.get("coordination")
                )
                related_ids.update(
                    _metadata_string_list(parent_relationships.get("child_task_ids"))
                )
                related_ids.update(
                    _metadata_string_list(parent_coordination.get("child_task_ids"))
                )
        return related_ids

    def _coordination_excluded_agent_ids(self, task: Task) -> set[str]:
        """Agents that meaningfully participated in a cooperative task family.

        Decomposed children and the final integration pass require distinct
        executors.  Lease history is the durable source of participation: it
        survives task handoff, unlike ``owner_agent_id``.

        Expired leases are *excluded* from the participation set: an expired
        lease means the agent went offline / crashed mid-attempt (it never
        produced a result to keep the reviewer independent from), so counting
        it as durable participation permanently burns that agent for the whole
        family after a mere crash.  In a finite agent pool, accumulated expired
        leases ratchet every family into a permanent no-eligible-agent deadlock
        that buys nothing — a re-attempt by the crashed agent is strictly better
        than a task that can never run again.  Only active/renewed/released
        leases (a real, completed-or-in-flight attempt) count.
        """
        related_ids = self._coordination_related_task_ids(task)
        if not related_ids:
            return set()
        placeholders = ",".join("?" for _ in related_ids)
        rows = self.store.query_all(
            "SELECT DISTINCT agent_id FROM leases "
            "WHERE task_id IN (%s) AND status != ?" % placeholders,
            (*sorted(related_ids), LeaseStatus.EXPIRED.value),
        )
        return {str(row["agent_id"]) for row in rows if row["agent_id"]}

    def _agent_available_for(
        self, agent: Agent, task: Task, *, allow_cooperative_reuse: bool = False
    ) -> bool:
        available, _reason = self._agent_availability_for_task(
            agent, task, allow_cooperative_reuse=allow_cooperative_reuse
        )
        return available

    def _claim_snapshot_ineligibility_reason(
        self,
        *,
        agent: Agent,
        task: Task,
        machine: Machine,
        active_count: int,
        project_paused: bool,
        break_glass: Optional[BreakGlassAuthorization],
        required_runtime_digest: Optional[str],
        role_reason: Optional[str],
    ) -> Optional[str]:
        """Evaluate mutable claim predicates from transaction-locked rows.

        Candidate generation remains an optimization. This is the authority
        immediately before lease INSERT, covering the state that can change
        after a dispatcher preflight (agent drain/status/capabilities/runtime,
        task/project holds, and machine trust/resource/tenant policy).
        """
        if agent.deleted_at:
            return "agent_deleted"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return "agent_status_unavailable"
        if agent.health_status != HealthStatus.HEALTHY.value:
            return "agent_health_unavailable"
        if not self.directives.agent_policy_ready(agent.id):
            return "directive_policy_unacknowledged"
        if active_count >= self._agent_capacity(agent):
            return "agent_capacity_full"
        if not machine.trusted:
            return "machine_untrusted"
        if not self._machine_allows_tenant(machine, self._task_tenant_id(task)):
            return "machine_tenant_not_allowed"
        if (
            metadata_declares_read_only_report_repository(task.metadata)
            and not agent_has_read_only_report_repository_executor(agent.resources)
        ):
            return "report_repository_executor_missing"

        break_glass_active = break_glass is not None and break_glass.agent_id == agent.id
        if self._task_dispatch_held(task) and not break_glass_active:
            return "dispatch_held"
        if project_paused and not break_glass_active:
            return "project_dispatch_paused"
        if agent.dispatch_hold and not break_glass_active:
            return "agent_dispatch_held"

        metadata = ensure_json_object(task.metadata)
        excluded = {
            str(value)
            for value in metadata.get("excluded_agent_ids", [])
            if str(value)
        } if isinstance(metadata.get("excluded_agent_ids"), list) else set()
        if agent.id in excluded:
            return "explicit_agent_excluded"
        target_agent_id = str(metadata.get("target_agent_id") or "").strip()
        if target_agent_id and target_agent_id != agent.id:
            return "target_agent_id_mismatch"
        target_agent_name = str(metadata.get("target_agent_name") or "").strip()
        if target_agent_name and target_agent_name != agent.name:
            return "target_agent_name_mismatch"
        if required_runtime_digest and agent.running_digest != required_runtime_digest:
            return "runtime_digest_mismatch"

        if break_glass_active:
            return None
        if not self._agent_resources_satisfy(agent, machine, task):
            return "agent_resources_insufficient"
        if not self._agent_has_repository_commands(agent, task):
            return "repository_commands_missing"
        coding_route_ok, coding_route_reason = self._agent_has_verified_coding_route(
            agent, task
        )
        if not coding_route_ok:
            return coding_route_reason
        if role_reason is not None:
            return role_reason
        return None

    def _task_required_runtime_digest_in_transaction(
        self,
        conn: Any,
        task: Task,
    ) -> Optional[str]:
        metadata = ensure_json_object(task.metadata)
        runtime_meta = ensure_json_object(metadata.get("runtime"))
        for value in (
            runtime_meta.get("required_runtime_digest"),
            runtime_meta.get("runtime_digest"),
            runtime_meta.get("base_runtime_digest"),
            metadata.get("required_runtime_digest"),
            metadata.get("runtime_digest"),
        ):
            digest = str(value or "").strip()
            if digest:
                return digest
        runtime_id = str(
            runtime_meta.get("runtime_environment_id")
            or runtime_meta.get("required_runtime_environment_id")
            or metadata.get("runtime_environment_id")
            or metadata.get("required_runtime_environment_id")
            or ""
        ).strip()
        if not runtime_id:
            return None
        conn.execute(
            "UPDATE runtime_environments SET updated_at = updated_at WHERE id = ?",
            (runtime_id,),
        )
        row = conn.execute(
            "SELECT digest FROM runtime_environments WHERE id = ?",
            (runtime_id,),
        ).fetchone()
        return str(row["digest"]) if row is not None else "__unknown_runtime_digest__"

    def _claim_role_ineligibility_reason_in_transaction(
        self,
        conn: Any,
        *,
        agent: Agent,
        task: Task,
        machine: Machine,
    ) -> Optional[str]:
        """Connection-local role, hardware, and soul eligibility snapshot."""

        def locked_role_by_id(role_id: str) -> Optional[Any]:
            conn.execute(
                "UPDATE agent_roles SET updated_at = updated_at WHERE id = ?",
                (role_id,),
            )
            return conn.execute(
                "SELECT * FROM agent_roles WHERE id = ?", (role_id,)
            ).fetchone()

        def locked_global_role(role_id_or_slug: str) -> Optional[Any]:
            row = conn.execute(
                "SELECT id FROM agent_roles WHERE id = ?",
                (role_id_or_slug,),
            ).fetchone()
            if row is None:
                row = conn.execute(
                    "SELECT id FROM agent_roles "
                    "WHERE slug = ? AND tenant_id IS NULL",
                    (role_id_or_slug,),
                ).fetchone()
            return locked_role_by_id(str(row["id"])) if row is not None else None

        metadata = ensure_json_object(task.metadata)
        required_role = str(metadata.get("required_role") or "").strip()
        target_role = locked_global_role(required_role) if required_role else None
        if required_role and target_role is None:
            return "required_role_unknown"

        bound_role = locked_role_by_id(agent.role_id) if agent.role_id else None
        if agent.role_id and bound_role is None:
            return "agent_role_unknown"
        if required_role:
            if bound_role is not None:
                if str(bound_role["slug"]) != required_role:
                    return "required_role_mismatch"
            else:
                target_caps = set(json_loads(target_role["required_capabilities"], []))
                if not target_caps.issubset(set(agent.capabilities)):
                    return "required_role_capabilities_missing"

        role_required_caps: set = set()
        if bound_role is not None:
            role_required_caps = set(
                json_loads(bound_role["required_capabilities"], [])
            )
            from mac.roles_service import machine_hardware_satisfies

            hardware_ok, _reasons = machine_hardware_satisfies(
                json_loads(bound_role["hardware_requirements"], {}),
                machine.hardware,
            )
            if not hardware_ok:
                return "role_hardware_insufficient"
            if not agent.hermes_instance_id:
                return "role_not_accepted_by_soul"
            conn.execute(
                "UPDATE hermes_instances SET updated_at = updated_at WHERE id = ?",
                (agent.hermes_instance_id,),
            )
            instance = conn.execute(
                "SELECT persona_id FROM hermes_instances WHERE id = ?",
                (agent.hermes_instance_id,),
            ).fetchone()
            if instance is None or not instance["persona_id"]:
                return "role_not_accepted_by_soul"
            persona_id = str(instance["persona_id"])
            conn.execute(
                "UPDATE personas SET updated_at = updated_at WHERE id = ?",
                (persona_id,),
            )
            persona = conn.execute(
                "SELECT name, metadata FROM personas WHERE id = ?",
                (persona_id,),
            ).fetchone()
            if persona is None:
                return "role_not_accepted_by_soul"
            persona_metadata = json_loads(persona["metadata"], {})
            explicit_slugs = persona_metadata.get("role_slugs")
            if isinstance(explicit_slugs, list) and explicit_slugs:
                allowed_slugs = {
                    str(value).strip().lower()
                    for value in explicit_slugs
                    if str(value).strip()
                }
            else:
                default_slug = (
                    str(persona["name"] or "")
                    .strip()
                    .lower()
                    .replace(" ", "-")
                    .replace("_", "-")
                )
                allowed_slugs = {default_slug} if default_slug else set()
            if str(bound_role["slug"]) not in allowed_slugs:
                return "role_not_accepted_by_soul"

        required_caps = set(task.required_capabilities) | role_required_caps
        if not required_caps.issubset(set(agent.capabilities)):
            return "capabilities_missing"
        return None

    def _agent_availability_for_task(
        self, agent: Agent, task: Task, *, allow_cooperative_reuse: bool = False
    ) -> Tuple[bool, str]:
        task_authorization = self._active_break_glass_authorization(task.id)
        break_glass = (
            task_authorization
            if task_authorization is not None
            and task_authorization.agent_id == agent.id
            else None
        )
        if task_authorization is not None and break_glass is None:
            return False, "break_glass_agent_mismatch"
        if agent.dispatch_hold and break_glass is None:
            return False, "agent_dispatch_held"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return False, "agent_status_unavailable"
        if agent.health_status != HealthStatus.HEALTHY.value:
            return False, "agent_health_unavailable"
        if not self.directives.agent_policy_ready(agent.id):
            return False, "directive_policy_unacknowledged"
        try:
            self._assert_current_read_only_report_task_contract(task)
        except ValidationError:
            return False, "report_repository_contract_invalid"
        if (
            metadata_declares_read_only_report_repository(task.metadata)
            and not agent_has_read_only_report_repository_executor(agent.resources)
        ):
            return False, "report_repository_executor_missing"
        # Hard safety exclusion used by crash-repair tasks: a worker must not
        # diagnose or approve a crash in the same revision that killed it.
        # Unlike cooperative distinctness this is not relaxed when the pool is
        # exhausted; the repair waits for an unaffected healthy peer.
        task_metadata = ensure_json_object(task.metadata)
        explicit_excluded = {
            str(value)
            for value in task_metadata.get("excluded_agent_ids", [])
            if str(value)
        } if isinstance(task_metadata.get("excluded_agent_ids"), list) else set()
        if agent.id in explicit_excluded:
            return False, "explicit_agent_excluded"
        # Distinct-executor separation is a *preference*, not a hard rule: when
        # the whole pool has already participated in the family, the dispatcher
        # relaxes it (allow_cooperative_reuse=True) rather than leaving the task
        # permanently undispatchable.  This mirrors the reviewer-independence
        # fallback the review path already has.
        if not allow_cooperative_reuse and agent.id in self._coordination_excluded_agent_ids(
            task
        ):
            return False, "cooperative_distinct_agent_excluded"
        target_agent_id = (
            task.metadata.get("target_agent_id")
            if isinstance(task.metadata, dict)
            else None
        )
        if target_agent_id and agent.id != str(target_agent_id):
            return False, "target_agent_id_mismatch"
        target_agent_name = (
            task.metadata.get("target_agent_name")
            if isinstance(task.metadata, dict)
            else None
        )
        if target_agent_name and agent.name != str(target_agent_name):
            return False, "target_agent_name_mismatch"
        required_runtime_digest = self._task_required_runtime_digest(task)
        if required_runtime_digest and agent.running_digest != required_runtime_digest:
            return False, "runtime_digest_mismatch"
        try:
            machine = self.get_machine(agent.machine_id)
        except NotFoundError:
            return False, "agent_machine_missing"
        if not machine.trusted:
            return False, "machine_untrusted"
        if self._agent_active_lease_count(agent.id) >= self._agent_capacity(agent):
            return False, "agent_capacity_full"
        if not self._machine_allows_tenant(machine, self._task_tenant_id(task)):
            return False, "machine_tenant_not_allowed"
        if break_glass is not None:
            # The operator selected this exact trusted host because ordinary
            # compatibility may itself be what needs repair: stale runtime
            # digests, missing sandbox-visible commands, broken coding-route
            # proofs, capabilities, roles, or task target hints.  Retain the
            # hard trust, health, status, capacity, and tenant boundaries above,
            # then bypass those task/agent compatibility checks only for this
            # short-lived authorization.
            return True, "break_glass_authorized"
        if not self._agent_resources_satisfy(agent, machine, task):
            return False, "agent_resources_insufficient"
        if not self._agent_has_repository_commands(agent, task):
            return False, "repository_commands_missing"
        coding_route_ok, coding_route_reason = self._agent_has_verified_coding_route(
            agent, task
        )
        if not coding_route_ok:
            return False, coding_route_reason
        # Role + hardware gates. Both no-op when neither the agent nor the
        # task carry role/hardware metadata, so the legacy capability path
        # below stays the dominant matcher for un-roled fleets.
        required_role = (
            task.metadata.get("required_role")
            if isinstance(task.metadata, dict)
            else None
        )
        if required_role:
            # Look up the target role first. An unknown role can never be
            # served, regardless of whether the agent is role-bound or a
            # multi-role dispatcher — fail closed.
            try:
                target_role = self.roles.get_role(str(required_role))
            except NotFoundError:
                return False, "required_role_unknown"
            if agent.role_id is not None:
                # Role-bound agent: keep the strict slug match so a tenant
                # using role-specific agents still gets the original
                # routing guarantee.
                try:
                    bound_role = self.roles.get_role(agent.role_id)
                except NotFoundError:
                    return False, "agent_role_unknown"
                if bound_role.slug != required_role:
                    return False, "required_role_mismatch"
            else:
                # Dispatcher case (job-per-task roles spec §6.1 Option B):
                # the runner agent has no role_id but carries the union of
                # role capabilities and re-attributes the work to a
                # role-specific identity at Job-launch time. Allow the
                # claim iff the dispatcher's capabilities cover the
                # target role's required_capabilities. The task-level
                # capabilities are still enforced by the union check at
                # the end of this method.
                if not set(target_role.required_capabilities).issubset(
                    set(agent.capabilities)
                ):
                    return False, "required_role_capabilities_missing"
        role_required_caps: set = set()
        if agent.role_id is not None:
            try:
                role = self.roles.get_role(agent.role_id)
            except NotFoundError:
                role = None
            if role is not None:
                ok, _reasons = self.roles.validate_hardware(role, machine)
                if not ok:
                    return False, "role_hardware_insufficient"
                # Soul-role compatibility is re-checked at dispatch time
                # rather than only at assignment time, so a persona edit
                # that narrows the allowed role list immediately stops
                # affected agents from being eligible.
                if not self.roles.soul_accepts_role(agent, role):
                    return False, "role_not_accepted_by_soul"
                role_required_caps = set(role.required_capabilities)
        capabilities = set(agent.capabilities)
        required = set(task.required_capabilities) | role_required_caps
        if not required.issubset(capabilities):
            return False, "capabilities_missing"
        return True, "matched"

    def _record_routing_skip(
        self,
        *,
        name: str,
        agent_id: Optional[str],
        task: Task,
        reason: str,
        route: str,
        candidate_rank: int,
        reason_class: str,
        dry_run: bool = False,
    ) -> None:
        self.record_log(
            name,
            level="debug",
            layer="control_plane",
            source=agent_id or route,
            subject_type="task",
            subject_id=task.id,
            detail={
                "agent_id": agent_id,
                "task_id": task.id,
                "reason": reason,
                "reason_class": reason_class,
                "route": route,
                "candidate_rank": candidate_rank,
                "dry_run": dry_run,
            },
        )

    def _agent_has_repository_commands(self, agent: Agent, task: Task) -> bool:
        metadata = ensure_json_object(task.metadata)
        required_commands = (
            _repository_host_required_commands_from_metadata(metadata)
            if _agent_requires_openshell(agent)
            else _repository_required_commands_from_metadata(metadata)
        )
        if not required_commands:
            return True
        available = _agent_resource_command_names(ensure_json_object(agent.resources))
        return set(required_commands).issubset(available)

    def _agent_has_verified_coding_route(
        self, agent: Agent, task: Task
    ) -> Tuple[bool, str]:
        """Require a fresh, exact in-sandbox route proof before repo dispatch."""
        if not self._task_is_repo_coupled(task) or not _agent_requires_openshell(agent):
            return True, "not_required"
        if not _truthy_env("MAC_OPENSHELL_REPO_REQUIRES_CODING_AGENT"):
            return True, "strict_route_verification_disabled"
        resources = ensure_json_object(agent.resources)
        coding = ensure_json_object(resources.get("coding_clis"))
        # A strict hub must fail closed while a worker is rolling forward. An
        # old configuration-only report cannot prove that the route works from
        # the actual sandbox, and accepting it would create a bypass precisely
        # when credentials or protocol settings are broken.
        if coding.get("schema") != "mac.coding_clis.v2":
            return False, "coding_agent_route_unreported"
        clis = ensure_json_object(coding.get("clis"))
        try:
            max_age = max(
                1.0,
                float(os.environ.get("MAC_CODING_ROUTE_MAX_AGE_SECONDS") or 1200.0),
            )
        except ValueError:
            max_age = 1200.0
        pinned_model = self._task_pinned_coding_model(task)
        saw_fresh_route = False
        for raw in clis.values():
            item = ensure_json_object(raw)
            if not (item.get("configured") is True and item.get("verified") is True):
                continue
            verification = ensure_json_object(item.get("verification"))
            checked_at = str(verification.get("checked_at") or "").strip()
            try:
                age = (parse_time(utcnow()) - parse_time(checked_at)).total_seconds()
            except Exception:  # noqa: BLE001 - malformed proof must fail closed.
                continue
            if age < 0 or age > max_age:
                continue
            if verification.get("route_fingerprint") != item.get("route_fingerprint"):
                continue
            saw_fresh_route = True
            if not pinned_model:
                return True, "verified"
            verified_model = str(
                verification.get("model") or item.get("model") or ""
            ).strip()
            verified_models = {
                str(value).strip()
                for value in (verification.get("verified_models") or [])
                if str(value).strip()
            }
            if verified_model == pinned_model or pinned_model in verified_models:
                return True, "verified"
        if pinned_model and saw_fresh_route:
            return False, "coding_agent_model_unverified"
        return False, "coding_agent_route_unverified"

    @staticmethod
    def _task_pinned_coding_model(task: Task) -> str:
        metadata = ensure_json_object(task.metadata)
        is_review = isinstance(metadata.get("review_context"), dict)
        key = "review_model" if is_review else "model"
        value = str(metadata.get(key) or "").strip()
        if value:
            return value[:256]
        runtime = ensure_json_object(metadata.get("runtime"))
        return str(runtime.get(key) or "").strip()[:256]

    def _task_required_runtime_digest(self, task: Task) -> Optional[str]:
        metadata = ensure_json_object(task.metadata)
        runtime = metadata.get("runtime")
        runtime_meta = ensure_json_object(runtime) if isinstance(runtime, dict) else {}
        for value in (
            runtime_meta.get("required_runtime_digest"),
            runtime_meta.get("runtime_digest"),
            runtime_meta.get("base_runtime_digest"),
            metadata.get("required_runtime_digest"),
            metadata.get("runtime_digest"),
        ):
            text = str(value or "").strip()
            if text:
                return text
        runtime_id = str(
            runtime_meta.get("runtime_environment_id")
            or runtime_meta.get("required_runtime_environment_id")
            or metadata.get("runtime_environment_id")
            or metadata.get("required_runtime_environment_id")
            or ""
        ).strip()
        if not runtime_id:
            return None
        try:
            return self.get_runtime(runtime_id).digest
        except NotFoundError:
            return "__unknown_runtime_digest__"

    def _default_review_policy(self, task: Task) -> JsonDict:
        metadata = ensure_json_object(task.metadata)
        for key in ("review", "default_review"):
            value = metadata.get(key)
            if isinstance(value, dict):
                return ensure_json_object(value)
        return {}

    def _default_review_required_capabilities(
        self,
        task: Task,
        policy: Optional[JsonDict] = None,
    ) -> List[str]:
        policy = ensure_json_object(policy or self._default_review_policy(task))
        required = set(_metadata_string_list(policy.get("required_capabilities")))
        if (
            policy.get("inherit_task_capabilities") is True
            or policy.get("inherit_required_capabilities") is True
        ):
            required.update(str(capability) for capability in task.required_capabilities)
        return sorted(required)

    def _default_review_disabled(self, task: Task) -> bool:
        policy = self._default_review_policy(task)
        mode = str(policy.get("mode") or policy.get("workflow") or "").strip().lower()
        return (
            mode == "manual"
            or policy.get("manual") is True
            or policy.get("auto") is False
            or policy.get("enabled") is False
        )

    def _default_review_evidence(self, task: Task) -> Tuple[Optional[Evidence], JsonDict]:
        evidence = self.list_evidence(task.id)
        if not evidence:
            return None, {"reason": "no_evidence"}
        successful = [
            item
            for item in evidence
            if self._evidence_returncode(item) == 0
        ]
        if not successful:
            return None, {"reason": "no_successful_evidence"}
        rejected: List[JsonDict] = []
        for item in reversed(successful):
            assessment = self._assess_default_review_evidence(task, item)
            if assessment["valid"]:
                return item, assessment
            rejected.append(
                {
                    "evidence_id": item.id,
                    "reason": assessment["reason"],
                    "problems": assessment.get("problems", []),
                }
            )
        return None, {
            "reason": "evidence_not_verifiable",
            "rejected_evidence": rejected[:5],
        }

    def _bound_review_evidence(self, task: Task) -> Tuple[Optional[Evidence], JsonDict]:
        """Resolve the immutable executor evidence target for this review attempt."""
        metadata = ensure_json_object(task.metadata)
        target = ensure_json_object(metadata.get("review_target"))
        target_id = str(target.get("executor_evidence_id") or "").strip()
        if target_id:
            try:
                evidence = self.get_evidence(target_id)
            except NotFoundError:
                return None, {
                    "reason": "review_target_missing",
                    "executor_evidence_id": target_id,
                }
            assessment = self._assess_default_review_evidence(task, evidence)
            if assessment.get("valid"):
                return evidence, assessment
            return None, {
                "reason": "bound_evidence_not_verifiable",
                "executor_evidence_id": target_id,
                "problems": assessment.get("problems", []),
            }

        # Rolling-upgrade compatibility for tasks that entered NEEDS_REVIEW
        # before review_target existed. Bind once, then never follow newer rows.
        evidence, assessment = self._default_review_evidence(task)
        if evidence is not None:
            metadata["review_target"] = {
                "executor_evidence_id": evidence.id,
                "attempt_count": task.attempt_count,
                "recorded_at": utcnow(),
            }
            self.store.execute(
                "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                (json_dumps(metadata), utcnow(), task.id),
            )
        return evidence, assessment

    def _assess_default_review_evidence(self, task: Task, evidence: Evidence) -> JsonDict:
        if self._evidence_returncode(evidence) != 0:
            return {
                "valid": False,
                "reason": "executor_not_successful",
                "problems": ["evidence returncode is not zero"],
            }
        manifest = evidence.metadata.get("verification") or evidence.metadata.get("mac_evidence")
        if not isinstance(manifest, dict):
            return {
                "valid": False,
                "reason": "missing_verification_manifest",
                "problems": ["evidence metadata lacks verification manifest"],
            }
        problems: List[str] = []
        schema = str(manifest.get("schema") or "").strip()
        if schema != VERIFICATION_SCHEMA:
            problems.append("verification.schema must be %s" % VERIFICATION_SCHEMA)
        # Canonical names only (mac-q38). Aliases were a maintainability
        # multiplier — every alias is a separate door downstream
        # validation must remember. Status must be ``complete``; the
        # alternative aliases (verified/pass/passed) are rejected at the
        # boundary. Same for evidence_type below.
        status = str(manifest.get("status") or "").strip().lower()
        if status != "complete":
            problems.append('verification.status must be "complete"')
        evidence_type = str(manifest.get("evidence_type") or "").strip().lower()
        if not evidence_type:
            problems.append("verification.evidence_type is required")
        if problems:
            return {
                "valid": False,
                "reason": "invalid_verification_manifest",
                "evidence_type": evidence_type or None,
                "problems": problems,
            }
        if evidence_type == "review_verdict":
            return {
                "valid": False,
                "reason": "review_verdict_is_not_executor_evidence",
                "evidence_type": evidence_type,
                "problems": ["review_verdict evidence only satisfies the reviewer verdict gate"],
            }
        # Root of trust (mac-ng2). The verification manifest must carry
        # ``signed_by`` (an agent_id) and ``signature`` (HMAC v1) made
        # with that agent's attestation key. Without this any executor
        # could self-approve by writing valid-looking JSON. Verification
        # is per-agent: the signer's key must be on file in the
        # ``agents.attestation_key_ciphertext`` column.
        signed_by = str(manifest.get("signed_by") or "").strip()
        signature = str(manifest.get("signature") or "").strip()
        if not signed_by or not signature:
            return {
                "valid": False,
                "reason": "manifest_not_signed",
                "evidence_type": evidence_type,
                "problems": ["verification.signed_by and verification.signature are required"],
            }
        signer_key = self._agent_attestation_key(signed_by)
        if signer_key is None:
            return {
                "valid": False,
                "reason": "signer_unknown",
                "evidence_type": evidence_type,
                "problems": ["verification.signed_by does not match a known agent with an attestation key"],
            }
        if not verify_verification_manifest_signature(signer_key, manifest, signature):
            # Key-rotation tolerance (mac-s2vz, extended): if the signer was
            # re-keyed AFTER this evidence was signed (e.g. a gateway redeploy
            # rotated the executor's key mid-review — the exact 2026-07-14
            # incident), verify against the retained previous key. Without this
            # the ALREADY-BOUND review_target evidence is rejected every sweep
            # tick and the task parks in waiting_for_verifiable_evidence forever.
            # Mirrors the fallback already in _find_review_verdict_evidence.
            rotated_ok = False
            rotation_row = self.store.query_one(
                "SELECT attestation_key_rotated_at FROM agents WHERE id = ?",
                (signed_by,),
            )
            rotated_at = rotation_row["attestation_key_rotated_at"] if rotation_row else None
            if rotated_at and getattr(evidence, "created_at", None):
                try:
                    predates = parse_time(rotated_at) > parse_time(evidence.created_at)
                except ValueError:
                    predates = False
                if predates:
                    prev_key = self._agent_attestation_prev_key(signed_by)
                    if prev_key is not None:
                        rotated_ok = verify_verification_manifest_signature(
                            prev_key, manifest, signature
                        )
            if not rotated_ok:
                return {
                    "valid": False,
                    "reason": "signature_invalid",
                    "evidence_type": evidence_type,
                    "problems": ["verification.signature does not verify against signed_by's attestation key"],
                }
        type_problems = self._verification_type_problems(task, manifest, evidence_type)
        if type_problems:
            # Option C — deferred test gate: when hub verify is enabled and the
            # executor declared its tests as deferred to the hub (at least one
            # test item carries status="deferred" and no item already passed),
            # accept the evidence so the hub verify path is triggered.  Hub
            # verify will run the full contract test and record an authoritative
            # signed verdict.  The sole expected failure at this point is the
            # absence of a passing test; any other problem (missing repo anchor,
            # dirty worktree, codegraph failure) is a real defect that must
            # still be rejected.
            #
            # Option A (MAC_REVIEW_HUB_VERIFY unset) is completely unchanged —
            # the executor must always supply its own passing tests.
            if (
                _hub_review_verify_enabled()
                and self._evidence_tests_are_hub_verify_deferred(evidence)
                and all(
                    "passing test" in p or "passing check" in p
                    for p in type_problems
                )
            ):
                return {
                    "valid": True,
                    "reason": "verification_contract_satisfied_pending_hub_verify",
                    "evidence_type": evidence_type,
                    "signed_by": signed_by,
                    "verified_by": "default-review-evidence-v1",
                    "hub_verify_deferred": True,
                }
            return {
                "valid": False,
                "reason": "verification_contract_failed",
                "evidence_type": evidence_type,
                "problems": type_problems,
            }
        return {
            "valid": True,
            "reason": "verification_contract_satisfied",
            "evidence_type": evidence_type,
            "signed_by": signed_by,
            "verified_by": "default-review-evidence-v1",
        }

    def _verification_type_problems(
        self,
        task: Task,
        manifest: JsonDict,
        evidence_type: str,
    ) -> List[str]:
        problems = validate_evidence_type(
            evidence_type,
            manifest,
            passed_check_count=self._passed_verification_check_count,
            allow_empty_repo_change=self._allows_empty_repo_change_evidence(task, evidence_type),
            repo_coupled=self._task_is_repo_coupled(task),
            require_tests=self._task_requires_tests(task),
        )
        problems.extend(self._required_changed_file_problems(task, manifest))
        return problems

    def _required_changed_file_problems(self, task: Task, manifest: JsonDict) -> List[str]:
        required = _required_changed_files_from_metadata(ensure_json_object(task.metadata))
        if not required:
            return []
        repo = manifest.get("repo") if isinstance(manifest.get("repo"), dict) else {}
        changed = _metadata_path_list(repo.get("files_changed")) if isinstance(repo, dict) else []
        missing = [
            path
            for path in required
            if not any(_repo_path_satisfies_requirement(item, path) for item in changed)
        ]
        if not missing:
            return []
        return [
            "repo evidence missing required changed files: %s" % ", ".join(missing)
        ]

    def _allows_empty_repo_change_evidence(self, task: Task, evidence_type: str) -> bool:
        if str(evidence_type or "").strip().lower() != "repo_change":
            return False
        metadata = ensure_json_object(task.metadata)
        origin = ensure_json_object(metadata.get("origin"))
        remediation = ensure_json_object(metadata.get("remediation"))
        return origin.get("type") == "beads_source_remediation" or remediation.get(
            "type"
        ) == "beads_source_refresh"

    def _task_is_repo_coupled(self, task: Task) -> bool:
        """mem-11: True when the task carries a repository_contract — a code task
        expected to produce a pushed repo change. ``operator_result`` evidence is
        rejected for such tasks (the verified task_d7c51a0b jam was a code task
        that emitted a free-text operator_result with no commit/push)."""
        metadata = ensure_json_object(task.metadata)
        # An explicitly declared report/answer task is non-code; operator_result
        # is its correct evidence type, so it is not repo-coupled here.
        if metadata_declares_report_deliverable(metadata):
            return False
        for path in (
            ("execution_contract", "repository_contract"),
            ("origin", "repository_contract"),
            ("repository_contract",),
        ):
            contract = _nested_json_object(metadata, *path)
            if isinstance(contract, dict) and contract:
                return True
        return False

    def _task_requires_tests(self, task: Task) -> bool:
        """mac-wjy3: True when the task's repository_contract explicitly lists
        ``tests`` in its required evidence. Conservative — config/remediation
        tasks (which don't opt in) are unaffected; only contracts that demand
        tests reject a tests:null manifest."""
        metadata = ensure_json_object(task.metadata)
        for path in (
            ("execution_contract", "repository_contract"),
            ("origin", "repository_contract"),
            ("repository_contract",),
        ):
            contract = _nested_json_object(metadata, *path)
            if not isinstance(contract, dict) or not contract:
                continue
            evidence = ensure_json_object(contract.get("evidence"))
            required = evidence.get("required") if isinstance(evidence.get("required"), list) else []
            if any(str(r).strip().lower() in {"tests", "test"} for r in required):
                return True
        return False

    def _require_pushed_repo_anchor(self, manifest: JsonDict) -> List[str]:
        # Canonical field names only (mac-q38). The previous code
        # accepted ``git``/``commit``/``commit_sha``/``changed_files``/
        # ``pushed_ref``/``pull_request_url``/etc. — each alias is a
        # separate doorway. Single canonical schema:
        #   verification.repo: { head_sha, files_changed, dirty, pushed,
        #                        remote_ref, pr_url? }
        repo = manifest.get("repo")
        if not isinstance(repo, dict):
            return ["repo evidence requires verification.repo object"]
        problems: List[str] = []
        head_sha = str(repo.get("head_sha") or "").strip()
        if not _GIT_SHA_RE.match(head_sha):
            problems.append("repo.head_sha must be a git SHA")
        dirty = repo.get("dirty")
        if dirty not in {False, "false", "False", 0, "0"}:
            problems.append("repo evidence must declare dirty=false")
        pushed = repo.get("pushed") is True or str(repo.get("pushed") or "").lower() == "true"
        remote_ref = str(repo.get("remote_ref") or "").strip()
        pr_url = str(repo.get("pr_url") or "").strip()
        if not (pushed and remote_ref) and not pr_url:
            problems.append("repo evidence requires pushed=true with remote_ref, or pr_url")
        return problems

    def _passed_verification_check_count(self, manifest: JsonDict) -> int:
        # Canonical names only (mac-q38): ``tests`` and ``checks``.
        # ``test_runs`` was an alias; rejecting it here.
        count = 0
        for item in self._verification_item_candidates(manifest.get("tests")):
            if self._verification_item_passed(item):
                count += 1
        for item in self._verification_item_candidates(manifest.get("checks")):
            if self._verification_item_passed(item):
                count += 1
        return count

    def _verification_item_candidates(self, value: Any) -> List[Any]:
        if value is None:
            return []
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            return [value]
        return []

    def _verification_item_passed(self, item: Any) -> bool:
        # Keep repo fields canonical, but accept common structured pass/fail
        # spellings for test/check result objects. Agents and tools naturally
        # emit "result=passed", booleans, and nested smoke/full-suite records;
        # rejecting those equivalent facts caused good pushed work to dead-letter.
        if isinstance(item, list):
            return any(self._verification_item_passed(nested) for nested in item)
        if not isinstance(item, dict):
            return False
        if "returncode" in item:
            return self._verification_int_value(item["returncode"]) == 0
        failed = self._verification_int_value(item.get("failed"))
        if failed is not None and failed > 0:
            return False
        if str(item.get("status") or "").strip().lower() in {
            "pass",
            "passed",
            "success",
            "successful",
            "succeeded",
            "ok",
        }:
            return True
        if str(item.get("result") or "").strip().lower() in {
            "pass",
            "passed",
            "success",
            "successful",
            "succeeded",
            "ok",
        }:
            return True
        if str(item.get("outcome") or "").strip().lower() in {
            "pass",
            "passed",
            "success",
            "successful",
            "succeeded",
            "ok",
        }:
            return True
        for key in ("passed", "success", "succeeded", "ok", "satisfied"):
            value = item.get(key)
            if value is True:
                return True
            number = self._verification_int_value(value)
            if number is not None and number > 0 and failed == 0:
                return True
        bool_values = [value for value in item.values() if isinstance(value, bool)]
        if bool_values and len(bool_values) == len(item) and all(bool_values):
            return True
        return any(
            self._verification_item_passed(nested)
            for nested in item.values()
            if isinstance(nested, (dict, list))
        )

    def _verification_int_value(self, value: Any) -> Optional[int]:
        try:
            if isinstance(value, bool):
                return int(value)
            return int(value)
        except (TypeError, ValueError):
            return None

    def _evidence_returncode(self, evidence: Evidence) -> Optional[int]:
        value = evidence.metadata.get("returncode")
        if value is None:
            return None
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _evidence_tests_are_hub_verify_deferred(evidence: "Evidence") -> bool:
        """Return True when the executor evidence declares its tests as deferred
        to hub verify — i.e. at least one test item carries status='deferred'
        and no test item is already passing.  This signals that the executor
        intentionally skipped the local contract test and expects hub verify
        (Option C) to supply the authoritative result.

        Only repo_change evidence participates: other evidence types do not
        have a hub-verify path and must always supply their own passing tests.
        """
        meta = ensure_json_object(evidence.metadata)
        verification = ensure_json_object(meta.get("verification"))
        evidence_type = str(verification.get("evidence_type") or "").strip().lower()
        if evidence_type not in {"repo_change", "documentation", "test"}:
            return False
        tests = verification.get("tests")
        if not isinstance(tests, list) or not tests:
            return False
        has_deferred = any(
            isinstance(item, dict)
            and str(item.get("status") or "").strip().lower() == "deferred"
            for item in tests
        )
        if not has_deferred:
            return False
        # If any test already passed, hub verify is not needed — the executor
        # already completed the test and the deferred item is stale/incidental.
        has_passing = any(
            isinstance(item, dict)
            and str(item.get("status") or "").strip().lower() in {
                "pass", "passed", "success", "successful", "succeeded", "ok",
            }
            for item in tests
        )
        return not has_passing

    def _hub_verify_repo_info(
        self, task: Task, executor_evidence: Evidence
    ) -> Optional[Dict[str, Any]]:
        """Extract the pushed-branch coordinates the hub verifier needs: the
        remote (evidence repo.remote_url, else the task's canonical contract
        remote), the branch, and head_sha. Returns None when the evidence is
        not a pushed repo change (nothing to independently verify).

        Deferred test items: evidence that carries a test item with
        status="deferred" (the executor deferred test execution to hub verify)
        is accepted here provided repo.pushed is True and the branch/sha are
        present.  The caller will run the contract test and record the verdict.
        """
        from . import gitops as _gitops

        meta = ensure_json_object(executor_evidence.metadata)
        verification = ensure_json_object(meta.get("verification"))
        repo = ensure_json_object(verification.get("repo"))
        # The task contract is the canonical, credential-free source of truth.
        # Executor evidence may contain a display-redacted push URL such as
        # ``https://x-access-token:<redacted>@github.com/...``; cloning that
        # literal string fails authentication even for a public repository.
        remote_url = ""
        md = ensure_json_object(task.metadata)
        for path in (
            ("execution_contract", "repository_contract"),
            ("origin", "repository_contract"),
            ("repository_contract",),
            ("origin",),
        ):
            node = _nested_json_object(md, *path)
            remote_url = str(
                node.get("canonical_remote_url") or node.get("repository_url") or ""
            ).strip()
            if remote_url:
                break
        if not remote_url:
            remote_url = str(repo.get("remote_url") or "").strip()
        remote_url = _gitops.strip_git_remote_auth(remote_url)
        head_sha = str(repo.get("head_sha") or "").strip()
        remote_ref = str(repo.get("remote_ref") or "").strip()
        branch = remote_ref[len("refs/heads/"):] if remote_ref.startswith("refs/heads/") else remote_ref
        if not remote_url or not _GIT_SHA_RE.match(head_sha) or not branch:
            return None
        if repo.get("pushed") is not True:
            return None
        files_changed = repo.get("files_changed")
        trusted_files = (
            [str(path) for path in files_changed if isinstance(path, str)]
            if isinstance(files_changed, list)
            else []
        )
        return {
            "remote_url": remote_url,
            "head_sha": head_sha,
            "branch": branch,
            "files_changed": trusted_files,
        }

    def _hub_verify_run_contract_test(
        self, remote_url: str, branch: str, head_sha: str, test_command: str
    ) -> Tuple[int, str]:
        """Clone the pushed branch and run the contract test in an isolated
        OpenShell sandbox on the hub. Returns (returncode, tail_of_output).

        Isolation is mandatory: this executes pushed (agent-authored) test code
        on the control-plane node, so it must not run on the hub host. Injected
        via MAC_HUB_VERIFY_RUNNER-style override in tests (see the
        ``_hub_verify_runner`` hook) so unit tests need no git/OpenShell."""
        runner = getattr(self, "_hub_verify_runner", None)
        if runner is not None:
            return runner(remote_url, branch, head_sha, test_command)
        from . import gitops as _gitops

        auth_url = _gitops.inject_git_remote_auth(remote_url)
        openshell = (os.environ.get("MAC_OPENSHELL_BIN") or "openshell").strip() or "openshell"
        image = (os.environ.get("MAC_HUB_VERIFY_IMAGE") or "localhost/mac-hermes:net").strip()
        policy = (os.environ.get("MAC_OPENSHELL_POLICY") or "").strip()
        try:
            timeout = float(os.environ.get("MAC_HUB_VERIFY_TIMEOUT", "1200"))
        except ValueError:
            timeout = 1200.0
        if _truthy_env("MAC_OPENSHELL_GC"):
            try:
                from mac.openshell_sandbox_gc import reconcile_stale_sandboxes

                try:
                    stale_after = float(
                        os.environ.get("MAC_OPENSHELL_STALE_AFTER_SECONDS") or "86400"
                    )
                except ValueError:
                    stale_after = 86400.0
                reconcile_stale_sandboxes(
                    openshell_bin=openshell,
                    stale_after_seconds=max(0.0, stale_after),
                    include_legacy=True,
                    apply=True,
                )
            except Exception as exc:  # noqa: BLE001 - verification remains guarded
                logging.getLogger(__name__).warning(
                    "OpenShell sandbox GC failed before hub verification: %s", exc
                )
        import uuid as _uuid

        tmp = Path(tempfile.mkdtemp(prefix="mac-hubverify-"))
        # Unique per invocation: the review sweep may re-tick while a verify is
        # still running, and a head_sha-derived name collides ("already
        # exists"). The in-flight guard in the caller also prevents overlap,
        # but a unique name is the belt-and-suspenders.
        name = "mac-hubverify-%s" % _uuid.uuid4().hex[:16]
        try:
            clone = subprocess.run(
                # Shallow single-branch clone keeps the upload into the sandbox
                # small (a deep clone's history broke the tar-over-ssh upload
                # with a broken pipe).
                ["git", "clone", "--branch", branch, "--depth", "1", "--single-branch",
                 "--", auth_url, str(tmp / "repo")],
                capture_output=True, text=True, timeout=300, check=False,
            )
            if clone.returncode != 0:
                return 1, "hub verify clone failed: %s" % _gitops.redact_git_remote_auth_in_text(
                    (clone.stderr or clone.stdout or "").strip()
                )[-800:]
            # Upload ONE tar file and extract inside the sandbox. Uploading the
            # directory tree loses .git in transit (OpenShell's upload drops
            # it), which failed every git-at-checkout contract test — and, once
            # the exit-97 probe landed, every verify outright with
            # "/sandbox/repo is not a usable git repo after upload". A single
            # archive survives any upload path verbatim, .git included.
            tar = subprocess.run(
                ["tar", "czf", str(tmp / "repo.tgz"), "-C", str(tmp), "repo"],
                capture_output=True, text=True, timeout=120, check=False,
            )
            if tar.returncode != 0:
                return 1, "hub verify tar failed: %s" % (
                    (tar.stderr or tar.stdout or "").strip()
                )[-800:]
            subprocess.run([openshell, "sandbox", "delete", name],
                           capture_output=True, text=True, timeout=60, check=False)
            argv = [openshell, "sandbox", "create", "--no-auto-providers"]
            if policy:
                argv += ["--policy", policy]
            argv += [
                "--name", name,
                "--label", "mac.owner=mac",
                "--label", "mac.kind=hubverify",
                "--label", "mac.pid=%d" % os.getpid(),
                "--label", "mac.keep=false",
                "--from", image, "--env", "HOME=/tmp",
                # OpenShell's supervisor resets PATH on fresh create/exec
                # commands instead of preserving the image ENV. Pass the
                # sandbox-owned runtime path explicitly; never inherit the
                # control-plane host's PATH.
                "--env", "PATH=%s" % SANDBOX_BASE_PATH,
                "--upload", "%s:%s" % (str(tmp / "repo.tgz"), "/sandbox"),
                "--", "/bin/bash", "-c",
                "export PATH=%s; hash -r 2>/dev/null || true; "
                "cd /sandbox && tar xzf repo.tgz && %scd /sandbox/repo && %s" % (
                    SANDBOX_BASE_PATH,
                    _HUB_VERIFY_GIT_PREFLIGHT,
                    test_command or "scripts/run-contract-tests.sh",
                ),
            ]
            try:
                proc = subprocess.run(argv, capture_output=True, text=True, timeout=timeout, check=False)
                out = (proc.stdout or "") + (proc.stderr or "")
                return int(proc.returncode), out[-2000:]
            finally:
                subprocess.run([openshell, "sandbox", "delete", name], capture_output=True, text=True, timeout=60, check=False)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def _run_hub_review_verification(
        self, task: Task, review: Review, executor_evidence: Evidence, actor: str
    ) -> Optional[Evidence]:
        """Produce a signed review_verdict by running the contract test on the
        hub (Option C), on behalf of the selected reviewer. No-op returning None
        when the evidence isn't a pushed repo change or the reviewer has no key
        (the workflow then falls back to the agent-nudge path)."""
        try:
            current_task = self.get_task(task.id)
            current_review = self.get_review(review.id)
        except NotFoundError:
            return None
        if current_review.status != ReviewStatus.PENDING.value:
            if current_review.evidence_id:
                try:
                    return self.get_evidence(current_review.evidence_id)
                except NotFoundError:
                    return None
            return None
        if current_task.state == TaskState.COMPLETED.value:
            return None
        assignment = ensure_json_object(
            ensure_json_object(task.metadata).get("review_experiment")
        )
        if assignment.get("schema") == "mac.review_experiment.v1":
            # A hub contract-test verdict is useful as a deterministic gate but
            # it is not a semantic second-model review.  Let the normal reviewer
            # nudge path run so experiment observations measure an actual model
            # pass instead of attributing the hub's test result to that agent.
            self._record_default_review_observation(
                task.id,
                "workflow.default_review.hub_verify_skipped",
                "info",
                {
                    "reason": "experiment_requires_semantic_reviewer",
                    "review_id": review.id,
                    "experiment_id": str(assignment.get("experiment_id") or ""),
                },
                actor,
            )
            return None
        info = self._hub_verify_repo_info(task, executor_evidence)
        if info is None:
            return None
        key = self._agent_attestation_key(review.reviewer_agent_id)
        if not key:
            return None
        existing = self._existing_hub_review_verification_evidence(
            task.id,
            current_review,
            executor_evidence.id,
            info["head_sha"],
        )
        if existing is not None:
            self._record_default_review_observation(
                task.id,
                "workflow.default_review.hub_verify_idempotent",
                "info",
                {
                    "review_id": review.id,
                    "verdict_evidence_id": existing.id,
                    "reason": "existing_hub_verdict",
                },
                actor,
            )
            return existing
        # In-flight guard: the review sweep re-ticks (~30s) while a verify runs
        # for minutes; without this, each tick would launch another concurrent
        # sandbox for the same review. One verify per review at a time.
        inflight = getattr(self, "_hub_verify_inflight", None)
        if inflight is None:
            inflight = self._hub_verify_inflight = set()
        if review.id in inflight:
            return None
        inflight.add(review.id)
        try:
            return self._run_hub_review_verification_locked(
                task, review, executor_evidence, actor, info, key
            )
        finally:
            inflight.discard(review.id)

    def _hub_review_verification_uri(self, review_id: str, head_sha: str) -> str:
        return "hub-verify://%s/%s" % (review_id, head_sha[:12])

    def _hub_review_test_command(self, task: Task, info: Mapping[str, Any]) -> str:
        """Choose the explicit sanity contract when changed paths are trustworthy.

        Older branches and repositories without the contract still run their
        full configured command. Unsafe or absent paths also fail closed to the
        full command rather than becoming shell input.
        """

        configured = _repository_contract_test_command_for_task(task)
        full_command = configured or "scripts/run-contract-tests.sh"
        if configured and configured not in {
            "scripts/run-contract-tests.sh",
            "./scripts/run-contract-tests.sh",
        }:
            return configured
        raw_files = info.get("files_changed")
        if not isinstance(raw_files, list) or not raw_files:
            return full_command
        safe_files: list[str] = []
        for raw in raw_files:
            value = str(raw or "").strip().replace("\\", "/")
            parts = value.split("/")
            if (
                not value
                or value.startswith("/")
                or any(part in {"", ".", ".."} for part in parts)
                or any(ord(char) < 32 for char in value)
            ):
                return full_command
            safe_files.append(value)
        changed_args = " ".join(
            "--changed-file %s" % shlex.quote(path) for path in sorted(set(safe_files))
        )
        return (
            "if [ -x scripts/run-sanity-tests.sh ]; then "
            "scripts/run-sanity-tests.sh %s; else %s; fi"
            % (changed_args, full_command)
        )

    def _matches_hub_review_verification_evidence(
        self,
        evidence: Evidence,
        *,
        task_id: str,
        reviewer_agent_id: str,
        executor_evidence_id: str,
        review_id: str,
        head_sha: str,
    ) -> bool:
        if evidence.task_id != task_id or evidence.kind != "review":
            return False
        if evidence.created_by != reviewer_agent_id:
            return False
        if evidence.uri != self._hub_review_verification_uri(review_id, head_sha):
            return False
        metadata = ensure_json_object(evidence.metadata)
        if metadata.get("hub_verified") is not True:
            return False
        manifest = metadata.get("verification")
        if not isinstance(manifest, dict):
            return False
        if str(manifest.get("evidence_type") or "").strip().lower() != "review_verdict":
            return False
        if str(manifest.get("reviewed_evidence_id") or "").strip() != executor_evidence_id:
            return False
        if str(manifest.get("verified_by") or "").strip() != "hub_review_verifier_v1":
            return False
        manifest_review_id = str(manifest.get("review_id") or "").strip()
        if manifest_review_id and manifest_review_id != review_id:
            return False
        repo = manifest.get("repo")
        if not isinstance(repo, dict):
            return False
        return str(repo.get("head_sha") or "").strip() == head_sha

    def _existing_hub_review_verification_evidence(
        self,
        task_id: str,
        review: Review,
        executor_evidence_id: str,
        head_sha: str,
    ) -> Optional[Evidence]:
        candidates: List[Evidence] = []
        if review.evidence_id:
            try:
                candidates.append(self.get_evidence(review.evidence_id))
            except NotFoundError:
                pass
        candidates.extend(reversed(self.list_evidence(task_id)))
        seen: set[str] = set()
        for candidate in candidates:
            if candidate.id in seen:
                continue
            seen.add(candidate.id)
            if not self._matches_hub_review_verification_evidence(
                candidate,
                task_id=task_id,
                reviewer_agent_id=review.reviewer_agent_id,
                executor_evidence_id=executor_evidence_id,
                review_id=review.id,
                head_sha=head_sha,
            ):
                continue
            verdict, _problems = self._find_review_verdict_evidence(
                task_id,
                review.reviewer_agent_id,
                executor_evidence_id=executor_evidence_id,
                verdict_evidence_id=candidate.id,
                not_before=review.created_at,
            )
            if verdict is not None:
                return verdict
        return None

    def _run_hub_review_verification_locked(
        self, task: Task, review: Review, executor_evidence: Evidence, actor: str,
        info: Mapping[str, Any], key: str,
    ) -> Optional[Evidence]:
        # The repository-owned selector combines changed/CodeGraph tests with
        # public and process-E2E canaries, and itself falls back to the full
        # suite for broad or uncertain changes. This keeps the independent hub
        # environment without unconditionally duplicating mainline coverage.
        test_command = self._hub_review_test_command(task, info)
        try:
            returncode, output = self._hub_verify_run_contract_test(
                info["remote_url"], info["branch"], info["head_sha"], test_command
            )
        except Exception as exc:  # noqa: BLE001 - a verify crash must not wedge the workflow
            self._record_default_review_observation(
                task.id, "workflow.default_review.hub_verify_error", "warning",
                {"review_id": review.id, "error": str(exc)[:300]}, actor,
            )
            return None
        verdict = "approved" if returncode == 0 else "rejected"
        current_review = self.get_review(review.id)
        existing = self._existing_hub_review_verification_evidence(
            task.id,
            current_review,
            executor_evidence.id,
            info["head_sha"],
        )
        if existing is not None:
            self._record_default_review_observation(
                task.id,
                "workflow.default_review.hub_verify_idempotent",
                "info",
                {
                    "review_id": review.id,
                    "verdict_evidence_id": existing.id,
                    "reason": "existing_hub_verdict_after_run",
                },
                actor,
            )
            return existing
        if (
            current_review.status != ReviewStatus.PENDING.value
            or self.get_task(task.id).state == TaskState.COMPLETED.value
        ):
            self._record_default_review_observation(
                task.id,
                "workflow.default_review.hub_verify_idempotent",
                "info",
                {
                    "review_id": review.id,
                    "review_status": current_review.status,
                    "reason": "review_no_longer_pending",
                },
                actor,
            )
            return None
        manifest: Dict[str, Any] = {
            "schema": VERIFICATION_SCHEMA,
            "status": "complete",
            "evidence_type": "review_verdict",
            "verdict": verdict,
            "review_id": review.id,
            "reviewed_evidence_id": executor_evidence.id,
            "worktree_digest": "sha256:%s" % hashlib.sha256(info["head_sha"].encode()).hexdigest(),
            "verified_by": "hub_review_verifier_v1",
            # Pushed-branch anchor for the verdict — the exact commit the hub
            # cloned and tested (mirrors the reviewed executor evidence).
            "repo": {
                "head_sha": info["head_sha"],
                "dirty": False,
                "pushed": True,
                "remote_ref": "refs/heads/%s" % info["branch"],
                # Mirror the reviewed change's file set — the verdict attests to
                # the same commit's files.
                "files_changed": _nested_json_object(
                    ensure_json_object(executor_evidence.metadata), "verification", "repo"
                ).get("files_changed") or [],
            },
            "tests": [
                {
                    "name": "hub contract verification",
                    "command": test_command or "scripts/run-contract-tests.sh",
                    "returncode": int(returncode),
                    "status": "pass" if returncode == 0 else "fail",
                }
            ],
            "signed_by": review.reviewer_agent_id,
        }
        # Carry the reviewed commit's codegraph audit (source/build changes
        # require it); the hub verified the same tree, so the executor's audit
        # result is the applicable one.
        exec_codegraph = _nested_json_object(
            ensure_json_object(executor_evidence.metadata), "verification"
        ).get("codegraph")
        if isinstance(exec_codegraph, dict) and exec_codegraph:
            manifest["codegraph"] = exec_codegraph
        if verdict == "rejected":
            manifest["feedback"] = "hub contract verification failed: %s" % (output[-500:] or "nonzero exit")
        manifest["signature"] = sign_verification_manifest(key, manifest)
        evidence = self.add_evidence(
            task.id,
            "review",
            self._hub_review_verification_uri(review.id, info["head_sha"]),
            "hub review verification: %s (rc=%d)" % (verdict, returncode),
            review.reviewer_agent_id,
            metadata={"returncode": 0, "verification": manifest, "hub_verified": True},
        )
        self._record_default_review_observation(
            task.id, "workflow.default_review.hub_verified", "info",
            {"review_id": review.id, "verdict": verdict, "returncode": returncode,
             "reviewer_agent_id": review.reviewer_agent_id}, actor,
        )
        if verdict == "rejected":
            self._record_review_outcome_lesson(
                task.id,
                outcome="review_rejected",
                detail=str(manifest.get("feedback") or "hub contract verification failed")[:300],
            )
        # The verdict is the event that unlocks the next stage (publish on
        # approval / feedback on rejection) — advance now, not on the next sweep.
        self._nudge_review_workflow(task.id)
        return evidence

    def _default_review_for_task(self, task_id: str) -> Optional[Review]:
        """Return the unambiguous review row to act on, or None.

        Refuses to pick when the task has more than one pending review
        (mac-d9c) — that's an ambiguous state and in an autonomous
        swarm there's no operator to break the tie. The caller logs
        ``workflow.default_review.ambiguous`` and leaves the task
        alone for explicit resolution.
        """
        reviews = self.list_reviews(task_id)
        if not reviews:
            return None
        pending = [review for review in reviews if review.status == ReviewStatus.PENDING.value]
        if len(pending) > 1:
            return None
        if pending:
            return pending[0]
        approved = [review for review in reviews if review.status == ReviewStatus.APPROVED.value]
        if approved:
            return approved[-1]
        return None

    def _review_verdict_nudge_payload(
        self,
        task_id: str,
        review: Review,
        evidence: Evidence,
    ) -> JsonDict:
        return {
            "task_id": task_id,
            "review_id": review.id,
            "executor_evidence_id": evidence.id,
            "reason": "produce_review_verdict",
        }

    def _ensure_review_verdict_nudge(
        self,
        task_id: str,
        review: Review,
        evidence: Evidence,
    ) -> Optional[AgentMessage]:
        # mac-ykkc: cap the number of times this review can be
        # re-nudged. Without the cap a reviewer that keeps failing to
        # produce a verdict (e.g. because the executor's lease branch
        # never made it to origin) ends up with hundreds of delivered
        # nudges as the dispatcher recreates the message on every tick.
        # Count those durable delivery attempts directly: review claims are
        # idempotent and therefore cannot serve as an attempt counter. After
        # the cap, retract the review with
        # a clear reason so the parent task transitions back to OPEN
        # or FAILED instead of spinning forever.
        try:
            attempt_count = int(os.environ.get("MAC_REVIEW_NUDGE_MAX_ATTEMPTS", "10"))
        except ValueError:
            attempt_count = 10
        attempt_row = self.store.query_one(
            """
            SELECT COUNT(*) AS n FROM messages
            WHERE task_id = ?
              AND recipient_agent_id = ?
              AND message_type = ?
              AND status = ?
              AND json_extract(payload, '$.reason') = 'produce_review_verdict'
              AND json_extract(payload, '$.review_id') = ?
            """,
            (
                task_id,
                review.reviewer_agent_id,
                MessageType.NUDGE.value,
                MessageStatus.DELIVERED.value,
                review.id,
            ),
        )
        prior_attempts = int(attempt_row["n"]) if attempt_row else 0
        if prior_attempts >= attempt_count:
            self._retract_default_review(
                review,
                "dispatcher",
                "reviewer_unable_to_produce_verdict_after_%d_attempts" % prior_attempts,
            )
            self.record_log(
                "workflow.default_review.nudge_capped",
                layer="control_plane",
                source="dispatcher",
                level="warning",
                subject_type="task",
                subject_id=task_id,
                detail={
                    "review_id": review.id,
                    "reviewer_agent_id": review.reviewer_agent_id,
                    "attempt_count": prior_attempts,
                    "cap": attempt_count,
                },
            )
            return None
        payload = self._review_verdict_nudge_payload(task_id, review, evidence)
        if self.messaging.has_queued_message(
            recipient_agent_id=review.reviewer_agent_id,
            task_id=task_id,
            message_type=MessageType.NUDGE.value,
            payload_contains=payload,
        ):
            return None
        # Nudge the reviewer so an autonomous review-executor has something to react to.
        return self.send_message(
            "dispatcher",
            review.reviewer_agent_id,
            MessageType.NUDGE.value,
            payload,
            task_id=task_id,
        )

    def _dedupe_same_reviewer_pending_reviews(
        self,
        pending_reviews: List[Review],
        actor: str,
    ) -> List[Review]:
        kept: List[Review] = []
        seen_reviewers: set[str] = set()
        retracted: List[Review] = []
        for review in sorted(pending_reviews, key=lambda item: (item.created_at, item.id)):
            if review.reviewer_agent_id in seen_reviewers:
                self._retract_default_review(
                    review,
                    actor,
                    "duplicate_pending_review_same_reviewer",
                )
                retracted.append(review)
                continue
            seen_reviewers.add(review.reviewer_agent_id)
            kept.append(review)
        if retracted:
            self._record_default_review_observation(
                kept[0].task_id if kept else retracted[0].task_id,
                "workflow.default_review.duplicate_pending_retracted",
                "warning",
                {
                    "retracted_review_ids": [review.id for review in retracted],
                    "kept_review_ids": [review.id for review in kept],
                    "reason": "duplicate_pending_review_same_reviewer",
                },
                actor,
            )
        return kept

    def _find_review_verdict_evidence(
        self,
        task_id: str,
        reviewer_agent_id: str,
        *,
        executor_evidence_id: str,
        verdict_evidence_id: Optional[str] = None,
        not_before: Optional[str] = None,
    ) -> Tuple[Optional[Evidence], List[str]]:
        """Locate the reviewer's signed verdict evidence row, or return
        ``(None, problems)`` if it doesn't exist yet (mac-jqb v1).

        The verdict is a separate Evidence row authored by the reviewer
        (not the executor) with a signed verification manifest of type
        ``review_verdict`` that names the executor's evidence_id.
        Without this row the workflow blocks — it will no longer
        auto-approve in the same process that selected the reviewer.

        Shape required for a valid verdict:
            evidence.metadata.returncode == 0
            evidence.metadata.verification:
                schema = mac.worker_evidence.v1
                status = complete
                evidence_type = review_verdict
                verdict in {approved, rejected}
                reviewed_evidence_id == executor_evidence_id
                signed_by = <reviewer_agent_id>
                signature = <HMAC of manifest under reviewer's key>
        """
        problems: List[str] = []
        reviewed_task = self.get_task(task_id)
        for evidence in reversed(self.list_evidence(task_id)):
            if verdict_evidence_id is not None and evidence.id != verdict_evidence_id:
                continue
            if evidence.created_by != reviewer_agent_id:
                continue
            if not_before is not None:
                try:
                    if parse_time(evidence.created_at) < parse_time(not_before):
                        problems.append(
                            "verdict %s predates review request" % evidence.id
                        )
                        continue
                except ValueError:
                    problems.append("verdict %s has invalid created_at" % evidence.id)
                    continue
            if self._evidence_returncode(evidence) != 0:
                problems.append("verdict evidence %s has nonzero returncode" % evidence.id)
                continue
            manifest = evidence.metadata.get("verification")
            if not isinstance(manifest, dict):
                problems.append("verdict evidence %s missing verification manifest" % evidence.id)
                continue
            if str(manifest.get("evidence_type") or "").strip().lower() != "review_verdict":
                continue  # not a verdict evidence row, skip silently
            if str(manifest.get("schema") or "").strip() != VERIFICATION_SCHEMA:
                problems.append("verdict %s schema mismatch" % evidence.id)
                continue
            if str(manifest.get("status") or "").strip().lower() != "complete":
                problems.append("verdict %s status not complete" % evidence.id)
                continue
            reviewed = str(manifest.get("reviewed_evidence_id") or "").strip()
            if reviewed != executor_evidence_id:
                problems.append(
                    "verdict %s references wrong executor evidence: %s != %s"
                    % (evidence.id, reviewed, executor_evidence_id)
                )
                continue
            signed_by = str(manifest.get("signed_by") or "").strip()
            signature = str(manifest.get("signature") or "").strip()
            if signed_by != reviewer_agent_id:
                problems.append("verdict %s signed_by != reviewer" % evidence.id)
                continue
            key = self._agent_attestation_key(signed_by)
            if key is None:
                problems.append("verdict %s signer has no attestation key" % evidence.id)
                continue
            if not verify_verification_manifest_signature(key, manifest, signature):
                # The signature does not verify against the signer's CURRENT
                # key. Before failing, check whether the key was rotated AFTER
                # this evidence was signed; if so, verify against the retained
                # previous key (the key active at signing time). A routine
                # re-key (e.g. an agent re-keyed after a redeploy) must not
                # invalidate a verdict that was validly signed beforehand
                # (mac-s2vz followup).
                rotation_row = self.store.query_one(
                    "SELECT attestation_key_rotated_at FROM agents WHERE id = ?",
                    (signed_by,),
                )
                rotated_at = rotation_row["attestation_key_rotated_at"] if rotation_row else None
                predates_rotation = False
                if rotated_at and evidence.created_at:
                    try:
                        predates_rotation = parse_time(rotated_at) > parse_time(
                            evidence.created_at
                        )
                    except ValueError:
                        predates_rotation = False
                prev_ok = False
                if predates_rotation:
                    prev_key = self._agent_attestation_prev_key(signed_by)
                    if prev_key is not None:
                        prev_ok = verify_verification_manifest_signature(
                            prev_key, manifest, signature
                        )
                if not prev_ok:
                    if predates_rotation:
                        # Rotated, and the retained previous key is absent
                        # (rotation predates key retention) or also fails:
                        # surface the clear key-rotation error + guidance.
                        problems.append(
                            "verdict %s signed under rotated attestation key "
                            "(rotated_at=%s, evidence created_at=%s); "
                            "the reviewer must re-sign with the current key"
                            % (evidence.id, rotated_at, evidence.created_at)
                        )
                    else:
                        problems.append(
                            "verdict %s signature does not verify" % evidence.id
                        )
                    continue
                # prev_ok: the signature verifies against the key that was
                # active at signing time — accept and fall through to the
                # remaining verdict checks below.
            executor_evidence = self.get_evidence(executor_evidence_id)
            executor_manifest = executor_evidence.metadata.get("verification") or {}
            if not isinstance(executor_manifest, dict):
                problems.append("verdict %s cannot resolve executor verification manifest" % evidence.id)
                continue
            verdict = str(manifest.get("verdict") or "").strip().lower()
            if verdict not in {"approved", "rejected"}:
                problems.append("verdict %s requires verdict approved or rejected" % evidence.id)
                continue
            digest = str(manifest.get("worktree_digest") or "").strip()
            if not re.match(r"^sha256:[0-9a-f]{64}$", digest):
                problems.append("verdict %s requires worktree_digest sha256" % evidence.id)
                continue
            llm_problems = cross_llm_review_problems(
                executor_manifest,
                manifest,
                requirements=review_diversity_requirements(reviewed_task),
            )
            if llm_problems:
                problems.extend(
                    "verdict %s %s" % (evidence.id, problem)
                    for problem in llm_problems
                )
                continue
            # Deterministic finalization can produce a signed, fail-closed
            # rejection even when the reviewer agent never emitted a semantic
            # verdict. That is useful evidence of a harness/protocol failure,
            # but it is not a code-review decision and must never consume an
            # executor attempt as though a reviewer rejected the patch.
            if "semantic_verdict" in manifest:
                semantic_verdict = str(
                    manifest.get("semantic_verdict") or ""
                ).strip().lower()
                if semantic_verdict not in {"approved", "rejected"}:
                    problems.append(
                        "verdict %s semantic verdict is invalid" % evidence.id
                    )
                    continue
            experiment = manifest.get("review_experiment")
            if isinstance(experiment, dict) and experiment.get("blind"):
                protocol = experiment.get("protocol")
                if (
                    not isinstance(protocol, dict)
                    or protocol.get("protocol_compliant") is not True
                ):
                    problems.append(
                        "verdict %s blind review protocol is noncompliant"
                        % evidence.id
                    )
                    continue
            if verdict == "rejected":
                feedback_problems = rejected_verdict_feedback_problems(manifest)
                if feedback_problems:
                    problems.extend(
                        "verdict %s %s" % (evidence.id, problem)
                        for problem in feedback_problems
                    )
                    continue
                return evidence, []
            executor_repo = executor_manifest.get("repo")
            if isinstance(executor_repo, dict):
                repo_problems = self._require_pushed_repo_anchor(manifest)
                if repo_problems:
                    problems.extend("verdict %s %s" % (evidence.id, problem) for problem in repo_problems)
                    continue
                review_repo = manifest.get("repo") if isinstance(manifest.get("repo"), dict) else {}
                executor_changed = _metadata_path_list(executor_repo.get("files_changed"))
                review_changed = _metadata_path_list(review_repo.get("files_changed"))
                if executor_changed and set(review_changed) != set(executor_changed):
                    problems.append(
                        "verdict %s repo.files_changed does not match executor evidence: %s != %s"
                        % (evidence.id, review_changed, executor_changed)
                    )
                    continue
                reviewed_sha = str((manifest.get("repo") or {}).get("head_sha") or "").strip()
                executor_sha = str(executor_repo.get("head_sha") or "").strip()
                if reviewed_sha != executor_sha:
                    problems.append(
                        "verdict %s repo.head_sha does not match executor evidence: %s != %s"
                        % (evidence.id, reviewed_sha, executor_sha)
                    )
                    continue
                # mac-9kij: when the executor's evidence carries a local
                # repo path, recompute ``git rev-parse <head_sha>^{commit}``
                # to confirm the SHA actually exists in that repo. This
                # catches the "reviewer typed back what executor typed,
                # but neither pushed" failure mode for local-path repos.
                # Remote URLs (https/ssh) require network and are left
                # to a future ``git ls-remote`` check.
                #
                # BUT only for UNPUSHED work. Per-lease executor workspaces
                # (repo-lease_<id>) are ephemeral and the sandbox re-inits git
                # in them, so once the commit is pushed its SHA is durably on
                # the remote yet frequently NOT reachable in that local path —
                # producing a false "not reachable" that fails an otherwise
                # publishable review. When repo.pushed is true, the commit's
                # reachability is authoritatively re-checked against origin at
                # publish time (verify_commit: git cat-file -e after fetch
                # origin), so the fragile local-path probe is both redundant
                # and wrong here. Run it only when the work was never pushed.
                repo_local_path = str(executor_repo.get("path") or "").strip()
                if repo_local_path and not executor_repo.get("pushed"):
                    from pathlib import Path as _RPath
                    from subprocess import run as _run, PIPE as _PIPE
                    candidate = _RPath(repo_local_path).expanduser()
                    if candidate.is_dir() and (candidate / ".git").exists():
                        try:
                            check = _run(
                                ["git", "rev-parse", "--verify",
                                 "%s^{commit}" % executor_sha],
                                cwd=str(candidate),
                                stdout=_PIPE,
                                stderr=_PIPE,
                                timeout=10,
                            )
                        except Exception:  # noqa: BLE001 - tooling missing → skip
                            check = None
                        if check is not None and check.returncode != 0:
                            problems.append(
                                "verdict %s executor head_sha %s not reachable in %s"
                                % (evidence.id, executor_sha, candidate)
                            )
                            continue
            if self._passed_verification_check_count(manifest) < 1:
                problems.append("verdict %s requires at least one independent passing check" % evidence.id)
                continue
            integration_problems = self._cooperative_review_integration_problems(
                reviewed_task, manifest
            )
            if integration_problems:
                problems.extend(
                    "verdict %s %s" % (evidence.id, problem)
                    for problem in integration_problems
                )
                continue
            codegraph_manifest = dict(manifest)
            if isinstance(executor_manifest.get("repo"), dict):
                review_repo = manifest.get("repo") if isinstance(manifest.get("repo"), dict) else {}
                codegraph_manifest["repo"] = {
                    **review_repo,
                    "files_changed": executor_manifest["repo"].get("files_changed") or [],
                }
            codegraph_problems = codegraph_audit_manifest_problems(codegraph_manifest)
            if codegraph_problems:
                problems.extend("verdict %s %s" % (evidence.id, problem) for problem in codegraph_problems)
                continue
            return evidence, []
        return None, problems

    def _review_attempt_protocol_failure(
        self,
        task_id: str,
        review: Review,
        *,
        executor_evidence_id: str,
    ) -> Tuple[Optional[Evidence], str]:
        """Return the review-attempt evidence proving harness/protocol failure.

        Review execution evidence carries the review and executor-evidence IDs
        even when no valid verdict manifest was produced. Keep this separate
        from semantic rejection so the workflow can retract the failed
        reviewer assignment and let selection try a different eligible peer.
        """
        for evidence in reversed(self.list_evidence(task_id)):
            if evidence.created_by != review.reviewer_agent_id:
                continue
            try:
                if parse_time(evidence.created_at) < parse_time(review.created_at):
                    continue
            except ValueError:
                continue
            metadata = ensure_json_object(evidence.metadata)
            if str(metadata.get("review_id") or "").strip() != review.id:
                continue
            if (
                str(metadata.get("executor_evidence_id") or "").strip()
                != executor_evidence_id
            ):
                continue
            if self._evidence_returncode(evidence) != 0:
                return evidence, "review_executor_nonzero"
            manifest = ensure_json_object(metadata.get("verification"))
            if (
                str(manifest.get("evidence_type") or "").strip().lower()
                != "review_verdict"
            ):
                continue
            if str(manifest.get("semantic_verdict") or "").strip().lower() not in {
                "approved",
                "rejected",
            }:
                return evidence, "semantic_verdict_invalid"
            experiment = ensure_json_object(manifest.get("review_experiment"))
            if experiment.get("blind"):
                protocol = ensure_json_object(experiment.get("protocol"))
                if protocol.get("protocol_compliant") is not True:
                    return evidence, "blind_protocol_noncompliant"
        return None, ""

    def _cooperative_review_integration_problems(
        self, task: Task, verdict_manifest: JsonDict
    ) -> List[str]:
        coordination = ensure_json_object(
            ensure_json_object(task.metadata).get("coordination")
        )
        if coordination.get("phase") != "integration":
            return []
        child_outputs = coordination.get("child_outputs", [])
        expected = {
            str(item.get("executor_evidence_id") or "").strip()
            for item in child_outputs
            if isinstance(item, dict)
            and str(item.get("executor_evidence_id") or "").strip()
        }
        missing_outputs = [
            str(item.get("task_id") or "unknown").strip()
            for item in child_outputs
            if not isinstance(item, dict)
            or str(item.get("status") or "").strip() != "ready"
            or not str(item.get("executor_evidence_id") or "").strip()
            or not str(ensure_json_object(item.get("repo")).get("head_sha") or "").strip()
        ]
        integration = ensure_json_object(verdict_manifest.get("integration"))
        required = set(
            _metadata_string_list(integration.get("required_child_evidence_ids"))
        )
        verified = set(
            _metadata_string_list(integration.get("verified_child_evidence_ids"))
        )
        problems: List[str] = []
        if integration.get("status") != "pass":
            problems.append("cooperative integration verification must pass")
        if missing_outputs:
            problems.append(
                "cooperative integration has incomplete child outputs: %s"
                % ", ".join(sorted(set(missing_outputs)))
            )
        if not expected:
            problems.append("cooperative integration has no child evidence targets")
        if required != expected:
            problems.append(
                "cooperative integration required child evidence does not match task inputs"
            )
        if verified != expected:
            problems.append(
                "cooperative integration did not verify every child commit as an ancestor"
            )
        return problems

    def _verdict_value(self, evidence: Evidence) -> str:
        manifest = evidence.metadata.get("verification") or {}
        verdict = str(manifest.get("verdict") or "").strip().lower()
        # Fail closed: an unknown/malformed verdict must NOT auto-approve.
        return verdict if verdict in {"approved", "rejected"} else "rejected"

    def _retract_default_review(self, review: Review, actor: str, reason: str) -> None:
        now = utcnow()
        self.store.execute(
            """
            UPDATE reviews
            SET status = ?, reason = ?, completed_at = ?
            WHERE id = ? AND status = ?
            """,
            (
                ReviewStatus.RETRACTED.value,
                reason,
                now,
                review.id,
                ReviewStatus.PENDING.value,
            ),
        )
        self._record_history(
            review.task_id,
            "task.review_retracted",
            actor,
            None,
            None,
            {
                "review_id": review.id,
                "reviewer_agent_id": review.reviewer_agent_id,
                "reason": reason,
            },
        )

    def _select_default_reviewer(
        self,
        task: Task,
        *,
        executor_agent_id: Optional[str] = None,
        excluded_agent_ids: Optional[Iterable[str]] = None,
        allow_independence_fallback: bool = False,
    ) -> Optional[Agent]:
        """Pick a default reviewer for ``task``.

        Trust boundaries enforced here (autonomous-review context where
        there is no human in the loop):

        * Tenancy (mac-dyk): the reviewer's persona tenant_id must
          match the task's tenant. Without a human to catch a misroute,
          the tenancy boundary IS the safety boundary.
        * Capability (mac-s1a): ``review`` capability is *required*,
          not preferred. An agent without it cannot be drafted.
        * Persona separation / anti-collusion (mac-v2i): the reviewer's
          persona slug must differ from the executor's persona slug.
          Two code-reviewer-souled agents cannot approve each other's
          work — the second-eyes role only matters if it's a different
          eye.
        * Never an executor for this task: current and prior lease owners,
          plus the latest evidence author, are excluded. Small fleets wait
          for genuinely independent review rather than weakening the gate.
        """
        task_tenant = self._task_tenant_id(task)
        executor_persona_slug = self._task_executor_persona_slug(task)
        review_policy = self._default_review_policy(task)
        review_required_capabilities = self._default_review_required_capabilities(
            task,
            review_policy,
        )

        excluded = {str(value) for value in (excluded_agent_ids or []) if str(value)}
        candidates: List[Agent] = []
        access_states: Dict[str, str] = {}
        independence_penalties: Dict[str, int] = {}
        for agent in self.list_agents():
            if agent.id in excluded:
                continue
            reason = self._default_reviewer_unavailable_reason(
                task,
                agent,
                task_tenant=task_tenant,
                executor_persona_slug=executor_persona_slug,
                executor_agent_id=executor_agent_id,
                review_policy=review_policy,
                review_required_capabilities=review_required_capabilities,
            )
            if (
                reason is not None
                and allow_independence_fallback
                and reason in REVIEWER_INDEPENDENCE_REASONS
                and self._reviewer_independence_fallback_enabled(task)
            ):
                reason = self._default_reviewer_unavailable_reason(
                    task,
                    agent,
                    task_tenant=task_tenant,
                    executor_persona_slug=executor_persona_slug,
                    executor_agent_id=executor_agent_id,
                    review_policy=review_policy,
                    review_required_capabilities=review_required_capabilities,
                    allow_independence_fallback=True,
                )
            if reason is not None:
                continue
            candidates.append(agent)
            access_states[agent.id] = self._reviewer_repository_access_state(
                task,
                agent.id,
            )[0]
            independence_penalties[agent.id] = self._reviewer_independence_penalty(
                task, agent, executor_agent_id
            )
        if not candidates:
            return None
        candidates.sort(
            key=lambda agent: (
                independence_penalties.get(agent.id, 0),
                0 if access_states.get(agent.id) == "success" else 1,
                0 if agent.status == AgentStatus.IDLE.value else 1,
                agent.name,
                agent.id,
            )
        )
        return candidates[0]

    def _ensure_hub_review_verifier_agent(
        self, task: Task, *, actor: str
    ) -> Optional[Agent]:
        if not _hub_review_verify_enabled():
            return None
        if not _truthy_env("MAC_HUB_REVIEWER_AUTO_REGISTER", "1"):
            return None
        assignment = ensure_json_object(
            ensure_json_object(task.metadata).get("review_experiment")
        )
        if assignment.get("schema") == "mac.review_experiment.v1":
            return None
        name = (
            os.environ.get("MAC_HUB_REVIEWER_AGENT_NAME", "").strip()
            or DEFAULT_HUB_REVIEWER_AGENT_NAME
        )
        agent_id = (
            os.environ.get("MAC_HUB_REVIEWER_AGENT_ID", "").strip()
            or DEFAULT_HUB_REVIEWER_AGENT_ID
        )
        machine_id = (
            os.environ.get("MAC_HUB_REVIEWER_MACHINE_ID", "").strip()
            or DEFAULT_HUB_REVIEWER_MACHINE_ID
        )
        try:
            machine = self.register_machine(
                "operator-review",
                labels={
                    "source": "mac-hub-review-verifier",
                    "role": "hub-reviewer",
                    "virtual": True,
                },
                resources={"virtual": True, "review": {"mode": "hub_verify"}},
                trusted=True,
                machine_id=machine_id,
            )
            return self.register_agent(
                machine.id,
                name,
                capabilities=["review"],
                resources={
                    "virtual": True,
                    "hub_review_verifier": {
                        "schema": HUB_REVIEW_VERIFIER_RESOURCE_SCHEMA,
                        "enabled": True,
                        "mode": "hub_verify",
                    },
                },
                agent_id=agent_id,
                actor=actor,
            )
        except Exception as exc:  # noqa: BLE001 - verifier setup must not break review sweeps.
            self.observability.record_log(
                "workflow.default_review.hub_reviewer_register_failed",
                level="warning",
                layer="control_plane",
                source="default-review-workflow",
                subject_type="agent",
                subject_id=agent_id,
                detail={"actor": actor, "error": str(exc)[:300]},
            )
            return None

    def _agent_is_hub_review_verifier(self, agent: Agent) -> bool:
        marker = ensure_json_object(
            ensure_json_object(agent.resources).get("hub_review_verifier")
        )
        return (
            marker.get("schema") == HUB_REVIEW_VERIFIER_RESOURCE_SCHEMA
            and marker.get("enabled") is not False
        )

    def _default_reviewer_unavailable_reason_for_id(
        self,
        task: Task,
        reviewer_agent_id: str,
        *,
        executor_agent_id: Optional[str] = None,
        allow_conditional_independence_fallback: bool = False,
    ) -> Optional[str]:
        try:
            agent = self.get_agent(reviewer_agent_id)
        except NotFoundError:
            return "reviewer_missing"
        reason = self._default_reviewer_unavailable_reason(
            task,
            agent,
            executor_agent_id=executor_agent_id,
            review_policy=self._default_review_policy(task),
        )
        if (
            allow_conditional_independence_fallback
            and reason in REVIEWER_INDEPENDENCE_REASONS
            and self._reviewer_independence_fallback_reason(
                task, agent, executor_agent_id=executor_agent_id
            )
        ):
            return None
        return reason

    def _default_reviewer_unavailable_reason(
        self,
        task: Task,
        agent: Agent,
        *,
        task_tenant: Optional[str] = None,
        executor_persona_slug: Optional[str] = None,
        executor_agent_id: Optional[str] = None,
        review_policy: Optional[JsonDict] = None,
        review_required_capabilities: Optional[Iterable[str]] = None,
        allow_independence_fallback: bool = False,
    ) -> Optional[str]:
        if (
            agent.id in self._coordination_excluded_agent_ids(task)
            and not allow_independence_fallback
        ):
            return "reviewer_cooperative_family_participant"
        if agent.health_status != HealthStatus.HEALTHY.value:
            return "reviewer_unhealthy"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return "reviewer_not_available"
        if (
            metadata_declares_read_only_report_repository(task.metadata)
            and not agent_has_read_only_report_repository_executor(agent.resources)
        ):
            return "reviewer_report_repository_executor_missing"
        hub_review_verifier = (
            _hub_review_verify_enabled()
            and self._agent_is_hub_review_verifier(agent)
        )
        if (
            not hub_review_verifier
            and not self._agent_seen_recently(agent, self._default_reviewer_stale_after_seconds())
        ):
            return "reviewer_stale"
        if (
            self.reviews.agent_has_owned_task(task.id, agent.id)
            and not allow_independence_fallback
        ):
            return "reviewer_previously_owned_task"
        if (
            executor_agent_id is not None
            and agent.id == executor_agent_id
            and not allow_independence_fallback
        ):
            return "reviewer_created_executor_evidence"
        if "review" not in set(agent.capabilities):
            return "reviewer_missing_capability"
        policy = review_policy if review_policy is not None else self._default_review_policy(task)
        target_agent_id = str(
            policy.get("target_agent_id")
            or policy.get("reviewer_agent_id")
            or ""
        ).strip()
        if target_agent_id and agent.id != target_agent_id:
            return "reviewer_not_target_agent"
        target_agent_name = str(
            policy.get("target_agent_name")
            or policy.get("reviewer_agent_name")
            or ""
        ).strip()
        if target_agent_name and agent.name != target_agent_name:
            return "reviewer_not_target_agent"
        required = set(
            review_required_capabilities
            if review_required_capabilities is not None
            else self._default_review_required_capabilities(task, policy)
        )
        missing = sorted(required - set(agent.capabilities))
        if missing:
            return "reviewer_missing_capabilities:%s" % ",".join(missing)
        if task_tenant is None:
            task_tenant = self._task_tenant_id(task)
        if executor_persona_slug is None:
            executor_persona_slug = self._task_executor_persona_slug(task)
        agent_tenant, agent_persona_slug = self._agent_tenant_and_persona(agent)
        if task_tenant is not None:
            if agent_tenant is None:
                # Headless worker (no hermes_instance_id => no persona
                # tenant). Persona-boundary tenancy fails closed for these
                # agents, which would park every tenant-scoped Hermes task
                # forever in needs_review. Fall back to the hardware
                # boundary — the same gate the executor path uses
                # (_agent_available_for) — so a headless reviewer on a
                # machine whose tenant policy permits the task's tenant
                # stays eligible, while one on a disallowed machine is
                # still refused.
                try:
                    machine = self.get_machine(agent.machine_id)
                except NotFoundError:
                    return "reviewer_wrong_tenant"
                if not self._machine_allows_tenant(machine, task_tenant):
                    return "reviewer_wrong_tenant"
            elif agent_tenant != task_tenant:
                return "reviewer_wrong_tenant"
        if (
            executor_persona_slug is not None
            and agent_persona_slug is not None
            and agent_persona_slug == executor_persona_slug
            and not allow_independence_fallback
        ):
            return "reviewer_same_persona"
        if hub_review_verifier:
            return None
        access_state, learning = self._reviewer_repository_access_state(task, agent.id)
        if access_state == "failure":
            host = str((learning or {}).get("repository_host") or "unknown")
            failure_class = str(
                (learning or {}).get("failure_class") or "authentication"
            )
            return "reviewer_repository_access_%s:%s" % (failure_class, host)
        return None

    def _reviewer_independence_fallback_enabled(self, task: Task) -> bool:
        # Repository reports are conclusions drawn from observed source rather
        # than mechanically integrated code. Their executor cannot also serve
        # as the independent check on those conclusions.
        if metadata_declares_read_only_report_repository(task.metadata):
            return False
        policy = self._default_review_policy(task)
        return not (
            policy.get("require_independent_reviewer") is True
            or policy.get("allow_independence_fallback") is False
            or review_diversity_requirements(task).get("high_risk") is True
        )

    def _reviewer_independence_penalty(
        self,
        task: Task,
        agent: Agent,
        executor_agent_id: Optional[str],
    ) -> int:
        penalty = 0
        if agent.id in self._coordination_excluded_agent_ids(task):
            penalty += 1
        executor_persona = self._task_executor_persona_slug(task)
        _tenant, reviewer_persona = self._agent_tenant_and_persona(agent)
        if (
            executor_persona is not None
            and reviewer_persona is not None
            and executor_persona == reviewer_persona
        ):
            penalty += 1
        if self.reviews.agent_has_owned_task(task.id, agent.id):
            penalty += 4
        if executor_agent_id is not None and agent.id == executor_agent_id:
            penalty += 4
        return penalty

    def _reviewer_independence_fallback_reason(
        self,
        task: Task,
        reviewer: Agent,
        *,
        executor_agent_id: Optional[str] = None,
        excluded_agent_ids: Optional[Iterable[str]] = None,
    ) -> Optional[str]:
        """Authorize independence relaxation only when no strict peer exists."""
        if not self._reviewer_independence_fallback_enabled(task):
            return None
        effective_excluded = {
            str(agent_id)
            for agent_id in (excluded_agent_ids or [])
            if str(agent_id)
        }
        evidence, _assessment = self._bound_review_evidence(task)
        if evidence is not None:
            effective_excluded.update(
                str(row["reviewer_agent_id"])
                for row in self.store.query_all(
                    "SELECT reviewer_agent_id FROM reviews "
                    "WHERE task_id = ? AND status = ? AND created_at >= ? "
                    "AND reason LIKE 'reviewer_protocol_failure:%'",
                    (
                        task.id,
                        ReviewStatus.RETRACTED.value,
                        evidence.created_at or "",
                    ),
                )
            )
        if reviewer.id in effective_excluded:
            return None
        resolved_executor = (
            executor_agent_id
            if executor_agent_id is not None
            else self.reviews.latest_executor_evidence_author(task.id)
        )
        strict_reason = self._default_reviewer_unavailable_reason(
            task,
            reviewer,
            executor_agent_id=resolved_executor,
            review_policy=self._default_review_policy(task),
        )
        if strict_reason not in REVIEWER_INDEPENDENCE_REASONS:
            return None
        relaxed_reason = self._default_reviewer_unavailable_reason(
            task,
            reviewer,
            executor_agent_id=resolved_executor,
            review_policy=self._default_review_policy(task),
            allow_independence_fallback=True,
        )
        if relaxed_reason is not None:
            return None
        if self._select_default_reviewer(
            task,
            executor_agent_id=resolved_executor,
            excluded_agent_ids=effective_excluded,
        ) is not None:
            return None
        return strict_reason

    def _reviewer_repository_access_state(
        self,
        task: Task,
        reviewer_agent_id: str,
    ) -> Tuple[str, Optional[JsonDict]]:
        remote = task_repository_remote(task)
        host = repository_host(remote)
        if not host or host == "local":
            return "unknown", None
        try:
            failure_cooldown = max(
                0,
                int(
                    os.environ.get(
                        "MAC_REPOSITORY_ACCESS_FAILURE_COOLDOWN_SECONDS",
                        "1800",
                    )
                ),
            )
        except ValueError:
            failure_cooldown = 1800
        try:
            success_ttl = max(
                0,
                int(
                    os.environ.get(
                        "MAC_REPOSITORY_ACCESS_SUCCESS_TTL_SECONDS",
                        "86400",
                    )
                ),
            )
        except ValueError:
            success_ttl = 86400
        records = self.memory.search_memory(
            subject_type="agent",
            subject_id=reviewer_agent_id,
            record_type=REPOSITORY_ACCESS_RECORD_TYPE,
            limit=50,
            order="desc",
        )
        state, learning = repository_access_state(
            records,
            project=task.project or "default",
            host=host,
            operation="review_clone",
            failure_cooldown_seconds=failure_cooldown,
            success_ttl_seconds=success_ttl,
        )
        return state, learning

    def _default_reviewer_stale_after_seconds(self) -> int:
        raw = (
            os.environ.get("MAC_DEFAULT_REVIEWER_STALE_AFTER_SECONDS", "").strip()
            or os.environ.get("MAC_AGENT_STALE_AFTER_SECONDS", "").strip()
        )
        if not raw:
            return 300
        try:
            return max(1, int(raw))
        except ValueError:
            return 300

    def _agent_seen_recently(self, agent: Agent, stale_after_seconds: int) -> bool:
        try:
            seen_at = parse_time(agent.last_seen_at)
            now = parse_time(utcnow())
        except Exception:  # noqa: BLE001 - malformed timestamps should fail closed.
            return False
        if seen_at.tzinfo is None and now.tzinfo is not None:
            now = now.replace(tzinfo=None)
        if seen_at.tzinfo is not None and now.tzinfo is None:
            seen_at = seen_at.replace(tzinfo=None)
        return (now - seen_at).total_seconds() <= max(1, int(stale_after_seconds))

    def _agent_tenant_and_persona(self, agent: Agent) -> Tuple[Optional[str], Optional[str]]:
        """Return ``(tenant_id, persona_slug)`` for an agent, both
        optional. Used by the reviewer-selection guards (tenancy +
        anti-collusion). Agents without a hermes_instance_id have
        neither and are treated as ineligible by the reviewer picker
        when the task is tenant-scoped."""
        if not agent.hermes_instance_id:
            return None, None
        try:
            instance = self.identity.get_hermes_instance(agent.hermes_instance_id)
        except NotFoundError:
            return None, None
        if not instance.persona_id:
            return instance.tenant_id, None
        try:
            persona = self.identity.get_persona(instance.persona_id)
        except NotFoundError:
            return instance.tenant_id, None
        slug = persona.name.strip().lower().replace(" ", "-").replace("_", "-") or None
        return instance.tenant_id, slug

    def _reviewer_assignment_problem(
        self, task: Task, reviewer: Agent
    ) -> Optional[str]:
        """Apply the same complete eligibility policy to every assignment path."""
        executor_agent_id = self.reviews.latest_executor_evidence_author(task.id)
        reason = self._default_reviewer_unavailable_reason(
            task,
            reviewer,
            executor_agent_id=executor_agent_id,
            review_policy=self._default_review_policy(task),
        )
        if (
            reason in REVIEWER_INDEPENDENCE_REASONS
            and self._reviewer_independence_fallback_reason(
                task, reviewer, executor_agent_id=executor_agent_id
            )
        ):
            return None
        if reason is None:
            return None
        readable = {
            "reviewer_same_persona": "reviewer and executor use the same persona",
            "reviewer_wrong_tenant": "reviewer is outside the task tenant boundary",
            "reviewer_report_repository_executor_missing": (
                "reviewer lacks the controller-verified per-task OpenShell report executor"
            ),
            "reviewer_cooperative_family_participant": (
                "reviewer executed another task in the same cooperative work family"
            ),
        }
        return readable.get(reason, reason.replace("_", " "))

    def _reviewer_independence_problem(
        self, task: Task, reviewer: Agent
    ) -> Optional[str]:
        """Compatibility form of the former independence-only policy."""
        if reviewer.id in self._coordination_excluded_agent_ids(task):
            return "reviewer executed another task in the same cooperative work family"
        task_tenant = self._task_tenant_id(task)
        reviewer_tenant, reviewer_persona = self._agent_tenant_and_persona(reviewer)
        if task_tenant is not None:
            if reviewer_tenant is None:
                try:
                    machine = self.get_machine(reviewer.machine_id)
                except NotFoundError:
                    return "reviewer machine is missing"
                if not self._machine_allows_tenant(machine, task_tenant):
                    return "reviewer is outside the task tenant boundary"
            elif reviewer_tenant != task_tenant:
                return "reviewer is outside the task tenant boundary"
        executor_persona = self._task_executor_persona_slug(task)
        if (
            executor_persona is not None
            and reviewer_persona is not None
            and executor_persona == reviewer_persona
        ):
            return "reviewer and executor use the same persona"
        return None

    def _task_executor_persona_slug(self, task: Task) -> Optional[str]:
        """Find the persona slug of whichever agent owned the task last
        (the executor). Used by anti-collusion. Returns None when the
        task has no recorded owner — in that case no executor-side
        persona constraint applies."""
        executor_agent_id: Optional[str] = task.owner_agent_id
        if executor_agent_id is None:
            # Look for the last lease against this task — it identifies
            # the executor even after submit-for-review releases owner.
            row = self.store.query_one(
                """
                SELECT agent_id FROM leases
                WHERE task_id = ?
                ORDER BY created_at DESC, id DESC
                LIMIT 1
                """,
                (task.id,),
            )
            if row is not None:
                executor_agent_id = row["agent_id"]
        if executor_agent_id is None:
            return None
        try:
            executor = self.get_agent(executor_agent_id)
        except NotFoundError:
            return None
        _, slug = self._agent_tenant_and_persona(executor)
        return slug

    def _default_publication_target(self, task: Task) -> Optional[str]:
        """Resolve the publication target from task metadata or return None.

        Returns ``None`` when no operator-set target is available
        (mac-w29). Previously this synthesized ``mac://tasks/{id}`` which
        is filler — no resolver exists for that URI. The auto-review
        workflow now treats ``None`` as "no publication destination
        configured; leave the task in REVIEWING and emit a waiting
        observability event."
        """
        metadata = task.metadata
        report_deliverable = metadata_declares_report_deliverable(metadata)

        def eligible(target: str) -> bool:
            return not (report_deliverable and target.startswith("git://"))

        for key in ("publication_target", "publish_target"):
            value = metadata.get(key)
            if isinstance(value, str) and value.strip() and eligible(value.strip()):
                return value.strip()
        publication = metadata.get("publication")
        if isinstance(publication, dict):
            target = publication.get("target")
            if isinstance(target, str) and target.strip() and eligible(target.strip()):
                return target.strip()
        acc_metadata = metadata.get("acc_metadata")
        if isinstance(acc_metadata, dict):
            beads_id = acc_metadata.get("beads_id")
            if isinstance(beads_id, str) and beads_id.strip():
                return "beads://%s" % beads_id.strip()
        # Fall back to the task's registered project metadata so an
        # operator can configure a single publication target per project
        # (e.g. for autonomous coding tasks that all complete the same
        # way) instead of stamping every task individually.
        project_target = self._project_publication_target(task)
        if project_target and eligible(project_target):
            return project_target
        # Fleet-wide default (opt-in): when set, routine approved tasks publish
        # via this target and auto-complete instead of parking in REVIEWING for
        # want of a per-task/per-project destination. Unset => unchanged (mac-w29
        # hold). e.g. MAC_DEFAULT_PUBLICATION_TARGET=git://main
        #
        # A *git* fleet-default only applies where the HUB can actually publish
        # (origin pins a clonable url, or a hub-local repository_path exists);
        # applying it to a non-publishable task would raise in the git publish
        # (_publish_git_target_if_needed) and block the task. Non-git defaults
        # apply to all.
        fleet_default = (os.environ.get("MAC_DEFAULT_PUBLICATION_TARGET") or "").strip()
        if fleet_default and (
            not fleet_default.startswith("git://") or self._task_git_publishable(task)
        ):
            return fleet_default
        return None

    def _task_git_publishable(self, task: Task) -> bool:
        """True if a git publish/merge can be attempted for this task — i.e. it is
        a repo task (origin pins a repo url/path, or a repository_contract). The
        publish resolves a hub-usable repo from origin.repository_url, a hub-local
        origin.repository_path, or the remote the worker pushed to (from the
        evidence), so a repo task need not have a hub-local path. Non-repo
        (operator) tasks return False so a git fleet-default never blocks them."""
        metadata = ensure_json_object(task.metadata)
        if metadata_declares_report_deliverable(metadata):
            return False
        origin = ensure_json_object(metadata.get("origin"))
        if str(origin.get("repository_url") or "").strip():
            return True
        if str(origin.get("repository_path") or "").strip():
            return True
        contract = ensure_json_object(origin.get("repository_contract"))
        return bool(
            str(contract.get("project") or "").strip()
            or str(contract.get("canonical_remote_url") or "").strip()
        )

    def _project_publication_target(self, task: Task) -> Optional[str]:
        project_name = str(getattr(task, "project", "") or "").strip()
        if not project_name:
            return None
        try:
            record = self.get_project_record(project_name)
        except NotFoundError:
            return None
        meta = ensure_json_object(record.metadata)
        for key in ("publication_target", "publish_target"):
            value = meta.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        publication = meta.get("publication")
        if isinstance(publication, dict):
            target = publication.get("target")
            if isinstance(target, str) and target.strip():
                return target.strip()
        return None

    def _record_default_review_observation(
        self,
        task_id: str,
        name: str,
        level: str,
        detail: JsonDict,
        actor: str,
    ) -> None:
        self.observability.record_log(
            name,
            level=level,
            layer="control_plane",
            source="default-review-workflow",
            subject_type="task",
            subject_id=task_id,
            detail={"actor": actor, **detail},
        )

    def _record_project_failure_lesson(
        self,
        task_id: str,
        *,
        evidence_type: str,
        error_signature: str,
        signals: Optional[JsonDict] = None,
        evidence_id: Optional[str] = None,
    ) -> None:
        """Persist a hub-side, project-scoped ``mac.deployment_learning.v1``
        failure lesson so the next execution run on this project recalls it.

        The executor records deployment lessons for failed *runs*, but review
        rejections and hub-side terminal failures produced no lesson — so the
        fleet never learned from rejected or force-failed work. The record
        shape matches the executor's ``build_learning_record`` so
        ``recall_deployment_lessons`` renders and injects it unchanged.
        Best-effort: telemetry-only, never breaks the caller.
        """
        try:
            task = self.get_task(task_id)
        except Exception:  # noqa: BLE001 - lesson recording must not break the workflow.
            return
        try:
            project = self._hermes_task_project_key(task) or (task.project or "unassigned")
            metadata = ensure_json_object(task.metadata)
            origin = metadata.get("origin") if isinstance(metadata, dict) else {}
            repo_name = str(origin.get("repository_name") or "") if isinstance(origin, dict) else ""
            content = {
                "schema": "mac.deployment_learning.v1",
                "task_id": task.id,
                "task_title": task.title,
                "project": project,
                "repository": repo_name,
                "evidence_type": evidence_type,
                "outcome": "failure",
                "signals": signals or {},
                "error_signature": error_signature or "",
                "at": utcnow(),
            }
            self.add_memory(
                task_id=task.id,
                subject_type="project",
                subject_id=project,
                # Matches the executor's DEPLOYMENT_LEARNING_PREFIX contract so
                # recall_deployment_lessons (which filters by this record_type
                # prefix + project) picks it up.
                record_type="deployment_learning:%s" % project,
                content=json_dumps(content),
                evidence_id=evidence_id,
                created_by="mac-hub-review",
            )
        except Exception:  # noqa: BLE001 - best-effort durable learning.
            import logging

            logging.getLogger(__name__).warning(
                "could not record project failure lesson for %s", task_id, exc_info=True
            )

    def _set_agent_idle(self, agent_id: str, conn: Any = None) -> None:
        now = utcnow()
        writer = conn if conn is not None else self.store
        writer.execute(
            "UPDATE agents SET status = ?, current_task_id = NULL, updated_at = ? WHERE id = ?",
            (AgentStatus.IDLE.value, now, agent_id),
        )

    def _agent_has_active_lease(self, agent_id: str) -> bool:
        row = self.store.query_one(
            """
            SELECT 1 FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
            LIMIT 1
            """,
            (agent_id, LeaseStatus.ACTIVE.value, agent_id),
        )
        return row is not None

    def _agent_active_lease_count(self, agent_id: str) -> int:
        row = self.store.query_one(
            """
            SELECT COUNT(*) AS count FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
            """,
            (agent_id, LeaseStatus.ACTIVE.value, agent_id),
        )
        return int(row["count"] if row is not None else 0)

    def _agent_capacity(self, agent: Agent) -> int:
        for key in ("capacity", "max_concurrent_tasks"):
            value = agent.resources.get(key)
            if value is not None:
                return max(1, int(value))
        return 1

    # --- service-role election (media-01) -------------------------------

    def _agent_eligible_for_service(self, agent: Agent, role: ServiceRole) -> bool:
        """Capability + hardware fit (uses reported GPU hw + the catalog VRAM
        floor). Capacity is checked separately in the sync loop."""
        if not set(role.required_capabilities).issubset(set(agent.capabilities or [])):
            return False
        hw = agent.resources.get("hardware") if isinstance(agent.resources, dict) else None
        if role.hardware_requirements:
            from mac.roles_service import machine_hardware_satisfies

            ok, _reasons = machine_hardware_satisfies(role.hardware_requirements, hw or {})
            if not ok:
                return False
        if role.model_id:
            try:
                from mac.local_gen_catalog import get_model, models_for_hardware

                model = get_model(role.model_id)
                if model is not None and model not in models_for_hardware(hw):
                    return False
            except Exception:  # noqa: BLE001 - catalog is optional
                pass
        return True

    @staticmethod
    def _agent_service_claim_eligibility_reason(agent: Agent) -> Optional[str]:
        """Return the durable agent-state fence blocking service-role claims."""

        if agent.deleted_at:
            return "agent_decommissioned"
        if agent.dispatch_hold:
            return "agent_dispatch_held"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return "agent_status_unavailable"
        if agent.health_status != HealthStatus.HEALTHY.value:
            return "agent_health_unavailable"
        return None

    def _service_holder_live(self, agent_id: str) -> bool:
        try:
            agent = self.get_agent(agent_id)
        except Exception:  # noqa: BLE001
            return False
        return self._agent_service_claim_eligibility_reason(agent) is None

    def sync_agent_service_claims(
        self, agent_id: str, willing_ops: Iterable[str], *, lease_seconds: int = 1800
    ) -> JsonDict:
        """A capable host declares the ops it's willing+able to run; the hub
        renews its still-willing held ops, releases ones it no longer wants, and
        claims new eligible ops up to the agent's capacity (so ops spread to
        hosts with headroom). Returns the authoritative held-op set.

        Self-driving: worker syncs (every ~30s) seed desired roles + reap stale
        claims, so the subsystem doesn't depend on a periodic /dispatch/tick."""
        self._ensure_service_roles_seeded()
        self.service_roles.expire_service_claims()
        willing = {str(op).strip() for op in (willing_ops or []) if str(op).strip()}
        with self.store.transaction() as conn:
            # Global lock order for agent-owned state is agent row first, then
            # the agent's service claims.  This is the same first fence used by
            # decommissioning and credential lifecycle operations.  On SQLite,
            # BEGIN IMMEDIATE serializes the writer; on PostgreSQL the no-op
            # UPDATE retains a row lock until this transaction commits.
            locked = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if locked.rowcount != 1:
                row = conn.execute(
                    "SELECT deleted_at FROM agents WHERE id = ?", (agent_id,)
                ).fetchone()
                if row is None:
                    raise NotFoundError("agent not found: %s" % agent_id)
                raise ValidationError(
                    "agent %s was decommissioned at %s"
                    % (agent_id, row["deleted_at"])
                )
            agent_row = conn.execute(
                "SELECT * FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            agent = self._agent_from_row(agent_row)
            capacity = self._agent_capacity(agent)

            role_rows = conn.execute(
                "SELECT * FROM service_roles "
                "WHERE enabled = 1 AND tenant_id IS NULL ORDER BY id"
            ).fetchall()
            roles_by_op: Dict[str, ServiceRole] = {}
            for row in role_rows:
                role = self.service_roles._role_from_row(row)
                roles_by_op.setdefault(role.op, role)

            # Lock this agent's active claims only after its eligibility row.
            # Every release, renewal and acquisition below uses this same
            # connection, closing the stale GET -> separate write TOCTOU.
            conn.execute(
                "UPDATE service_claims SET updated_at = updated_at "
                "WHERE agent_id = ? AND status = ?",
                (agent_id, ServiceClaimStatus.ACTIVE.value),
            )
            claim_rows = conn.execute(
                "SELECT c.*, r.op AS role_op FROM service_claims c "
                "LEFT JOIN service_roles r ON r.id = c.service_role_id "
                "WHERE c.agent_id = ? AND c.status = ? ORDER BY c.id",
                (agent_id, ServiceClaimStatus.ACTIVE.value),
            ).fetchall()

            blocked_reason = self._agent_service_claim_eligibility_reason(agent)
            if blocked_reason is not None:
                # A held/draining/unhealthy worker is not merely denied new
                # claims: any old advertisement is withdrawn in this same
                # eligibility transaction and therefore cannot be renewed.
                conn.execute(
                    "UPDATE service_claims SET status = ?, updated_at = ? "
                    "WHERE agent_id = ? AND status = ?",
                    (
                        ServiceClaimStatus.RELEASED.value,
                        utcnow(),
                        agent_id,
                        ServiceClaimStatus.ACTIVE.value,
                    ),
                )
                return {
                    "held": [],
                    "managed": sorted(roles_by_op.keys()),
                    "capacity": capacity,
                    "eligible": False,
                    "eligibility_reason": blocked_reason,
                }

            held_ops: Dict[str, Any] = {}
            now = utcnow()
            for claim in claim_rows:
                op = str(claim["role_op"] or "")
                if (
                    not op
                    or op in held_ops
                    or op not in willing
                    or op not in roles_by_op
                ):
                    conn.execute(
                        "UPDATE service_claims SET status = ?, updated_at = ? "
                        "WHERE id = ? AND agent_id = ? AND status = ?",
                        (
                            ServiceClaimStatus.RELEASED.value,
                            now,
                            claim["id"],
                            agent_id,
                            ServiceClaimStatus.ACTIVE.value,
                        ),
                    )
                    continue
                held_ops[op] = claim

            expires_at = (
                parse_time(now) + timedelta(seconds=int(lease_seconds))
            ).isoformat()
            for op, claim in list(held_ops.items()):
                renewed = conn.execute(
                    "UPDATE service_claims SET expires_at = ?, updated_at = ? "
                    "WHERE id = ? AND agent_id = ? AND status = ?",
                    (
                        expires_at,
                        now,
                        claim["id"],
                        agent_id,
                        ServiceClaimStatus.ACTIVE.value,
                    ),
                )
                if renewed.rowcount != 1:
                    del held_ops[op]

            active_lease_row = conn.execute(
                "SELECT COUNT(*) AS count FROM leases l "
                "JOIN tasks t ON t.lease_id = l.id "
                "WHERE l.agent_id = ? AND l.status = ? "
                "AND t.owner_agent_id = ?",
                (agent_id, LeaseStatus.ACTIVE.value, agent_id),
            ).fetchone()
            load = len(held_ops) + int(
                active_lease_row["count"] if active_lease_row is not None else 0
            )
            candidates = [
                op
                for op in willing
                if op not in held_ops and op in roles_by_op and roles_by_op[op].enabled
            ]
            holder_counts = {
                str(row["service_role_id"]): int(row["count"])
                for row in conn.execute(
                    "SELECT service_role_id, COUNT(*) AS count "
                    "FROM service_claims WHERE status = ? "
                    "GROUP BY service_role_id",
                    (ServiceClaimStatus.ACTIVE.value,),
                ).fetchall()
            }

            for op in sorted(
                candidates,
                key=lambda value: (holder_counts.get(roles_by_op[value].id, 0), value),
            ):
                if load >= capacity:
                    break
                role = roles_by_op[op]
                if not self._agent_eligible_for_service(agent, role):
                    continue
                claim_id = new_id("sclaim")
                conn.execute(
                    "INSERT INTO service_claims ("
                    "id, service_role_id, agent_id, status, expires_at, "
                    "created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?) "
                    "ON CONFLICT DO NOTHING",
                    (
                        claim_id,
                        role.id,
                        agent_id,
                        ServiceClaimStatus.ACTIVE.value,
                        expires_at,
                        now,
                        now,
                    ),
                )
                active = conn.execute(
                    "SELECT id FROM service_claims "
                    "WHERE service_role_id = ? AND agent_id = ? AND status = ?",
                    (role.id, agent_id, ServiceClaimStatus.ACTIVE.value),
                ).fetchone()
                if active is None:
                    continue
                held_ops[op] = active
                holder_counts[role.id] = holder_counts.get(role.id, 0) + 1
                load += 1

            # "managed" = ops that have a service_role (election active). Ops
            # not managed remain advertised unconditionally for compatibility.
            return {
                "held": sorted(held_ops.keys()),
                "managed": sorted(roles_by_op.keys()),
                "capacity": capacity,
                "eligible": True,
                "eligibility_reason": None,
            }

    def _ensure_service_roles_seeded(self) -> None:
        """Idempotently seed the desired ops from MAC_SERVICE_ROLE_OPS (opt-in;
        unset = no election). Driven by both worker syncs and the tick."""
        ops_env = (os.environ.get("MAC_SERVICE_ROLE_OPS") or "").strip()
        if not ops_env:
            return
        wanted = [o.strip() for o in ops_env.split(",") if o.strip()]
        existing = {r.op for r in self.service_roles.desired_services(tenant_id=None)}
        if any(o not in existing for o in wanted):
            self.seed_service_roles(wanted)

    def reconcile_service_roles(self) -> JsonDict:
        """Periodic (called from tick): seed desired ops from MAC_SERVICE_ROLE_OPS
        (opt-in; unset = no election, agents advertise as before), expire silent/
        overloaded holders, drop offline holders, and emit a provisioning demand
        signal for any desired op with zero live holders ("the cluster needs a
        <op> agent")."""
        self._ensure_service_roles_seeded()
        expired = self.service_roles.expire_service_claims()
        requested: List[str] = []
        for role in self.service_roles.desired_services(tenant_id=None):
            live = [
                c for c in self.service_roles.list_active_claims(role_id=role.id)
                if self._service_holder_live(c.agent_id)
            ]
            for claim in self.service_roles.list_active_claims(role_id=role.id):
                if not self._service_holder_live(claim.agent_id):
                    self.service_roles.release_service_claim(claim.id, reason="holder_offline")
            if not live:
                try:
                    self.provisioning.request_agent(
                        reason="service_role:%s" % role.slug,
                        capabilities=role.required_capabilities,
                        hardware=role.hardware_requirements,
                        detail={"op": role.op, "model_id": role.model_id},
                        requested_by="service-role-reconciler",
                    )
                    requested.append(role.op)
                except Exception:  # noqa: BLE001 - demand signal is best-effort
                    pass
        return {"expired": len(expired), "requested": requested}

    def seed_service_roles(self, ops: Iterable[Any]) -> int:
        """Idempotently seed/enable a desired service_role per op. Each op is a
        dict {op, model_id, capabilities?} or a bare op string (model from the
        catalog)."""
        from mac.local_gen_catalog import LOCAL_GEN_MODELS

        by_op_default = {}
        for m in LOCAL_GEN_MODELS:
            if m.routable:
                by_op_default.setdefault(m.op, m.id)
        count = 0
        for spec in ops:
            if isinstance(spec, dict):
                op = str(spec.get("op") or "").strip()
                model_id = spec.get("model_id") or by_op_default.get(op)
                caps = spec.get("capabilities") or ["gpu"]
            else:
                op = str(spec).strip()
                model_id = by_op_default.get(op)
                caps = ["gpu"]
            if not op:
                continue
            self.service_roles.upsert_role(op, model_id=model_id, required_capabilities=caps)
            count += 1
        return count

    def _task_tenant_id(self, task: Task) -> Optional[str]:
        origin = task.metadata.get("origin")
        if isinstance(origin, dict) and origin.get("tenant_id"):
            return str(origin["tenant_id"])
        tenant_id = task.metadata.get("tenant_id")
        return str(tenant_id) if tenant_id else None

    def _machine_allows_tenant(self, machine: Machine, tenant_id: Optional[str]) -> bool:
        policy = machine.labels.get("tenant_policy") or {}
        if not isinstance(policy, dict):
            return True
        mode = str(policy.get("mode", "shared"))
        allowed = set(policy.get("tenant_ids") or policy.get("allow_tenants") or [])
        denied = set(policy.get("deny_tenants") or [])
        if mode == "denied":
            return False
        if tenant_id is None:
            return mode != "private"
        if tenant_id in denied:
            return False
        if mode == "private":
            return tenant_id in allowed
        if allowed:
            return tenant_id in allowed
        return True

    def _agent_resources_satisfy(self, agent: Agent, machine: Machine, task: Task) -> bool:
        required = task.metadata.get("resources") or task.metadata.get("required_resources") or {}
        if isinstance(required, dict):
            available = dict(machine.resources)
            available.update(agent.resources)
            for key, needed in required.items():
                current = available.get(key)
                if isinstance(needed, (int, float)):
                    if current is None or float(current) < float(needed):
                        return False
                elif isinstance(needed, list):
                    if not set(needed).issubset(set(current or [])):
                        return False
                elif needed is not None and current != needed:
                    return False
        # Structured hardware constraints on the task (set by the workflow
        # runtime when spawning a role-bound node task). Falls through the
        # shared matcher so the role-required-hardware vocabulary stays in
        # one place.
        hw_required = task.metadata.get("hardware") if isinstance(task.metadata, dict) else None
        if isinstance(hw_required, dict) and hw_required:
            from mac.roles_service import machine_hardware_satisfies

            ok, _reasons = machine_hardware_satisfies(hw_required, machine.hardware)
            if not ok:
                return False
        return True

    def _expire_agent_active_leases(self, agent_id: str, timestamp: str, reason: str) -> None:
        liveness_loss = reason in {"heartbeat_offline", "agent_update_offline"}
        rows = self.store.query_all(
            """
            SELECT
                l.id AS lease_id,
                l.task_id AS task_id,
                t.state AS task_state,
                t.attempt_count AS attempt_count,
                t.max_attempts AS max_attempts
            FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
            ORDER BY l.created_at, l.id
            """,
            (agent_id, LeaseStatus.ACTIVE.value, agent_id),
        )
        if not rows:
            return
        # Do not maintain a second, weaker expiry implementation here.  An
        # offline event may force an otherwise clock-live lease to EXPIRED and
        # refund its attempt, but durable finalizer ownership, persisted
        # decision, package repair receipt, WIP handling, task detach, and node
        # transition must all run through the same resumable path as the normal
        # sweeper.
        for row in rows:
            if liveness_loss:
                next_state = TaskState.OPEN.value
            elif row["attempt_count"] >= row["max_attempts"]:
                next_state = TaskState.FAILED.value
            else:
                next_state = TaskState.OPEN.value
            attempt_count_after = max(
                0,
                int(row["attempt_count"]) - (1 if liveness_loss else 0),
            )
            detail = {
                "lease_id": row["lease_id"],
                "agent_id": agent_id,
                "reason": reason,
                "failure_class": "environment" if liveness_loss else "work",
                "attempt_refunded": liveness_loss,
                "attempt_count_before": int(row["attempt_count"]),
                "attempt_count_after": attempt_count_after,
            }
            decision = {
                "schema": "mac.lease_expiry_decision.v1",
                "lease_id": row["lease_id"],
                "task_id": row["task_id"],
                "target_state": next_state,
                "reset_attempt_count": False,
                "attempt_count_after": attempt_count_after,
                "detail": detail,
            }
            lease_row = self.store.query_one(
                "SELECT * FROM leases WHERE id = ?",
                (row["lease_id"],),
            )
            if lease_row is None:
                continue
            try:
                self._expire_lease_row(
                    lease_row,
                    force_expire=True,
                    decision_override=decision,
                )
            except Exception as exc:  # noqa: BLE001 - isolate one stale assignment.
                try:
                    self.record_log(
                        "lease.recovery.failed",
                        layer="control_plane",
                        source="dispatcher",
                        level="error",
                        subject_type="lease",
                        subject_id=str(row["lease_id"]),
                        detail={
                            "lease_id": str(row["lease_id"]),
                            "reason": reason,
                            "error": str(exc),
                        },
                    )
                except Exception:
                    pass
        for row in rows:
            # Self-documenting: a lease expiry means the agent stopped heartbeating
            # mid-task (offline / crash / long synchronous op like a big clone).
            # Record the cause + remediation on the task (visible in `mac task
            # show`/`summary`) whether it was requeued (OPEN) or failed out. The
            # BLOCKED target arg only selects the matching note text.
            try:
                diag = _failure_diagnosis(TaskState.BLOCKED.value, {"reason": reason})
                if diag:
                    self.append_task_activity(row["task_id"], "diagnosis", "dispatcher", diag)
            except Exception:  # noqa: BLE001 - advisory only
                pass
